var G = window.G || (window.G = {});
G.ROOMS = G.ROOMS || {};
G.ROOMS["zh-l048"] = {"id":"zh-l048","lang":"zh","level":3,"no":48,"teacher":"wang","title":"HSK3 · Bài 48 · 亲戚和邻居 Họ hàng và hàng xóm","intro":["我爷爷奶奶住在南方。","Bài 48: Gọi đúng vai vế họ hàng, xưng hô với người lạ, và dùng 自己 để nói \"chính mình\". Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ yéye nǎinai zhù zài nánfāng.","gram":{"t":"自己 — chính mình","b":"Chủ ngữ + 自己 + động từ · danh từ + 自己的","d":"自己 đặt ngay sau chủ ngữ để nhấn mạnh \"tự làm lấy\". Cũng dùng làm sở hữu: 我自己的房间 (phòng của riêng tôi). Không cần chia theo ngôi như tiếng Anh (myself/yourself).","ex":[["我自己做饭。","Tôi tự nấu cơm.","Wǒ zìjǐ zuòfàn."],["这是我自己的自行车。","Đây là xe đạp của riêng tôi.","Zhè shì wǒ zìjǐ de zìxíngchē."],["你自己去还是我们一起去？","Bạn tự đi hay chúng ta cùng đi?","Nǐ zìjǐ qù háishi wǒmen yìqǐ qù?"]]},"grams":[{"t":"自己 — chính mình","b":"Chủ ngữ + 自己 + động từ · danh từ + 自己的","d":"自己 đặt ngay sau chủ ngữ để nhấn mạnh \"tự làm lấy\". Cũng dùng làm sở hữu: 我自己的房间 (phòng của riêng tôi). Không cần chia theo ngôi như tiếng Anh (myself/yourself).","ex":[["我自己做饭。","Tôi tự nấu cơm.","Wǒ zìjǐ zuòfàn."],["这是我自己的自行车。","Đây là xe đạp của riêng tôi.","Zhè shì wǒ zìjǐ de zìxíngchē."],["你自己去还是我们一起去？","Bạn tự đi hay chúng ta cùng đi?","Nǐ zìjǐ qù háishi wǒmen yìqǐ qù?"]]},{"t":"Gọi người lạ bằng từ họ hàng","b":"阿姨 · 叔叔 · 爷爷 · 奶奶 · 哥哥 · 姐姐","d":"Đây là điểm văn hoá giống hệt tiếng Việt: người Trung Quốc gọi người lạ theo VAI VẾ họ hàng chứ không gọi \"ông/bà\" chung chung. Người trạc tuổi bố mẹ là 叔叔/阿姨, người già là 爷爷/奶奶, người hơn mình chút là 哥哥/姐姐.","ex":[["阿姨，多少钱？","Cô ơi, bao nhiêu tiền ạ?","Āyí, duōshao qián?"],["叔叔，谢谢您！","Chú ơi, cháu cảm ơn chú!","Shūshu, xièxie nín!"]]},{"t":"Nội và ngoại phân biệt bằng chữ 外","b":"爷爷/奶奶 bên nội · 外公/外婆 bên ngoại","d":"外 nghĩa là \"ngoại\". Người Việt cũng nói \"ông nội / ông ngoại\" — cùng một cách tư duy về dòng họ. Đây là chỗ người phương Tây học rất vất vả còn người Việt hiểu ngay.","ex":[["这是我爷爷，那是我外公。","Đây là ông nội tôi, kia là ông ngoại tôi.","Zhè shì wǒ yéye, nà shì wǒ wàigōng."]]}],"items":[{"zh":"阿姨","py":"āyí","vi":"dì, cô (chị em của mẹ); cô (gọi phụ nữ trung niên)","hv":"a di","note":"Ở Trung Quốc, gọi một phụ nữ lạ trạc tuổi mẹ mình là 阿姨 — lịch sự và thân thiện, giống \"cô\" tiếng Việt.","ex":"这位阿姨是我妈妈的同事。","exPy":"Zhè wèi āyí shì wǒ māma de tóngshì.","exVi":"Cô này là đồng nghiệp của mẹ tôi.","w":"这 位 阿姨 是 我 妈妈 的 同事。"},{"zh":"叔叔","py":"shūshu","vi":"chú (em trai của bố); chú (gọi đàn ông trung niên)","hv":"thúc thúc","note":"Tiếng Việt có \"thúc bá\" (chú bác) trong từ Hán Việt. Cặp 叔叔 / 阿姨 dùng để gọi người lạ trạc tuổi bố mẹ.","ex":"叔叔，请问这儿有座位吗？","exPy":"Shūshu, qǐngwèn zhèr yǒu zuòwèi ma?","exVi":"Chú ơi, cho hỏi ở đây còn chỗ không ạ?","w":"叔叔， 请问 这儿 有 座位 吗？"},{"zh":"爷爷","py":"yéye","vi":"ông nội","hv":"gia gia","note":"Chỉ dùng cho ông NỘI. Ông ngoại là 外公 wàigōng — chữ 外 (ngoại) giống hệt cách phân biệt của tiếng Việt.","ex":"我爷爷奶奶住在南方。","exPy":"Wǒ yéye nǎinai zhù zài nánfāng.","exVi":"Ông bà nội tôi sống ở miền Nam.","w":"我 爷爷 奶奶 住 在 南方。"},{"zh":"奶奶","py":"nǎinai","vi":"bà nội","hv":"nãi nãi","note":"奶 có bộ 女 và vốn nghĩa là sữa. Bà ngoại là 外婆 wàipó.","ex":"奶奶每天早上去公园锻炼。","exPy":"Nǎinai měi tiān zǎoshang qù gōngyuán duànliàn.","exVi":"Sáng nào bà nội cũng ra công viên tập thể dục.","w":"奶奶 每 天 早上 去 公园 锻炼。"},{"zh":"邻居","py":"línjū","vi":"hàng xóm","hv":"lân cư","note":"Tiếng Việt: \"lân cận\", \"láng giềng\". 居 = \"cư\" trong \"cư trú\", \"dân cư\".","ex":"我的邻居有两个孩子。","exPy":"Wǒ de línjū yǒu liǎng ge háizi.","exVi":"Hàng xóm tôi có hai đứa con.","w":"我 的 邻居 有 两 个 孩子。"},{"zh":"客人","py":"kèrén","vi":"khách","hv":"khách nhân","note":"客 chính là \"khách\" tiếng Việt (\"khách sạn\", \"hành khách\", \"khách quan\").","ex":"今天晚上有客人来。","exPy":"Jīntiān wǎnshang yǒu kèrén lái.","exVi":"Tối nay có khách đến.","w":"今天 晚上 有 客人 来。"},{"zh":"别人","py":"biéren","vi":"người khác","hv":"biệt nhân","note":"别 (khác) + 人 (người). Chữ thứ hai đọc nhẹ. Đừng nhầm với 别 bié (đừng) ở bài 27.","ex":"别人的事，我们别管。","exPy":"Biéren de shì, wǒmen bié guǎn.","exVi":"Chuyện người khác, ta đừng xen vào.","w":"别人 的 事， 我们 别 管。"},{"zh":"自己","py":"zìjǐ","vi":"chính mình, tự mình","hv":"tự kỷ","note":"Chính là \"tự kỷ\" tiếng Việt (自 tự + 己 kỷ), nhưng nghĩa gốc chỉ đơn giản là BẢN THÂN, không mang nghĩa bệnh lý.","ex":"我自己一个人来的。","exPy":"Wǒ zìjǐ yí ge rén lái de.","exVi":"Tôi tự đến một mình.","w":"我 自己 一 个人 来 的。"},{"zh":"年轻","py":"niánqīng","vi":"trẻ, trẻ tuổi","hv":"niên khinh","note":"年 (năm, tuổi) + 轻 (nhẹ) — tuổi còn nhẹ. Cách ghép chữ rất hình tượng.","ex":"他比我年轻五岁。","exPy":"Tā bǐ wǒ niánqīng wǔ suì.","exVi":"Anh ấy trẻ hơn tôi năm tuổi.","w":"他 比 我 年轻 五 岁。"},{"zh":"老","py":"lǎo","vi":"già; cũ; lâu năm","hv":"lão","note":"Tiếng Việt: \"lão\", \"lão làng\". Đã gặp trong 老师 (bài 1) — ở đó 老 mang nghĩa kính trọng chứ không phải \"già\".","ex":"这本词典太老了。","exPy":"Zhè běn cídiǎn tài lǎo le.","exVi":"Quyển từ điển này cũ quá rồi.","w":"这 本 词典 太 老 了。"}],"newChars":["阿","姨","叔","爷","邻","居","己","轻"],"outro":"很好！Xong bài 48."};
G.ROOMS["zh-l049"] = {"id":"zh-l049","lang":"zh","level":3,"no":49,"teacher":"wang","title":"HSK3 · Bài 49 · 身体和长相 Cơ thể và ngoại hình","intro":["他个子很高，也很瘦。","Bài 49: Gọi tên các bộ phận cơ thể, tả người cao thấp béo gầy — và thấy rõ sức mạnh của bộ thủ. Bấm 1 · Học để bắt đầu."],"introPy":"Tā gèzi hěn gāo, yě hěn shòu.","gram":{"t":"Bộ 月 (thịt) — chìa khoá của mọi chữ về cơ thể","b":"脸 · 腿 · 脚 · 胖 · 脑 · 肚","d":"Nhắc lại bài bộ thủ: 月 bên TRÁI một chữ hầu như luôn là 肉 (thịt), không phải mặt trăng. Nhìn thấy nó là đoán ngay chữ nói về cơ thể. Cả bài này là ví dụ sống động.","ex":[["脸","mặt","liǎn"],["腿","chân","tuǐ"],["脚","bàn chân","jiǎo"]]},"grams":[{"t":"Bộ 月 (thịt) — chìa khoá của mọi chữ về cơ thể","b":"脸 · 腿 · 脚 · 胖 · 脑 · 肚","d":"Nhắc lại bài bộ thủ: 月 bên TRÁI một chữ hầu như luôn là 肉 (thịt), không phải mặt trăng. Nhìn thấy nó là đoán ngay chữ nói về cơ thể. Cả bài này là ví dụ sống động.","ex":[["脸","mặt","liǎn"],["腿","chân","tuǐ"],["脚","bàn chân","jiǎo"]]},{"t":"Tả người: chủ đề kép","b":"Người + bộ phận + tính từ","d":"Tiếng Trung hay dùng cấu trúc \"chủ đề kép\": 他个子很高 nghĩa đen là \"anh ấy, vóc người rất cao\". Nêu người trước, rồi nêu đặc điểm — giống tiếng Việt nói \"anh ấy dáng người cao\".","ex":[["他个子很高。","Anh ấy dáng cao.","Tā gèzi hěn gāo."],["她头发很长。","Cô ấy tóc rất dài.","Tā tóufa hěn cháng."],["这个孩子眼睛很大。","Đứa bé này mắt rất to.","Zhège háizi yǎnjing hěn dà."]]},{"t":"有点儿 và 一点儿 — khác nhau chỗ nào?","b":"有点儿 + tính từ (chê) · tính từ + 一点儿 (so sánh)","d":"有点儿 đứng TRƯỚC tính từ và luôn mang ý CHÊ, không hài lòng: 有点儿贵 (hơi đắt quá). Còn 一点儿 đứng SAU và chỉ là so sánh trung tính: 便宜一点儿 (rẻ hơn chút). Đây là lỗi rất phổ biến.","ex":[["这件衣服有点儿瘦。","Bộ đồ này hơi chật. (chê)","Zhè jiàn yīfu yǒudiǎnr shòu."],["我想要大一点儿的。","Tôi muốn cái to hơn chút. (so sánh)","Wǒ xiǎng yào dà yìdiǎnr de."]]}],"items":[{"zh":"鼻子","py":"bízi","vi":"cái mũi","hv":"tỵ tử","note":"鼻 có bộ 自 ở trên — mà 自 vốn là hình CÁI MŨI (người Trung Quốc chỉ vào mũi khi nói \"tôi\").","ex":"他的鼻子和眼睛像爸爸。","exPy":"Tā de bízi hé yǎnjing xiàng bàba.","exVi":"Mũi và mắt cậu ấy giống bố.","w":"他 的 鼻子 和 眼睛 像 爸爸。"},{"zh":"耳朵","py":"ěrduo","vi":"cái tai","hv":"nhĩ đoá","note":"耳 là bộ thủ bạn đã học. Tiếng Việt: \"nhĩ khoa\", \"thính nhĩ\". Chữ thứ hai đọc nhẹ.","ex":"我的耳朵听不清楚。","exPy":"Wǒ de ěrduo tīng bu qīngchu.","exVi":"Tai tôi nghe không rõ.","w":"我 的 耳朵 听 不 清楚。"},{"zh":"嘴","py":"zuǐ","vi":"cái miệng","hv":"chuỷ","note":"Có bộ 口 (miệng) bên trái. 口 là bộ thủ, còn 嘴 là từ dùng hằng ngày để chỉ cái miệng.","ex":"医生说：请张开嘴。","exPy":"Yīshēng shuō: qǐng zhāng kāi zuǐ.","exVi":"Bác sĩ nói: xin há miệng ra.","w":"医生 说： 请 张 开 嘴。"},{"zh":"脸","py":"liǎn","vi":"khuôn mặt","hv":"kiểm","note":"Bên trái là 月 — nhưng đây là 肉 (thịt) chứ không phải mặt trăng, đúng như đã học ở phần bộ thủ.","ex":"洗完脸就吃饭吧。","exPy":"Xǐ wán liǎn jiù chīfàn ba.","exVi":"Rửa mặt xong thì ăn cơm nhé.","w":"洗 完 脸 就 吃 饭 吧。"},{"zh":"头发","py":"tóufa","vi":"tóc","hv":"đầu phát","note":"头 (đầu) + 发 (tóc). Tiếng Việt: \"đầu\", \"phát\" trong \"lý phát\" (cắt tóc). Chữ thứ hai đọc nhẹ.","ex":"她的头发又黑又长。","exPy":"Tā de tóufa yòu hēi yòu cháng.","exVi":"Tóc cô ấy vừa đen vừa dài.","w":"她 的 头发 又 黑 又 长。"},{"zh":"腿","py":"tuǐ","vi":"chân, đùi","hv":"thoái","note":"Cũng có bộ 月 (thịt) bên trái — như mọi bộ phận cơ thể. Chỉ phần từ hông xuống bàn chân.","ex":"我的腿有点儿疼。","exPy":"Wǒ de tuǐ yǒudiǎnr téng.","exVi":"Chân tôi hơi đau.","w":"我 的 腿 有点儿 疼。"},{"zh":"脚","py":"jiǎo","vi":"bàn chân","hv":"cước","note":"Tiếng Việt: \"cước\" trong \"nhân cước\", \"cước bộ\". Cũng có bộ 月 (thịt). 腿 là cả cái chân, 脚 chỉ bàn chân.","ex":"这双鞋对我的脚太小了。","exPy":"Zhè shuāng xié duì wǒ de jiǎo tài xiǎo le.","exVi":"Đôi giày này nhỏ quá so với chân tôi.","w":"这 双 鞋 对 我 的 脚 太 小 了。"},{"zh":"个子","py":"gèzi","vi":"vóc người, chiều cao","hv":"cá tử","note":"Chuyên dùng để nói chiều cao của NGƯỜI: 个子高 (cao), 个子矮 (thấp). Đồ vật thì không dùng 个子.","ex":"他个子很高，也很瘦。","exPy":"Tā gèzi hěn gāo, yě hěn shòu.","exVi":"Anh ấy cao và gầy.","w":"他 个子 很 高， 也 很 瘦。"},{"zh":"胖","py":"pàng","vi":"béo, mập","hv":"bàn","note":"Bộ 月 (thịt) + 半. Chỉ dùng cho NGƯỜI và động vật. Nói đồ ăn nhiều mỡ thì dùng 肥 féi.","ex":"我最近胖了三公斤。","exPy":"Wǒ zuìjìn pàng le sān gōngjīn.","exVi":"Dạo này tôi tăng ba cân.","w":"我 最近 胖 了 三 公斤。"},{"zh":"瘦","py":"shòu","vi":"gầy; (quần áo) chật","hv":"sấu","note":"Có bộ 疒 (bệnh tật) bao ngoài — người xưa coi gầy quá là có bệnh. Nói về quần áo thì 瘦 nghĩa là chật.","ex":"她太瘦了。","exPy":"Tā tài shòu le.","exVi":"Cô ấy gầy quá.","w":"她 太 瘦 了。"}],"newChars":["鼻","耳","朵","嘴","脸","头","腿","脚","胖","瘦"],"outro":"很好！Xong bài 49."};
G.ROOMS["zh-l050"] = {"id":"zh-l050","lang":"zh","level":3,"no":50,"teacher":"wang","title":"HSK3 · Bài 50 · 我不舒服 Ốm đau và cảm giác","intro":["我今天不太舒服。","Bài 50: Kể triệu chứng với bác sĩ, và dùng 了 để báo hiệu tình trạng đã thay đổi. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ jīntiān bú tài shūfu.","gram":{"t":"了 báo hiệu TÌNH TRẠNG ĐÃ THAY ĐỔI","b":"tính từ / động từ + 了","d":"Khác với 了 chỉ việc hoàn thành ở bài 8, chữ 了 cuối câu ở đây nghĩa là \"đã trở nên…\". 我饿了 = trước không đói, giờ đói rồi. Đây là cách dùng 了 quan trọng thứ hai.","ex":[["我饿了。","Tôi đói rồi. (trước chưa đói)","Wǒ è le."],["他感冒了。","Cậu ấy bị cảm rồi.","Tā gǎnmào le."],["天气冷了。","Trời lạnh rồi.","Tiānqì lěng le."]]},"grams":[{"t":"了 báo hiệu TÌNH TRẠNG ĐÃ THAY ĐỔI","b":"tính từ / động từ + 了","d":"Khác với 了 chỉ việc hoàn thành ở bài 8, chữ 了 cuối câu ở đây nghĩa là \"đã trở nên…\". 我饿了 = trước không đói, giờ đói rồi. Đây là cách dùng 了 quan trọng thứ hai.","ex":[["我饿了。","Tôi đói rồi. (trước chưa đói)","Wǒ è le."],["他感冒了。","Cậu ấy bị cảm rồi.","Tā gǎnmào le."],["天气冷了。","Trời lạnh rồi.","Tiānqì lěng le."]]},{"t":"Nói chỗ nào đau: bộ phận + 疼","b":"Người + bộ phận cơ thể + 疼","d":"Không cần chữ \"bị\" hay giới từ nào cả. 我头疼 nghĩa đen là \"tôi, đầu đau\" — lại là cấu trúc chủ đề kép của bài 32.","ex":[["我头疼。","Tôi đau đầu.","Wǒ tóu téng."],["他肚子疼。","Cậu ấy đau bụng.","Tā dùzi téng."],["我嗓子疼，还发烧。","Tôi đau họng, còn sốt nữa.","Wǒ sǎngzi téng, hái fāshāo."]]},{"t":"Bộ 疒 và bộ 饣 — đoán nghĩa không cần từ điển","b":"疒 = bệnh tật · 饣 = ăn uống","d":"疼 (đau), 病 (bệnh), 瘦 (gầy) đều có 疒. 饿 (đói), 饱 (no), 饭 (cơm), 馆 (quán) đều có 饣. Gặp chữ lạ mang hai bộ này, bạn đã đoán được nửa nghĩa.","ex":[["疼 · 病 · 瘦","đều thuộc nhóm ốm đau","téng · bìng · shòu"],["饿 · 饱 · 饭 · 馆","đều thuộc nhóm ăn uống","è · bǎo · fàn · guǎn"]]}],"items":[{"zh":"感冒","py":"gǎnmào","vi":"cảm, cảm cúm","hv":"cảm mạo","note":"Chính là \"cảm mạo\" tiếng Việt. Là ĐỘNG TỪ nên nói 我感冒了, không nói 我有感冒.","ex":"我感冒了，还有点儿发烧。","exPy":"Wǒ gǎnmào le, hái yǒudiǎnr fāshāo.","exVi":"Tôi bị cảm, còn hơi sốt nữa.","w":"我 感冒 了， 还 有点儿 发烧。"},{"zh":"发烧","py":"fāshāo","vi":"sốt","hv":"phát thiêu","note":"发 (phát ra) + 烧 (đốt, có bộ 火 lửa) — người nóng lên như bị đốt. Cũng là động từ ly hợp.","ex":"他发烧了。","exPy":"Tā fāshāo le.","exVi":"Cậu ấy bị sốt rồi.","w":"他 发烧 了。"},{"zh":"疼","py":"téng","vi":"đau","hv":"đông","note":"Bộ 疒 (bệnh tật) bao ngoài — nhìn bộ này là biết chữ nói về ốm đau. Nói bộ phận nào đau: 头疼, 肚子疼.","ex":"哪儿疼？","exPy":"Nǎr téng?","exVi":"Đau chỗ nào?","w":"哪儿 疼？"},{"zh":"舒服","py":"shūfu","vi":"dễ chịu, thoải mái","hv":"thư phục","note":"舒 = \"thư\" trong \"thư giãn\", \"thư thái\". 不舒服 là cách nói \"trong người khó chịu\" — câu đầu tiên bạn nói khi đi khám.","ex":"我今天不太舒服。","exPy":"Wǒ jīntiān bú tài shūfu.","exVi":"Hôm nay tôi thấy hơi khó chịu.","w":"我 今天 不 太 舒服。"},{"zh":"健康","py":"jiànkāng","vi":"sức khoẻ; khoẻ mạnh","hv":"kiện khang","note":"Tiếng Việt có \"kiện tráng\", \"khang kiện\". Vừa là danh từ (sức khoẻ) vừa là tính từ (khoẻ mạnh).","ex":"身体健康比什么都重要。","exPy":"Shēntǐ jiànkāng bǐ shénme dōu zhòngyào.","exVi":"Sức khoẻ quan trọng hơn mọi thứ.","w":"身体 健康 比 什么 都 重要。"},{"zh":"检查","py":"jiǎnchá","vi":"kiểm tra, khám","hv":"kiểm tra","note":"Chính là \"kiểm tra\" tiếng Việt. Dùng cả cho khám bệnh lẫn soát lại bài làm.","ex":"医生给我检查了一下。","exPy":"Yīshēng gěi wǒ jiǎnchá le yíxià.","exVi":"Bác sĩ khám cho tôi một chút.","w":"医生 给 我 检查 了 一下。"},{"zh":"饿","py":"è","vi":"đói","hv":"ngạ","note":"Bộ 饣 (thức ăn) bên trái. Tiếng Việt: \"ngạ quỷ\" (quỷ đói) trong Phật giáo.","ex":"我饿了，我们去吃饭吧。","exPy":"Wǒ è le, wǒmen qù chīfàn ba.","exVi":"Tôi đói rồi, đi ăn cơm đi.","w":"我 饿 了， 我们 去 吃 饭 吧。"},{"zh":"渴","py":"kě","vi":"khát","hv":"khát","note":"Chính là chữ \"khát\" tiếng Việt. Bộ 氵 (nước) bên trái. Đừng nhầm với 喝 hē (uống) — chỉ khác bộ.","ex":"我渴了，想喝水。","exPy":"Wǒ kě le, xiǎng hē shuǐ.","exVi":"Tôi khát rồi, muốn uống nước.","w":"我 渴 了， 想 喝 水。"},{"zh":"饱","py":"bǎo","vi":"no","hv":"bão","note":"Cũng có bộ 饣 (thức ăn). Cặp 饿 / 饱 đi liền nhau như \"đói / no\".","ex":"谢谢，我吃饱了。","exPy":"Xièxie, wǒ chī bǎo le.","exVi":"Cảm ơn, tôi ăn no rồi.","w":"谢谢， 我 吃 饱 了。"},{"zh":"矮","py":"ǎi","vi":"thấp (người, vật)","hv":"ải","note":"Trái nghĩa với 高. Dùng cho người và vật thấp; còn 低 dī (bài 52) dùng cho độ cao, giá cả, âm thanh.","ex":"这张桌子太矮了。","exPy":"Zhè zhāng zhuōzi tài ǎi le.","exVi":"Cái bàn này thấp quá.","w":"这 张 桌子 太 矮 了。"}],"newChars":["冒","烧","疼","舒","健","康","检","查","饿","渴","饱","矮"],"outro":"很好！Xong bài 50."};
G.ROOMS["zh-l051"] = {"id":"zh-l051","lang":"zh","level":3,"no":51,"teacher":"wang","title":"HSK3 · Bài 51 · 心情 Cảm xúc","intro":["别着急，慢慢来。","Bài 51: Nói ra cảm xúc, và khám phá \"gia đình chữ 心\" — nhóm chữ về lòng dạ con người. Bấm 1 · Học để bắt đầu."],"introPy":"Bié zháojí, mànman lái.","gram":{"t":"Gia đình chữ 心 — mọi cảm xúc đều có trái tim","b":"心 đứng dưới · 忄 đứng bên trái","d":"着急, 担心, 小心, 放心, 害怕, 想, 意, 忙, 快 — nhìn thấy 心 hay 忄 là biết chữ nói về LÒNG DẠ. Người Trung Quốc coi tim là nơi suy nghĩ, không phải não; tiếng Việt cũng nói \"nghĩ trong lòng\", \"để bụng\".","ex":[["担心 · 小心 · 放心","gánh lòng · giữ lòng · đặt lòng xuống","dānxīn · xiǎoxīn · fàngxīn"],["怕 · 忙 · 快 · 想","đều mang bộ 忄","pà · máng · kuài · xiǎng"]]},"grams":[{"t":"Gia đình chữ 心 — mọi cảm xúc đều có trái tim","b":"心 đứng dưới · 忄 đứng bên trái","d":"着急, 担心, 小心, 放心, 害怕, 想, 意, 忙, 快 — nhìn thấy 心 hay 忄 là biết chữ nói về LÒNG DẠ. Người Trung Quốc coi tim là nơi suy nghĩ, không phải não; tiếng Việt cũng nói \"nghĩ trong lòng\", \"để bụng\".","ex":[["担心 · 小心 · 放心","gánh lòng · giữ lòng · đặt lòng xuống","dānxīn · xiǎoxīn · fàngxīn"],["怕 · 忙 · 快 · 想","đều mang bộ 忄","pà · máng · kuài · xiǎng"]]},{"t":"对 … 满意 / 生气 — nêu đối tượng của cảm xúc","b":"对 + người/việc + cảm xúc","d":"对 duì ở đây nghĩa là \"đối với\". Cả cụm đứng TRƯỚC tính từ, giống quy tắc của 在 và 给. Nói 我满意对这个 là sai.","ex":[["我对这个结果很满意。","Tôi rất hài lòng với kết quả này.","Wǒ duì zhège jiéguǒ hěn mǎnyì."],["他对我很热情。","Anh ấy rất nhiệt tình với tôi.","Tā duì wǒ hěn rèqíng."]]},{"t":"生气 là động từ ly hợp — giận AI đặt vào giữa","b":"生 + 人 + 的气","d":"Muốn nói \"giận tôi\" thì phải tách 生气 ra: 生我的气. Nói 生气我 là sai. Đây lại là động từ ly hợp như 唱歌, 跳舞 ở bài 26.","ex":[["你别生我的气。","Bạn đừng giận tôi.","Nǐ bié shēng wǒ de qì."],["妈妈生弟弟的气了。","Mẹ giận em trai rồi.","Māma shēng dìdi de qì le."]]}],"items":[{"zh":"着急","py":"zháojí","vi":"sốt ruột, lo cuống","hv":"trước cấp","note":"急 có bộ 心 ở dưới. Tiếng Việt: \"cấp bách\", \"khẩn cấp\". 别着急 = đừng vội, câu an ủi rất hay dùng.","ex":"别着急，慢慢来。","exPy":"Bié zháojí, mànman lái.","exVi":"Đừng vội, từ từ thôi.","w":"别 着急， 慢 慢 来。"},{"zh":"害怕","py":"hàipà","vi":"sợ","hv":"hại phạ","note":"怕 có bộ 忄 (tim). Nói tắt chỉ dùng 怕 cũng được: 我怕狗 (tôi sợ chó).","ex":"我小时候很害怕狗。","exPy":"Wǒ xiǎo shíhou hěn hàipà gǒu.","exVi":"Hồi nhỏ tôi rất sợ chó.","w":"我 小时候 很 害怕 狗。"},{"zh":"难过","py":"nánguò","vi":"buồn, khó chịu trong lòng","hv":"nan quá","note":"难 (khó) + 过 (qua) — khó mà đi qua được. Cách ghép chữ rất gợi cảm xúc.","ex":"听到这个消息我很难过。","exPy":"Tīng dào zhège xiāoxi wǒ hěn nánguò.","exVi":"Nghe tin đó tôi rất buồn.","w":"听 到 这个 消息 我 很 难过。"},{"zh":"生气","py":"shēngqì","vi":"tức giận","hv":"sinh khí","note":"生 (sinh ra) + 气 (khí) — trong người sinh ra luồng khí nóng. Giận AI thì dùng 生…的气.","ex":"他为什么生气了？","exPy":"Tā wèi shénme shēngqì le?","exVi":"Sao anh ấy lại giận?","w":"他 为什么 生气 了？"},{"zh":"担心","py":"dānxīn","vi":"lo lắng","hv":"đảm tâm","note":"担 (gánh) + 心 (tim) — gánh nặng trong lòng. Tiếng Việt: \"đảm đương\", \"gánh vác\".","ex":"我很担心他的身体。","exPy":"Wǒ hěn dānxīn tā de shēntǐ.","exVi":"Tôi rất lo cho sức khoẻ anh ấy.","w":"我 很 担心 他 的 身体。"},{"zh":"小心","py":"xiǎoxīn","vi":"cẩn thận","hv":"tiểu tâm","note":"小 (nhỏ) + 心 (tim) — giữ lòng nhỏ lại, tức là dè dặt. Biển báo ở Trung Quốc thường ghi 小心！","ex":"过马路要小心。","exPy":"Guò mǎlù yào xiǎoxīn.","exVi":"Qua đường phải cẩn thận.","w":"过 马路 要 小心。"},{"zh":"放心","py":"fàngxīn","vi":"yên tâm","hv":"phóng tâm","note":"放 (đặt xuống) + 心 (tim) — đặt lòng xuống, hết lo. Trái nghĩa hoàn toàn với 担心.","ex":"你放心，我一定完成。","exPy":"Nǐ fàngxīn, wǒ yídìng wánchéng.","exVi":"Bạn yên tâm, tôi nhất định làm xong.","w":"你 放心， 我 一定 完成。"},{"zh":"满意","py":"mǎnyì","vi":"hài lòng","hv":"mãn ý","note":"Chính là \"mãn ý\" tiếng Việt: 满 (đầy) + 意 (ý). Hài lòng với cái gì thì dùng 对…满意.","ex":"老师对我的成绩很满意。","exPy":"Lǎoshī duì wǒ de chéngjì hěn mǎnyì.","exVi":"Thầy rất hài lòng với kết quả của tôi.","w":"老师 对 我 的 成绩 很 满意。"},{"zh":"愿意","py":"yuànyì","vi":"sẵn lòng, muốn","hv":"nguyện ý","note":"Chính là \"nguyện ý\" tiếng Việt. Nhấn vào sự TỰ NGUYỆN, khác 想 (muốn) và 要 (cần).","ex":"如果你愿意，我们一起去。","exPy":"Rúguǒ nǐ yuànyì, wǒmen yìqǐ qù.","exVi":"Nếu bạn muốn, chúng ta cùng đi.","w":"如果 你 愿意， 我们 一起 去。"},{"zh":"同意","py":"tóngyì","vi":"đồng ý, tán thành","hv":"đồng ý","note":"Chính là \"đồng ý\" tiếng Việt: 同 (cùng) + 意 (ý) — cùng một ý.","ex":"我同意你的看法。","exPy":"Wǒ tóngyì nǐ de kànfǎ.","exVi":"Tôi đồng ý với ý kiến của bạn.","w":"我 同意 你 的 看法。"}],"newChars":["急","害","怕","担","满"],"outro":"很好！Xong bài 51."};
G.ROOMS["zh-l052"] = {"id":"zh-l052","lang":"zh","level":3,"no":52,"teacher":"wang","title":"HSK3 · Bài 52 · 想法和决定 Suy nghĩ và quyết định","intro":["你还记得他的名字吗？","Bài 52: Nêu quan điểm, nói nhớ hay quên, và phân biệt 认为 với 觉得. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ hái jìde tā de míngzi ma?","gram":{"t":"觉得 / 认为 / 相信 — ba mức chắc chắn","b":"觉得 = cảm thấy · 认为 = cho rằng · 相信 = tin chắc","d":"觉得 nhẹ nhất, mang tính cảm nhận cá nhân. 认为 là nhận định có suy xét, dùng trong văn viết và tranh luận. 相信 là tin tưởng, mức chắc chắn cao nhất. Cả ba đều theo sau bởi CẢ MỘT CÂU.","ex":[["我觉得有点儿冷。","Tôi thấy hơi lạnh. (cảm nhận)","Wǒ juéde yǒudiǎnr lěng."],["我认为他是对的。","Tôi cho rằng anh ấy đúng. (nhận định)","Wǒ rènwéi tā shì duì de."],["我相信他会来。","Tôi tin anh ấy sẽ đến. (tin chắc)","Wǒ xiāngxìn tā huì lái."]]},"grams":[{"t":"觉得 / 认为 / 相信 — ba mức chắc chắn","b":"觉得 = cảm thấy · 认为 = cho rằng · 相信 = tin chắc","d":"觉得 nhẹ nhất, mang tính cảm nhận cá nhân. 认为 là nhận định có suy xét, dùng trong văn viết và tranh luận. 相信 là tin tưởng, mức chắc chắn cao nhất. Cả ba đều theo sau bởi CẢ MỘT CÂU.","ex":[["我觉得有点儿冷。","Tôi thấy hơi lạnh. (cảm nhận)","Wǒ juéde yǒudiǎnr lěng."],["我认为他是对的。","Tôi cho rằng anh ấy đúng. (nhận định)","Wǒ rènwéi tā shì duì de."],["我相信他会来。","Tôi tin anh ấy sẽ đến. (tin chắc)","Wǒ xiāngxìn tā huì lái."]]},{"t":"清楚 làm bổ ngữ kết quả","b":"động từ giác quan + 清楚","d":"Ghép sau 听, 看, 说 để nói đã đạt tới mức RÕ RÀNG. Phủ định chèn 不 vào giữa, khẳng định chèn 得 — đúng như 听得懂 / 听不懂 ở bài 19.","ex":[["我没听清楚。","Tôi nghe chưa rõ.","Wǒ méi tīng qīngchu."],["太远了，我看不清楚。","Xa quá, tôi nhìn không rõ.","Tài yuǎn le, wǒ kàn bu qīngchu."]]},{"t":"了解 và 知道 và 认识 — ba kiểu \"biết\"","b":"知道 = biết thông tin · 认识 = quen mặt · 了解 = hiểu sâu","d":"Mức độ tăng dần. 我知道他 (nghe tên anh ấy), 我认识他 (quen biết), 我很了解他 (hiểu rõ tính cách anh ấy). Người Việt hay dùng lẫn vì tiếng Việt chỉ có chữ \"biết\".","ex":[["我知道这个地方。","Tôi biết chỗ này.","Wǒ zhīdào zhège dìfang."],["我认识他，但是不太了解他。","Tôi quen anh ấy, nhưng không hiểu rõ lắm.","Wǒ rènshi tā, dànshì bú tài liǎojiě tā."]]}],"items":[{"zh":"相信","py":"xiāngxìn","vi":"tin, tin tưởng","hv":"tương tín","note":"信 = \"tín\" trong \"tín nhiệm\", \"uy tín\". Sau 相信 có thể là người hoặc cả một câu.","ex":"我相信你一定能做到。","exPy":"Wǒ xiāngxìn nǐ yídìng néng zuò dào.","exVi":"Tôi tin bạn nhất định làm được.","w":"我 相信 你 一定 能 做 到。"},{"zh":"认为","py":"rènwéi","vi":"cho rằng, nhận định","hv":"nhận vi","note":"Trang trọng hơn 觉得. Dùng khi nêu một nhận định có suy xét, hay gặp trong bài viết và tranh luận.","ex":"我认为学汉语最重要的是练习。","exPy":"Wǒ rènwéi xué Hànyǔ zuì zhòngyào de shì liànxí.","exVi":"Tôi cho rằng học tiếng Trung quan trọng nhất là luyện tập.","w":"我 认为 学 汉语 最 重要 的 是 练习。"},{"zh":"了解","py":"liǎojiě","vi":"hiểu rõ, tìm hiểu","hv":"liễu giải","note":"Chữ 了 ở đây đọc liǎo chứ không phải le. Tiếng Việt có \"liễu giải\", \"giải thích\".","ex":"他很了解中国文化。","exPy":"Tā hěn liǎojiě Zhōngguó wénhuà.","exVi":"Anh ấy hiểu rất rõ văn hoá Trung Quốc.","w":"他 很 了解 中国 文化。"},{"zh":"明白","py":"míngbai","vi":"hiểu, rõ ràng","hv":"minh bạch","note":"Chính là \"minh bạch\" tiếng Việt: 明 (sáng) + 白 (trắng) — sáng rõ như ban ngày.","ex":"我明白你的意思了。","exPy":"Wǒ míngbai nǐ de yìsi le.","exVi":"Tôi hiểu ý bạn rồi.","w":"我 明白 你 的 意思 了。"},{"zh":"清楚","py":"qīngchu","vi":"rõ ràng, rành mạch","hv":"thanh sở","note":"清 có bộ 氵 (nước) — trong veo như nước. Hay dùng làm bổ ngữ: 听清楚 (nghe rõ), 看清楚 (nhìn rõ).","ex":"这个问题我没听清楚。","exPy":"Zhège wèntí wǒ méi tīng qīngchu.","exVi":"Câu hỏi này tôi nghe chưa rõ.","w":"这个 问题 我 没 听 清楚。"},{"zh":"记得","py":"jìde","vi":"nhớ","hv":"ký đắc","note":"记 = \"ký\" trong \"nhật ký\", \"ghi chép\". Có bộ 讠 (lời nói).","ex":"你还记得他的名字吗？","exPy":"Nǐ hái jìde tā de míngzi ma?","exVi":"Bạn còn nhớ tên anh ấy không?","w":"你 还 记得 他 的 名字 吗？"},{"zh":"忘记","py":"wàngjì","vi":"quên","hv":"vong ký","note":"忘 = 亡 (mất) trên 心 (tim) — rơi mất khỏi lòng. Nói tắt là 忘: 我忘了.","ex":"对不起，我忘记了。","exPy":"Duìbuqǐ, wǒ wàngjì le.","exVi":"Xin lỗi, tôi quên mất rồi.","w":"对不起， 我 忘记 了。"},{"zh":"决定","py":"juédìng","vi":"quyết định","hv":"quyết định","note":"Chính là \"quyết định\" tiếng Việt. Vừa là động từ vừa là danh từ, y hệt tiếng Việt.","ex":"我们决定明天出发。","exPy":"Wǒmen juédìng míngtiān chūfā.","exVi":"Chúng tôi quyết định mai lên đường.","w":"我们 决定 明天 出发。"},{"zh":"选择","py":"xuǎnzé","vi":"lựa chọn","hv":"tuyển trạch","note":"Tiếng Việt: \"tuyển chọn\", \"tuyển sinh\". Cả hai chữ đều có bộ 辶 hoặc 扌 — đi và tay, tức là hành động chọn.","ex":"这两个你选择哪一个？","exPy":"Zhè liǎng ge nǐ xuǎnzé nǎ yí ge?","exVi":"Hai cái này bạn chọn cái nào?","w":"这 两 个 你 选择 哪 一 个？"},{"zh":"需要","py":"xūyào","vi":"cần","hv":"nhu yếu","note":"Chính là \"nhu yếu\" trong \"nhu yếu phẩm\", \"nhu cầu\". Trang trọng hơn 要 và không dùng để gọi món.","ex":"我需要一点儿时间。","exPy":"Wǒ xūyào yìdiǎnr shíjiān.","exVi":"Tôi cần một chút thời gian.","w":"我 需要 一点儿 时间。"}],"newChars":["解","清","楚","记","忘","决","选","择","需"],"outro":"很好！Xong bài 52."};
G.ROOMS["zh-l053"] = {"id":"zh-l053","lang":"zh","level":3,"no":53,"teacher":"wang","title":"HSK3 · Bài 53 · 在学校 Trường lớp","intro":["你上几年级？","Bài 53: Nói về lớp học, bài vở, điểm số — bài giàu từ Hán Việt nhất từ đầu giáo trình. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ shàng jǐ niánjí?","gram":{"t":"Cả bài này là tiếng Việt viết bằng chữ Hán","b":"校长 hiệu trưởng · 练习 luyện tập · 成绩 thành tích · 词典 từ điển","d":"Đây là bài thể hiện rõ nhất lợi thế của người Việt. Bảy trên mười từ có âm Hán Việt trùng khít nghĩa tiếng Việt hiện đại. Mẹo học: gặp từ mới hai chữ, hãy đọc âm Hán Việt lên trước — rất nhiều lần bạn sẽ tự đoán ra nghĩa.","ex":[["校长","hiệu trưởng","xiàozhǎng"],["成绩","thành tích","chéngjì"],["词典","từ điển","cídiǎn"]]},"grams":[{"t":"Cả bài này là tiếng Việt viết bằng chữ Hán","b":"校长 hiệu trưởng · 练习 luyện tập · 成绩 thành tích · 词典 từ điển","d":"Đây là bài thể hiện rõ nhất lợi thế của người Việt. Bảy trên mười từ có âm Hán Việt trùng khít nghĩa tiếng Việt hiện đại. Mẹo học: gặp từ mới hai chữ, hãy đọc âm Hán Việt lên trước — rất nhiều lần bạn sẽ tự đoán ra nghĩa.","ex":[["校长","hiệu trưởng","xiàozhǎng"],["成绩","thành tích","chéngjì"],["词典","từ điển","cídiǎn"]]},{"t":"复习 và 练习 — ôn lại hay luyện mới?","b":"复习 = xem lại cái đã học · 练习 = làm đi làm lại cho thạo","d":"复习课文 (ôn lại bài khoá) nhưng 练习写字 (luyện viết chữ). Nhớ mẹo: 复 là \"lặp lại\", 练 là \"rèn\".","ex":[["我在复习昨天的课。","Tôi đang ôn bài hôm qua.","Wǒ zài fùxí zuótiān de kè."],["我要多练习说话。","Tôi phải luyện nói nhiều hơn.","Wǒ yào duō liànxí shuōhuà."]]},{"t":"Ghép 学 để gọi tên môn học","b":"gốc + 学","d":"Quy tắc ghép chữ cực kỳ hữu ích: biết 学 (học) rồi thì đoán được cả loạt tên môn. Tiếng Việt cũng vậy: số học, hoá học, văn học, y học.","ex":[["数学","toán học","shùxué"],["文学","văn học","wénxué"],["医学","y học","yīxué"]]}],"items":[{"zh":"班","py":"bān","vi":"lớp (học); ca (làm việc)","hv":"ban","note":"Đã gặp trong 上班 (đi làm) ở bài 20. Ở trường thì 班 là lớp: 我们班 = lớp chúng tôi.","ex":"我们班一共有二十五个人。","exPy":"Wǒmen bān yígòng yǒu èrshíwǔ ge rén.","exVi":"Lớp tôi tất cả có hai mươi lăm người.","w":"我们 班 一共 有 二 十 五 个人。"},{"zh":"年级","py":"niánjí","vi":"khối lớp, năm học","hv":"niên cấp","note":"年 (năm) + 级 (cấp bậc). 级 có bộ 纟. Tiếng Việt: \"cấp bậc\", \"đẳng cấp\".","ex":"你上几年级？","exPy":"Nǐ shàng jǐ niánjí?","exVi":"Bạn học lớp mấy?","w":"你 上 几 年级？"},{"zh":"校长","py":"xiàozhǎng","vi":"hiệu trưởng","hv":"hiệu trưởng","note":"Chính là \"hiệu trưởng\" tiếng Việt. Chữ 长 ở đây đọc zhǎng (trưởng), không phải cháng (dài).","ex":"校长要跟我们说话。","exPy":"Xiàozhǎng yào gēn wǒmen shuōhuà.","exVi":"Thầy hiệu trưởng muốn nói chuyện với chúng ta.","w":"校长 要 跟 我们 说话。"},{"zh":"作业","py":"zuòyè","vi":"bài tập về nhà","hv":"tác nghiệp","note":"作 (làm) + 业 (nghiệp, việc). Tiếng Việt: \"tác phẩm\", \"nghiệp vụ\". Làm bài tập là 做作业.","ex":"今天的作业不太多。","exPy":"Jīntiān de zuòyè bú tài duō.","exVi":"Bài tập hôm nay không nhiều lắm.","w":"今天 的 作业 不 太 多。"},{"zh":"练习","py":"liànxí","vi":"luyện tập; bài luyện","hv":"luyện tập","note":"Chính là \"luyện tập\" tiếng Việt. 练 có bộ 纟 (sợi tơ) — luyện như kéo sợi, làm đi làm lại.","ex":"我每天练习写二十个汉字。","exPy":"Wǒ měi tiān liànxí xiě èrshí ge Hànzì.","exVi":"Ngày nào tôi cũng luyện viết hai mươi chữ Hán.","w":"我 每 天 练习 写 二 十 个 汉字。"},{"zh":"复习","py":"fùxí","vi":"ôn tập, ôn lại","hv":"phục tập","note":"复 = \"phục\" trong \"khôi phục\", \"lặp lại\". Khác 练习 (luyện kỹ năng mới) — 复习 là xem lại cái đã học.","ex":"明天考试，我要复习一下。","exPy":"Míngtiān kǎoshì, wǒ yào fùxí yíxià.","exVi":"Mai thi, tôi phải ôn lại chút.","w":"明天 考试， 我 要 复习 一下。"},{"zh":"成绩","py":"chéngjì","vi":"thành tích, điểm số","hv":"thành tích","note":"Chính là \"thành tích\" tiếng Việt. 绩 cũng có bộ 纟 — dệt nên kết quả.","ex":"这次考试成绩怎么样？","exPy":"Zhè cì kǎoshì chéngjì zěnmeyàng?","exVi":"Kết quả kỳ thi lần này thế nào?","w":"这 次 考试 成绩 怎么样？"},{"zh":"数学","py":"shùxué","vi":"môn toán","hv":"số học","note":"数 (số) + 学 (học). Ghép 学 vào sau là ra tên môn: 数学, 化学 (hoá học), 文学 (văn học).","ex":"我的数学成绩比中文好。","exPy":"Wǒ de shùxué chéngjì bǐ Zhōngwén hǎo.","exVi":"Điểm toán của tôi tốt hơn tiếng Trung.","w":"我 的 数学 成绩 比 中文 好。"},{"zh":"词典","py":"cídiǎn","vi":"từ điển","hv":"từ điển","note":"Chính là \"từ điển\" tiếng Việt. 词 có bộ 讠 (lời nói). Còn gọi là 字典 zìdiǎn (tự điển — tra từng chữ).","ex":"不认识的字可以查词典。","exPy":"Bú rènshi de zì kěyǐ chá cídiǎn.","exVi":"Chữ không biết thì tra từ điển.","w":"不 认识 的 字 可以 查 词典。"},{"zh":"笔记本","py":"bǐjìběn","vi":"quyển vở; máy tính xách tay","hv":"bút ký bản","note":"笔 (bút) + 记 (ghi) + 本 (quyển). Nay còn nghĩa laptop: 笔记本电脑.","ex":"我把笔记本忘在教室了。","exPy":"Wǒ bǎ bǐjìběn wàng zài jiàoshì le.","exVi":"Tôi để quên vở ở lớp rồi.","w":"我 把 笔记本 忘 在 教室 了。"}],"newChars":["业","练","复","绩","典"],"outro":"很好！Xong bài 53."};
G.ROOMS["zh-l054"] = {"id":"zh-l054","lang":"zh","level":3,"no":54,"teacher":"wang","title":"HSK3 · Bài 54 · 认真学习 Dạy và học","intro":["老师教得很认真。","Bài 54: Nói về việc dạy, hỏi đáp, khó dễ, và dùng bổ ngữ trình độ 得 thành thạo. Bấm 1 · Học để bắt đầu."],"introPy":"Lǎoshī jiāo de hěn rènzhēn.","gram":{"t":"Bổ ngữ trình độ 得 — nói làm việc gì đó ra sao","b":"Động từ + 得 + tính từ","d":"Nhắc lại bài 26 nhưng giờ dùng thành thạo. Nếu động từ có tân ngữ thì phải LẶP LẠI động từ: 他说汉语说得很好. Hoặc đảo tân ngữ lên trước: 他汉语说得很好. Cả hai đều đúng.","ex":[["老师讲得很清楚。","Thầy giảng rất rõ.","Lǎoshī jiǎng de hěn qīngchu."],["他汉字写得很漂亮。","Anh ấy viết chữ Hán rất đẹp.","Tā Hànzì xiě de hěn piàoliang."],["你回答得不对。","Bạn trả lời không đúng.","Nǐ huídá de bú duì."]]},"grams":[{"t":"Bổ ngữ trình độ 得 — nói làm việc gì đó ra sao","b":"Động từ + 得 + tính từ","d":"Nhắc lại bài 26 nhưng giờ dùng thành thạo. Nếu động từ có tân ngữ thì phải LẶP LẠI động từ: 他说汉语说得很好. Hoặc đảo tân ngữ lên trước: 他汉语说得很好. Cả hai đều đúng.","ex":[["老师讲得很清楚。","Thầy giảng rất rõ.","Lǎoshī jiǎng de hěn qīngchu."],["他汉字写得很漂亮。","Anh ấy viết chữ Hán rất đẹp.","Tā Hànzì xiě de hěn piàoliang."],["你回答得不对。","Bạn trả lời không đúng.","Nǐ huídá de bú duì."]]},{"t":"Câu hỏi chính phản: A 不 A","b":"tính từ + 不 + tính từ · động từ + 不 + động từ","d":"Cách hỏi thay cho 吗, nghe tự nhiên và hay dùng hơn trong hội thoại. 难不难? = có khó không? Lưu ý: câu này KHÔNG được thêm 吗 nữa.","ex":[["汉语难不难？","Tiếng Trung có khó không?","Hànyǔ nán bu nán?"],["你去不去？","Bạn có đi không?","Nǐ qù bu qù?"],["这个问题简单不简单？","Câu hỏi này có đơn giản không?","Zhège wèntí jiǎndān bu jiǎndān?"]]},{"t":"只要 … 就 … — chỉ cần… là…","b":"只要 + điều kiện, 就 + kết quả","d":"Cấu trúc động viên rất hay dùng khi học. Giống hệt \"chỉ cần… là…\" của tiếng Việt, kể cả vị trí hai vế.","ex":[["只要努力，就一定能学会。","Chỉ cần cố gắng là nhất định học được.","Zhǐyào nǔlì, jiù yídìng néng xué huì."],["只要每天练习，你的字就会越来越好。","Chỉ cần ngày nào cũng luyện, chữ bạn sẽ ngày càng đẹp.","Zhǐyào měi tiān liànxí, nǐ de zì jiù huì yuè lái yuè hǎo."]]}],"items":[{"zh":"教","py":"jiāo","vi":"dạy","hv":"giáo","note":"Tiếng Việt: \"giáo dục\", \"giáo viên\". Đọc jiāo (thanh 1) là động từ dạy; đọc jiào (thanh 4) trong 教室, 教育.","ex":"老师教得很认真。","exPy":"Lǎoshī jiāo de hěn rènzhēn.","exVi":"Thầy dạy rất tận tâm.","w":"老师 教 得 很 认真。"},{"zh":"讲","py":"jiǎng","vi":"giảng, kể, nói","hv":"giảng","note":"Chính là \"giảng\" tiếng Việt (\"giảng bài\", \"diễn giảng\"). Bộ 讠 (lời nói).","ex":"老师，请您再讲一次。","exPy":"Lǎoshī, qǐng nín zài jiǎng yí cì.","exVi":"Thưa thầy, xin thầy giảng lại một lần nữa.","w":"老师， 请 您 再 讲 一 次。"},{"zh":"回答","py":"huídá","vi":"trả lời","hv":"hồi đáp","note":"Chính là \"hồi đáp\" tiếng Việt: 回 (quay lại) + 答 (đáp). 答 có bộ 竹 (tre) — thẻ tre để viết câu trả lời.","ex":"请回答第一个问题。","exPy":"Qǐng huídá dì-yī ge wèntí.","exVi":"Xin trả lời câu hỏi thứ nhất.","w":"请 回答 第一 个 问题。"},{"zh":"句子","py":"jùzi","vi":"câu","hv":"cú tử","note":"Tiếng Việt: \"cú pháp\", \"tạo cú\". Lượng từ là 个: 一个句子.","ex":"这个句子是什么意思？","exPy":"Zhège jùzi shì shénme yìsi?","exVi":"Câu này nghĩa là gì?","w":"这个 句子 是 什么 意思？"},{"zh":"简单","py":"jiǎndān","vi":"đơn giản","hv":"giản đơn","note":"Chính là \"giản đơn\" tiếng Việt, chỉ đảo thứ tự thành \"đơn giản\". 简 có bộ 竹 (thẻ tre).","ex":"这个语法很简单。","exPy":"Zhège yǔfǎ hěn jiǎndān.","exVi":"Ngữ pháp này rất đơn giản.","w":"这个 语法 很 简单。"},{"zh":"容易","py":"róngyì","vi":"dễ, dễ dàng","hv":"dung dị","note":"Khác 简单 một chút: 简单 là ít phức tạp, 容易 là không tốn công. Trái nghĩa của cả hai đều là 难.","ex":"汉语的发音不太容易。","exPy":"Hànyǔ de fāyīn bú tài róngyì.","exVi":"Phát âm tiếng Trung không dễ lắm.","w":"汉语 的 发音 不 太 容易。"},{"zh":"难","py":"nán","vi":"khó","hv":"nan","note":"Tiếng Việt: \"nan giải\", \"khó khăn\", \"gian nan\". Đã gặp trong 难过 (bài 34).","ex":"写汉字很难，但是很有意思。","exPy":"Xiě Hànzì hěn nán, dànshì hěn yǒu yìsi.","exVi":"Viết chữ Hán khó nhưng rất thú vị.","w":"写 汉字 很 难， 但是 很 有意思。"},{"zh":"认真","py":"rènzhēn","vi":"nghiêm túc, chăm chú","hv":"nhận chân","note":"认 (nhận) + 真 (thật) — coi mọi việc là thật. Lời khen rất hay dùng với học sinh và nhân viên.","ex":"只要认真练习，一定会进步。","exPy":"Zhǐyào rènzhēn liànxí, yídìng huì jìnbù.","exVi":"Chỉ cần luyện tập nghiêm túc, nhất định sẽ tiến bộ.","w":"只要 认真 练习， 一定 会 进步。"},{"zh":"努力","py":"nǔlì","vi":"nỗ lực, cố gắng","hv":"nỗ lực","note":"Chính là \"nỗ lực\" tiếng Việt. 力 là bộ thủ \"lực\" bạn đã học — dồn sức ra làm.","ex":"他学习很努力，成绩也很好。","exPy":"Tā xuéxí hěn nǔlì, chéngjì yě hěn hǎo.","exVi":"Cậu ấy học rất chăm, điểm cũng tốt.","w":"他 学习 很 努力， 成绩 也 很 好。"},{"zh":"提高","py":"tígāo","vi":"nâng cao","hv":"đề cao","note":"Chính là \"đề cao\" tiếng Việt: 提 (nâng, bộ 扌 tay) + 高 (cao). Hay dùng với 水平 (trình độ).","ex":"我要提高我的听力水平。","exPy":"Wǒ yào tígāo wǒ de tīnglì shuǐpíng.","exVi":"Tôi phải nâng cao khả năng nghe.","w":"我 要 提高 我 的 听力 水平。"}],"newChars":["讲","答","句","简","单","容","易","努","力","提"],"outro":"很好！Xong bài 54."};
G.ROOMS["zh-l055"] = {"id":"zh-l055","lang":"zh","level":3,"no":55,"teacher":"wang","title":"HSK3 · Bài 55 · 语言和文化 Ngôn ngữ và văn hoá","intro":["我学中文两年了。","Bài 55: Nói về đất nước, văn hoá, trình độ tiếng — và thấy tiếng Việt gần tiếng Trung đến mức nào. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ xué Zhōngwén liǎng nián le.","gram":{"t":"对 … 感兴趣 — hứng thú với cái gì","b":"对 + đối tượng + 感兴趣","d":"Mẫu câu cố định, học nguyên khối. Cả cụm 对…感 đứng trước 兴趣. Phủ định: 对…不感兴趣.","ex":[["我对历史很感兴趣。","Tôi rất hứng thú với lịch sử.","Wǒ duì lìshǐ hěn gǎn xìngqù."],["他对音乐不感兴趣。","Anh ấy không hứng thú với âm nhạc.","Tā duì yīnyuè bù gǎn xìngqù."]]},"grams":[{"t":"对 … 感兴趣 — hứng thú với cái gì","b":"对 + đối tượng + 感兴趣","d":"Mẫu câu cố định, học nguyên khối. Cả cụm 对…感 đứng trước 兴趣. Phủ định: 对…不感兴趣.","ex":[["我对历史很感兴趣。","Tôi rất hứng thú với lịch sử.","Wǒ duì lìshǐ hěn gǎn xìngqù."],["他对音乐不感兴趣。","Anh ấy không hứng thú với âm nhạc.","Tā duì yīnyuè bù gǎn xìngqù."]]},{"t":"世界上 — thêm 上 sau danh từ trừu tượng","b":"世界上 · 书上 · 报纸上 · 网上","d":"Nhắc lại quy tắc bài 11: từ chỉ vị trí đứng SAU danh từ. Với những khái niệm rộng như thế giới, sách, mạng, tiếng Trung vẫn thêm 上 dù tiếng Việt không nói \"trên thế giới\" theo nghĩa đen.","ex":[["世界上最高的山","ngọn núi cao nhất thế giới","shìjiè shàng zuì gāo de shān"],["我在网上看到的。","Tôi thấy trên mạng.","Wǒ zài wǎng shàng kàn dào de."]]},{"t":"Kho từ Hán Việt hai âm tiết — mỏ vàng của người Việt","b":"文化 · 历史 · 世界 · 国家 · 音乐 · 普通","d":"Sáu từ trong bài này có âm Hán Việt TRÙNG KHÍT với từ tiếng Việt bạn dùng hằng ngày. Người học tiếng Anh phải học thuộc từng từ một; bạn chỉ cần nhận ra mối liên hệ. Hãy tận dụng: mỗi khi gặp từ hai chữ, đọc âm Hán Việt trước.","ex":[["文化 · 历史 · 世界","văn hoá · lịch sử · thế giới","wénhuà · lìshǐ · shìjiè"],["国家 · 音乐 · 普通","quốc gia · âm nhạc · phổ thông","guójiā · yīnyuè · pǔtōng"]]}],"items":[{"zh":"中文","py":"Zhōngwén","vi":"tiếng Trung, Trung văn","hv":"Trung văn","note":"文 nhấn vào CHỮ VIẾT và văn bản, còn 汉语 (bài 5) nhấn vào TIẾNG NÓI. Trong đời thường dùng lẫn nhau được.","ex":"我学中文两年了。","exPy":"Wǒ xué Zhōngwén liǎng nián le.","exVi":"Tôi học tiếng Trung hai năm rồi.","w":"我 学 中文 两 年 了。"},{"zh":"普通话","py":"pǔtōnghuà","vi":"tiếng phổ thông","hv":"phổ thông thoại","note":"普通 chính là \"phổ thông\" tiếng Việt. Đây là tiếng chuẩn dùng trên cả nước, khác các phương ngữ như tiếng Quảng Đông.","ex":"他的普通话说得非常好。","exPy":"Tā de pǔtōnghuà shuō de fēicháng hǎo.","exVi":"Anh ấy nói tiếng phổ thông cực chuẩn.","w":"他 的 普通话 说 得 非常 好。"},{"zh":"水平","py":"shuǐpíng","vi":"trình độ","hv":"thuỷ bình","note":"Nghĩa đen là \"mặt nước phẳng\" — mức ngang bằng, từ đó thành \"trình độ\". Hay đi với 提高 (bài 37).","ex":"我的汉语水平还需要提高。","exPy":"Wǒ de Hànyǔ shuǐpíng hái xūyào tígāo.","exVi":"Trình độ tiếng Trung của tôi còn cần nâng cao.","w":"我 的 汉语 水平 还 需要 提高。"},{"zh":"文化","py":"wénhuà","vi":"văn hoá","hv":"văn hoá","note":"Chính là \"văn hoá\" tiếng Việt, không sai một ly.","ex":"我对中国文化很感兴趣。","exPy":"Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù.","exVi":"Tôi rất hứng thú với văn hoá Trung Quốc.","w":"我 对 中国 文化 很 感兴趣。"},{"zh":"历史","py":"lìshǐ","vi":"lịch sử","hv":"lịch sử","note":"Chính là \"lịch sử\" tiếng Việt. Việt Nam và Trung Quốc chia sẻ hàng nghìn năm lịch sử — và cả kho từ vựng này.","ex":"越南和中国的历史关系很长。","exPy":"Yuènán hé Zhōngguó de lìshǐ guānxi hěn cháng.","exVi":"Quan hệ lịch sử giữa Việt Nam và Trung Quốc rất lâu đời.","w":"越 南 和 中国 的 历史 关系 很 长。"},{"zh":"世界","py":"shìjiè","vi":"thế giới","hv":"thế giới","note":"Chính là \"thế giới\" tiếng Việt. 界 có bộ 田 (ruộng) — ranh giới các thửa ruộng.","ex":"世界上有两百多个国家。","exPy":"Shìjiè shàng yǒu liǎngbǎi duō ge guójiā.","exVi":"Trên thế giới có hơn hai trăm quốc gia.","w":"世界 上 有 两 百 多 个 国家。"},{"zh":"国家","py":"guójiā","vi":"quốc gia, đất nước","hv":"quốc gia","note":"Chính là \"quốc gia\" tiếng Việt: 国 (nước) + 家 (nhà) — nước là cái nhà lớn.","ex":"你去过几个国家？","exPy":"Nǐ qù guo jǐ ge guójiā?","exVi":"Bạn đã đi mấy nước rồi?","w":"你 去 过 几 个 国家？"},{"zh":"有名","py":"yǒumíng","vi":"nổi tiếng","hv":"hữu danh","note":"有 (có) + 名 (danh tiếng). Tiếng Việt có \"hữu danh vô thực\" — cùng chữ 有名 này.","ex":"北京是一个很有名的城市。","exPy":"Běijīng shì yí ge hěn yǒumíng de chéngshì.","exVi":"Bắc Kinh là một thành phố rất nổi tiếng.","w":"北京 是 一 个 很 有名 的 城市。"},{"zh":"故事","py":"gùshi","vi":"câu chuyện","hv":"cố sự","note":"故 = \"cố\" trong \"cố hương\", \"điển cố\". Nghĩa đen: chuyện cũ. Kể chuyện là 讲故事.","ex":"奶奶给我讲了一个很有意思的故事。","exPy":"Nǎinai gěi wǒ jiǎng le yí ge hěn yǒu yìsi de gùshi.","exVi":"Bà nội kể cho tôi một câu chuyện rất thú vị.","w":"奶奶 给 我 讲 了 一 个 很 有意思 的 故事。"},{"zh":"音乐","py":"yīnyuè","vi":"âm nhạc","hv":"âm nhạc","note":"Chính là \"âm nhạc\" tiếng Việt. Chữ 乐 đọc yuè là nhạc, đọc lè là vui (như 快乐 bài 28) — một chữ hai âm.","ex":"我一边做作业一边听音乐。","exPy":"Wǒ yìbiān zuò zuòyè yìbiān tīng yīnyuè.","exVi":"Tôi vừa làm bài vừa nghe nhạc.","w":"我 一边 做 作业 一边 听 音乐。"}],"newChars":["文","普","平","化","史","世","界","故","音"],"outro":"很好！Xong bài 55."};
G.ROOMS["zh-l056"] = {"id":"zh-l056","lang":"zh","level":3,"no":56,"teacher":"wang","title":"HSK3 · Bài 56 · 工作和会议 Công việc và cuộc họp","intro":["经理让我参加下午的会议。","Bài 56: Nói chuyện nơi công sở, đề nghị giải pháp — sáu trên mười từ là từ Hán Việt quen thuộc. Bấm 1 · Học để bắt đầu."],"introPy":"Jīnglǐ ràng wǒ cānjiā xiàwǔ de huìyì.","gram":{"t":"已经 … 了 — đã… rồi","b":"已经 + động từ + 了","d":"已经 yǐjīng nghĩa là \"đã\". Gần như luôn đi kèm 了 ở cuối câu. Phủ định thì bỏ cả hai và dùng 还没: 还没完成 (vẫn chưa xong).","ex":[["工作已经完成了。","Việc đã xong rồi.","Gōngzuò yǐjīng wánchéng le."],["会议已经开始了。","Cuộc họp đã bắt đầu rồi.","Huìyì yǐjīng kāishǐ le."],["我还没完成。","Tôi vẫn chưa xong.","Wǒ hái méi wánchéng."]]},"grams":[{"t":"已经 … 了 — đã… rồi","b":"已经 + động từ + 了","d":"已经 yǐjīng nghĩa là \"đã\". Gần như luôn đi kèm 了 ở cuối câu. Phủ định thì bỏ cả hai và dùng 还没: 还没完成 (vẫn chưa xong).","ex":[["工作已经完成了。","Việc đã xong rồi.","Gōngzuò yǐjīng wánchéng le."],["会议已经开始了。","Cuộc họp đã bắt đầu rồi.","Huìyì yǐjīng kāishǐ le."],["我还没完成。","Tôi vẫn chưa xong.","Wǒ hái méi wánchéng."]]},{"t":"Động từ ly hợp trong công sở","b":"帮忙 · 开会 · 上班 · 请假","d":"Cùng nhóm với 唱歌, 跳舞, 生气 đã học. Muốn thêm gì thì chèn vào giữa: 帮我的忙, 开了三个小时会, 请一天假. Đây là điểm ngữ pháp người Việt hay quên nhất.","ex":[["他帮了我很大的忙。","Anh ấy giúp tôi rất nhiều.","Tā bāng le wǒ hěn dà de máng."],["我们开了两个小时会。","Chúng tôi họp hai tiếng.","Wǒmen kāi le liǎng ge xiǎoshí huì."]]},{"t":"对 … 要求高 — đòi hỏi cao với ai","b":"对 + người + 要求 + 高/严","d":"Lại là mẫu 对 quen thuộc từ bài 34. Nhớ: cụm 对… luôn đứng TRƯỚC phần miêu tả, không đứng sau.","ex":[["老师对学生要求很高。","Thầy yêu cầu học sinh rất cao.","Lǎoshī duì xuésheng yāoqiú hěn gāo."],["他对自己要求很严。","Anh ấy đòi hỏi bản thân rất nghiêm.","Tā duì zìjǐ yāoqiú hěn yán."]]}],"items":[{"zh":"经理","py":"jīnglǐ","vi":"giám đốc, quản lý","hv":"kinh lý","note":"经 (kinh doanh) + 理 (quản lý). Tiếng Việt: \"kinh lý\", \"quản lý\", \"lý sự\". Gọi kèm họ: 王经理.","ex":"经理让我参加下午的会议。","exPy":"Jīnglǐ ràng wǒ cānjiā xiàwǔ de huìyì.","exVi":"Giám đốc bảo tôi dự cuộc họp chiều nay.","w":"经理 让 我 参加 下午 的 会议。"},{"zh":"同事","py":"tóngshì","vi":"đồng nghiệp","hv":"đồng sự","note":"Chính là \"đồng sự\" tiếng Việt: 同 (cùng) + 事 (việc). Cùng nhóm với 同学 (bài 5), 同意 (bài 34).","ex":"我的同事都很热情。","exPy":"Wǒ de tóngshì dōu hěn rèqíng.","exVi":"Đồng nghiệp của tôi đều rất nhiệt tình.","w":"我 的 同事 都 很 热情。"},{"zh":"办公室","py":"bàngōngshì","vi":"văn phòng","hv":"biện công thất","note":"办 (làm) + 公 (việc công) + 室 (phòng). Tiếng Việt: \"biện pháp\", \"công vụ\", \"phòng thất\".","ex":"办公室在三楼。","exPy":"Bàngōngshì zài sān lóu.","exVi":"Văn phòng ở tầng ba.","w":"办公室 在 三 楼。"},{"zh":"会议","py":"huìyì","vi":"cuộc họp, hội nghị","hv":"hội nghị","note":"Chính là \"hội nghị\" tiếng Việt. Họp là 开会 (mở hội) — dùng động từ 开 như 开车, 开门.","ex":"会议几点开始？","exPy":"Huìyì jǐ diǎn kāishǐ?","exVi":"Mấy giờ họp?","w":"会议 几 点 开始？"},{"zh":"司机","py":"sījī","vi":"tài xế","hv":"tư cơ","note":"司 (điều khiển) + 机 (máy). 司 cũng nằm trong 公司 (công ty) ở bài 20.","ex":"司机把我们送到了机场。","exPy":"Sījī bǎ wǒmen sòng dào le jīchǎng.","exVi":"Tài xế đưa chúng tôi tới sân bay.","w":"司机 把 我们 送 到 了 机场。"},{"zh":"帮忙","py":"bāngmáng","vi":"giúp một tay","hv":"bang mang","note":"Là động từ ly hợp: giúp AI thì tách ra — 帮我的忙, hoặc đơn giản dùng 帮我 như bài 20.","ex":"你能帮个忙吗？","exPy":"Nǐ néng bāng ge máng ma?","exVi":"Bạn giúp một tay được không?","w":"你 能 帮 个 忙 吗？"},{"zh":"完成","py":"wánchéng","vi":"hoàn thành","hv":"hoàn thành","note":"Chính là \"hoàn thành\" tiếng Việt: 完 (xong, bài 23) + 成 (nên).","ex":"这个工作我已经完成了。","exPy":"Zhège gōngzuò wǒ yǐjīng wánchéng le.","exVi":"Việc này tôi đã làm xong rồi.","w":"这个 工作 我 已经 完成 了。"},{"zh":"要求","py":"yāoqiú","vi":"yêu cầu","hv":"yêu cầu","note":"Chính là \"yêu cầu\" tiếng Việt. Chú ý 要 ở đây đọc yāo (thanh 1), không phải yào.","ex":"老板对工作要求很高。","exPy":"Lǎobǎn duì gōngzuò yāoqiú hěn gāo.","exVi":"Sếp yêu cầu công việc rất cao.","w":"老板 对 工作 要求 很 高。"},{"zh":"解决","py":"jiějué","vi":"giải quyết","hv":"giải quyết","note":"Chính là \"giải quyết\" tiếng Việt. 解 vốn là hình con dao mổ con bò — tháo gỡ ra.","ex":"我们一定能解决这个问题。","exPy":"Wǒmen yídìng néng jiějué zhège wèntí.","exVi":"Chúng ta nhất định giải quyết được vấn đề này.","w":"我们 一定 能 解决 这个 问题。"},{"zh":"办法","py":"bànfǎ","vi":"cách, biện pháp","hv":"biện pháp","note":"Chính là \"biện pháp\" tiếng Việt. 没办法 = không còn cách nào, câu than thở rất hay dùng.","ex":"没办法，只能这样了。","exPy":"Méi bànfǎ, zhǐ néng zhèyàng le.","exVi":"Không còn cách nào, đành vậy thôi.","w":"没 办法， 只能 这样 了。"}],"newChars":["办","议","求"],"outro":"很好！Xong bài 56."};
G.ROOMS["zh-l057"] = {"id":"zh-l057","lang":"zh","level":3,"no":57,"teacher":"wang","title":"HSK3 · Bài 57 · 城市生活 Trong thành phố","intro":["这个城市不太大，但是很干净。","Bài 57: Gọi tên các địa điểm trong thành phố và tả vị trí bằng cấu trúc 在…的… Bấm 1 · Học để bắt đầu."],"introPy":"Zhège chéngshì bú tài dà, dànshì hěn gānjìng.","gram":{"t":"附近有 … 吗？ — hỏi quanh đây có gì","b":"(nơi chốn) + 有 + vật + 吗?","d":"Mẫu câu tồn tại: nơi chốn đứng đầu, rồi 有, rồi thứ tồn tại. Rất khác tiếng Anh (there is) nhưng giống tiếng Việt: \"gần đây có siêu thị không?\".","ex":[["附近有银行吗？","Gần đây có ngân hàng không?","Fùjìn yǒu yínháng ma?"],["学校附近有很多饭馆。","Gần trường có nhiều quán ăn.","Xuéxiào fùjìn yǒu hěn duō fànguǎn."]]},"grams":[{"t":"附近有 … 吗？ — hỏi quanh đây có gì","b":"(nơi chốn) + 有 + vật + 吗?","d":"Mẫu câu tồn tại: nơi chốn đứng đầu, rồi 有, rồi thứ tồn tại. Rất khác tiếng Anh (there is) nhưng giống tiếng Việt: \"gần đây có siêu thị không?\".","ex":[["附近有银行吗？","Gần đây có ngân hàng không?","Fùjìn yǒu yínháng ma?"],["学校附近有很多饭馆。","Gần trường có nhiều quán ăn.","Xuéxiào fùjìn yǒu hěn duō fànguǎn."]]},{"t":"在 A 和 B 中间 — nằm giữa hai thứ","b":"在 + A + 和 + B + 中间","d":"Cấu trúc chỉ vị trí ba thành phần. Chú ý 中间 đứng CUỐI, sau cả hai mốc — đúng quy tắc \"từ chỉ vị trí đứng sau danh từ\" của bài 11.","ex":[["公园在学校和医院中间。","Công viên nằm giữa trường học và bệnh viện.","Gōngyuán zài xuéxiào hé yīyuàn zhōngjiān."],["他坐在我和妹妹中间。","Cậu ấy ngồi giữa tôi và em gái.","Tā zuò zài wǒ hé mèimei zhōngjiān."]]},{"t":"Đuôi 馆 và 店 — tên các loại cơ sở","b":"馆 = nơi lớn có tổ chức · 店 = cửa hàng","d":"图书馆 (thư viện), 饭馆 (quán ăn), 宾馆 (khách sạn) đều dùng 馆. Còn 商店 (cửa hàng), 书店 (hiệu sách) dùng 店. Biết hai đuôi này là đoán được rất nhiều tên địa điểm.","ex":[["图书馆 · 饭馆 · 宾馆","thư viện · quán ăn · khách sạn","túshūguǎn · fànguǎn · bīnguǎn"],["商店 · 书店 · 饭店","cửa hàng · hiệu sách · nhà hàng","shāngdiàn · shūdiàn · fàndiàn"]]}],"items":[{"zh":"城市","py":"chéngshì","vi":"thành phố","hv":"thành thị","note":"Chính là \"thành thị\" tiếng Việt: 城 (thành luỹ) + 市 (chợ). Trái nghĩa là 农村 (nông thôn).","ex":"这个城市不太大，但是很干净。","exPy":"Zhège chéngshì bú tài dà, dànshì hěn gānjìng.","exVi":"Thành phố này không lớn lắm nhưng rất sạch.","w":"这个 城市 不 太 大， 但是 很 干净。"},{"zh":"地方","py":"dìfang","vi":"nơi, chỗ","hv":"địa phương","note":"Chính là \"địa phương\" tiếng Việt, nhưng tiếng Trung dùng rộng hơn — bất cứ \"chỗ\" nào cũng là 地方.","ex":"这个地方我来过一次。","exPy":"Zhège dìfang wǒ lái guo yí cì.","exVi":"Chỗ này tôi từng đến một lần.","w":"这个 地方 我 来 过 一 次。"},{"zh":"附近","py":"fùjìn","vi":"gần đây, lân cận","hv":"phụ cận","note":"Chính là \"phụ cận\" tiếng Việt. 近 là chữ \"cận\" (gần) đã học ở bài 24.","ex":"请问，附近有超市吗？","exPy":"Qǐngwèn, fùjìn yǒu chāoshì ma?","exVi":"Xin hỏi, gần đây có siêu thị không?","w":"请问， 附近 有 超市 吗？"},{"zh":"中间","py":"zhōngjiān","vi":"ở giữa","hv":"trung gian","note":"Tiếng Việt: \"trung gian\", \"trung tâm\". Nằm giữa hai vật thì dùng 在 A 和 B 中间.","ex":"图书馆在公园和学校中间。","exPy":"Túshūguǎn zài gōngyuán hé xuéxiào zhōngjiān.","exVi":"Thư viện nằm giữa công viên và trường học.","w":"图书馆 在 公园 和 学校 中间。"},{"zh":"街道","py":"jiēdào","vi":"đường phố","hv":"nhai đạo","note":"街 (phố) + 道 (đường). Nói tắt là 街: 上街 = ra phố. 道 cũng là \"đạo\" trong \"đạo lý\", \"đường đạo\".","ex":"这条街道上有很多商店。","exPy":"Zhè tiáo jiēdào shàng yǒu hěn duō shāngdiàn.","exVi":"Trên phố này có nhiều cửa hàng.","w":"这 条 街道 上 有 很 多 商店。"},{"zh":"公园","py":"gōngyuán","vi":"công viên","hv":"công viên","note":"Chính là \"công viên\" tiếng Việt: 公 (công cộng) + 园 (vườn).","ex":"老人们喜欢在公园里锻炼。","exPy":"Lǎorénmen xǐhuan zài gōngyuán lǐ duànliàn.","exVi":"Người già thích tập thể dục trong công viên.","w":"老人 们 喜欢 在 公园 里 锻炼。"},{"zh":"银行","py":"yínháng","vi":"ngân hàng","hv":"ngân hàng","note":"Chính là \"ngân hàng\" tiếng Việt: 银 (bạc, bộ 钅 kim loại) + 行. Chú ý 行 ở đây đọc háng, không phải xíng.","ex":"有，就在银行旁边。","exPy":"Yǒu, jiù zài yínháng pángbiān.","exVi":"Có, ngay cạnh ngân hàng.","w":"有， 就 在 银行 旁边。"},{"zh":"超市","py":"chāoshì","vi":"siêu thị","hv":"siêu thị","note":"Chính là \"siêu thị\" tiếng Việt: 超 (siêu, vượt) + 市 (chợ). Nói đủ là 超级市场.","ex":"超市里的水果很新鲜。","exPy":"Chāoshì lǐ de shuǐguǒ hěn xīnxiān.","exVi":"Hoa quả trong siêu thị rất tươi.","w":"超市 里 的 水果 很 新鲜。"},{"zh":"图书馆","py":"túshūguǎn","vi":"thư viện","hv":"đồ thư quán","note":"图 (đồ, tranh) + 书 (sách) + 馆 (quán). Tiếng Việt gọi là \"thư viện\", cùng chữ 书 (thư).","ex":"我每个周末都去图书馆。","exPy":"Wǒ měi ge zhōumò dōu qù túshūguǎn.","exVi":"Cuối tuần nào tôi cũng đi thư viện.","w":"我 每 个 周末 都 去 图书馆。"},{"zh":"洗手间","py":"xǐshǒujiān","vi":"nhà vệ sinh","hv":"tẩy thủ gian","note":"洗 (rửa) + 手 (tay) + 间 (gian phòng) — \"phòng rửa tay\", cách nói lịch sự. Còn gọi là 卫生间.","ex":"请问洗手间怎么走？","exPy":"Qǐngwèn xǐshǒujiān zěnme zǒu?","exVi":"Xin hỏi nhà vệ sinh đi lối nào?","w":"请问 洗手间 怎么 走？"}],"newChars":["城","市","地","附","街","园","银","超","图"],"outro":"很好！Xong bài 57."};
G.ROOMS["zh-l058"] = {"id":"zh-l058","lang":"zh","level":3,"no":58,"teacher":"wang","title":"HSK3 · Bài 58 · 坐地铁 Đi lại trong thành phố","intro":["从这儿到机场坐地铁最快。","Bài 58: Đi tàu điện ngầm, hỏi tầng lầu, đón tiễn người — và phân biệt 楼 với 层. Bấm 1 · Học để bắt đầu."],"introPy":"Cóng zhèr dào jīchǎng zuò dìtiě zuì kuài.","gram":{"t":"楼 và 层 — cùng nghĩa \"tầng\" nhưng dùng khác nhau","b":"住在三楼 (ở tầng 3) · 这座楼有二十层 (toà nhà có 20 tầng)","d":"Khi nói MÌNH Ở tầng mấy thì dùng 楼: 三楼. Khi ĐẾM có bao nhiêu tầng thì dùng 层: 二十层. Mẹo nhớ: 层 là lượng từ nên luôn đi sau con số để đếm.","ex":[["我的办公室在五楼。","Văn phòng tôi ở tầng năm.","Wǒ de bàngōngshì zài wǔ lóu."],["这座楼一共有十二层。","Toà nhà này tất cả có mười hai tầng.","Zhè zuò lóu yígòng yǒu shí'èr céng."]]},"grams":[{"t":"楼 và 层 — cùng nghĩa \"tầng\" nhưng dùng khác nhau","b":"住在三楼 (ở tầng 3) · 这座楼有二十层 (toà nhà có 20 tầng)","d":"Khi nói MÌNH Ở tầng mấy thì dùng 楼: 三楼. Khi ĐẾM có bao nhiêu tầng thì dùng 层: 二十层. Mẹo nhớ: 层 là lượng từ nên luôn đi sau con số để đếm.","ex":[["我的办公室在五楼。","Văn phòng tôi ở tầng năm.","Wǒ de bàngōngshì zài wǔ lóu."],["这座楼一共有十二层。","Toà nhà này tất cả có mười hai tầng.","Zhè zuò lóu yígòng yǒu shí'èr céng."]]},{"t":"坐 và 骑 — nhắc lại và mở rộng","b":"坐 = ngồi vào trong · 骑 = dạng chân cưỡi lên","d":"坐地铁, 坐船, 坐飞机, 坐公共汽车 (ngồi vào). Nhưng 骑自行车, 骑马, 骑摩托车 (cưỡi lên). Giống hệt tiếng Việt phân biệt \"đi tàu\" với \"cưỡi ngựa\".","ex":[["我坐地铁，他骑自行车。","Tôi đi tàu điện, cậu ấy đạp xe.","Wǒ zuò dìtiě, tā qí zìxíngchē."]]},{"t":"接 — một chữ ba nghĩa hay dùng","b":"接人 đón người · 接电话 nghe máy · 接东西 nhận đồ","d":"Nghĩa gốc của 接 là \"nối vào, tiếp nhận\". Từ đó ra cả ba nghĩa. Tiếng Việt cũng nói \"tiếp đón\", \"tiếp nhận\", \"tiếp máy\" — cùng một logic.","ex":[["明天我去车站接你。","Mai tôi ra bến đón bạn.","Míngtiān wǒ qù chēzhàn jiē nǐ."],["他正在接电话。","Anh ấy đang nghe điện thoại.","Tā zhèngzài jiē diànhuà."]]}],"items":[{"zh":"地铁","py":"dìtiě","vi":"tàu điện ngầm","hv":"địa thiết","note":"地 (đất) + 铁 (sắt, bộ 钅 kim loại) — \"đường sắt dưới đất\". Cách gọi rất trực quan.","ex":"从这儿到机场坐地铁最快。","exPy":"Cóng zhèr dào jīchǎng zuò dìtiě zuì kuài.","exVi":"Từ đây ra sân bay đi tàu điện ngầm là nhanh nhất.","w":"从 这儿 到 机场 坐 地铁 最 快。"},{"zh":"船","py":"chuán","vi":"thuyền, tàu thuỷ","hv":"thuyền","note":"Chính là chữ \"thuyền\" tiếng Việt. Bên trái là 舟 (con thuyền) — bộ thủ hình chiếc thuyền.","ex":"夏天我们可以坐船去玩。","exPy":"Xiàtiān wǒmen kěyǐ zuò chuán qù wán.","exVi":"Mùa hè chúng ta có thể đi thuyền chơi.","w":"夏天 我们 可以 坐 船 去 玩。"},{"zh":"地图","py":"dìtú","vi":"bản đồ","hv":"địa đồ","note":"地 (đất) + 图 (hình vẽ). Tiếng Việt có \"địa đồ\" trong văn cổ, nay nói \"bản đồ\".","ex":"你有地图吗？我不认识路。","exPy":"Nǐ yǒu dìtú ma? Wǒ bú rènshi lù.","exVi":"Bạn có bản đồ không? Tôi không biết đường.","w":"你 有 地图 吗？ 我 不 认识 路。"},{"zh":"站","py":"zhàn","vi":"ga, bến; đứng","hv":"trạm","note":"Chính là \"trạm\" tiếng Việt. Vừa là danh từ (bến, ga) vừa là động từ (đứng): 站起来 = đứng dậy.","ex":"下一站下车。","exPy":"Xià yí zhàn xià chē.","exVi":"Ga sau thì xuống xe.","w":"下 一 站 下 车。"},{"zh":"楼","py":"lóu","vi":"toà nhà; tầng","hv":"lâu","note":"Chính là \"lầu\" tiếng Việt. Bộ 木 (gỗ) vì nhà xưa làm bằng gỗ. 上楼 lên lầu, 下楼 xuống lầu.","ex":"我住在这座楼的八层。","exPy":"Wǒ zhù zài zhè zuò lóu de bā céng.","exVi":"Tôi ở tầng tám của toà nhà này.","w":"我 住 在 这 座 楼 的 八 层。"},{"zh":"层","py":"céng","vi":"tầng (lượng từ)","hv":"tằng","note":"Chính là chữ \"tầng\" tiếng Việt. Bộ 尸 ở trên. Khác 楼 ở cách dùng — xem phần ngữ pháp.","ex":"这座楼有二十层。","exPy":"Zhè zuò lóu yǒu èrshí céng.","exVi":"Toà nhà này có hai mươi tầng.","w":"这 座 楼 有 二 十 层。"},{"zh":"电梯","py":"diàntī","vi":"thang máy","hv":"điện thê","note":"电 (điện) + 梯 (thang, bộ 木 gỗ). Lại một thành viên của \"gia đình chữ 电\" ở bài 13.","ex":"电梯坏了，我们走楼梯吧。","exPy":"Diàntī huài le, wǒmen zǒu lóutī ba.","exVi":"Thang máy hỏng rồi, ta đi cầu thang bộ nhé.","w":"电梯 坏 了， 我们 走 楼梯 吧。"},{"zh":"骑","py":"qí","vi":"cưỡi, đi (xe hai bánh)","hv":"kỵ","note":"Bộ 马 (ngựa) bên trái. Tiếng Việt: \"kỵ binh\", \"kỵ sĩ\". Dùng cho thứ phải dạng chân: ngựa, xe đạp, xe máy.","ex":"他每天骑自行车上班。","exPy":"Tā měi tiān qí zìxíngchē shàngbān.","exVi":"Ngày nào anh ấy cũng đạp xe đi làm.","w":"他 每 天 骑 自行车 上班。"},{"zh":"离开","py":"líkāi","vi":"rời khỏi","hv":"ly khai","note":"离 (bài 24, khoảng cách) + 开 (mở, rời ra). Tiếng Việt: \"ly khai\", \"chia ly\".","ex":"他去年离开了这个城市。","exPy":"Tā qùnián líkāi le zhège chéngshì.","exVi":"Năm ngoái anh ấy rời thành phố này.","w":"他 去年 离开 了 这个 城市。"},{"zh":"接","py":"jiē","vi":"đón; nhận, nghe (máy)","hv":"tiếp","note":"Bộ 扌 (tay). Tiếng Việt: \"tiếp đón\", \"tiếp nhận\". 接电话 = nghe điện thoại, 接朋友 = đón bạn.","ex":"明天几点去机场接他？","exPy":"Míngtiān jǐ diǎn qù jīchǎng jiē tā?","exVi":"Mai mấy giờ ra sân bay đón anh ấy?","w":"明天 几 点 去 机场 接 他？"}],"newChars":["铁","船","楼","层","梯","骑"],"outro":"很好！Xong bài 58."};
G.ROOMS["zh-l059"] = {"id":"zh-l059","lang":"zh","level":3,"no":59,"teacher":"wang","title":"HSK3 · Bài 59 · 买东西付钱 Tiền bạc và mua sắm","intro":["一共多少钱？","Bài 59: Trả tiền, đổi tiền, mượn đồ — và phân biệt ba động từ cầm nắm 带 / 拿 / 借. Bấm 1 · Học để bắt đầu."],"introPy":"Yígòng duōshao qián?","gram":{"t":"Tiếng Trung đếm theo VẠN, không theo nghìn","b":"一万 = 10.000 · 十万 = 100.000 · 一百万 = 1.000.000","d":"Đây là chỗ người Việt hay bối rối vì tiếng Việt đếm theo nghìn và triệu. Người Trung Quốc nhảy bậc ở 万 (vạn) và 亿 (ức = 100 triệu). Mẹo: gặp số lớn, hãy tách nhóm bốn chữ số từ phải sang chứ không phải ba.","ex":[["一万","10.000 (một vạn)","yí wàn"],["二十万","200.000 (hai mươi vạn)","èrshí wàn"],["一百万","1.000.000 (một trăm vạn)","yìbǎi wàn"]]},"grams":[{"t":"Tiếng Trung đếm theo VẠN, không theo nghìn","b":"一万 = 10.000 · 十万 = 100.000 · 一百万 = 1.000.000","d":"Đây là chỗ người Việt hay bối rối vì tiếng Việt đếm theo nghìn và triệu. Người Trung Quốc nhảy bậc ở 万 (vạn) và 亿 (ức = 100 triệu). Mẹo: gặp số lớn, hãy tách nhóm bốn chữ số từ phải sang chứ không phải ba.","ex":[["一万","10.000 (một vạn)","yí wàn"],["二十万","200.000 (hai mươi vạn)","èrshí wàn"],["一百万","1.000.000 (một trăm vạn)","yìbǎi wàn"]]},{"t":"带 / 拿 / 借 — ba kiểu cầm lấy","b":"带 = mang theo mình · 拿 = cầm bằng tay · 借 = mượn","d":"带钱包 (mang ví theo người, có thể trong túi). 拿杯子 (cầm cái cốc trong tay ngay lúc này). 借书 (mượn sách, sẽ trả lại). Ba động từ này người Việt rất hay dùng lẫn.","ex":[["出门要带护照。","Ra ngoài phải mang hộ chiếu.","Chūmén yào dài hùzhào."],["请帮我拿一下包。","Cầm hộ tôi cái túi với.","Qǐng bāng wǒ ná yíxià bāo."],["这本书是我借的。","Quyển sách này tôi mượn.","Zhè běn shū shì wǒ jiè de."]]},{"t":"花 + thời gian/tiền + động từ","b":"花 + số lượng + 动词","d":"花 dùng được cho cả tiền lẫn thời gian. 我花了三百块买这件衣服 / 我花了两个小时做作业. Cấu trúc giống hệt tiếng Việt \"tiêu ba trăm để mua…\", \"mất hai tiếng để làm…\".","ex":[["我花了两百块买这双鞋。","Tôi tiêu hai trăm để mua đôi giày này.","Wǒ huā le liǎngbǎi kuài mǎi zhè shuāng xié."],["他每天花一个小时学中文。","Ngày nào anh ấy cũng dành một tiếng học tiếng Trung.","Tā měi tiān huā yí ge xiǎoshí xué Zhōngwén."]]}],"items":[{"zh":"元","py":"yuán","vi":"đồng (đơn vị tiền, văn viết)","hv":"nguyên","note":"Dạng VIẾT trang trọng của 块 (bài 22). Trên hoá đơn và bảng giá luôn ghi 元, nhưng nói miệng thì dùng 块.","ex":"一共一百二十元。","exPy":"Yígòng yìbǎi èrshí yuán.","exVi":"Tổng cộng một trăm hai mươi đồng.","w":"一共 一 百 二 十 元。"},{"zh":"万","py":"wàn","vi":"mười nghìn, vạn","hv":"vạn","note":"Chính là \"vạn\" tiếng Việt. QUAN TRỌNG: tiếng Trung đếm theo VẠN chứ không theo nghìn — 100.000 là 十万 (mười vạn), không phải \"một trăm nghìn\".","ex":"这台电脑要一万多块。","exPy":"Zhè tái diànnǎo yào yí wàn duō kuài.","exVi":"Cái máy tính này hơn một vạn đồng.","w":"这 台 电脑 要 一 万 多 块。"},{"zh":"花","py":"huā","vi":"bông hoa; tiêu (tiền, thời gian)","hv":"hoa","note":"Bộ 艹 (cỏ cây). Hai nghĩa: bông hoa và TIÊU TIỀN. Tiếng Việt cũng nói \"tiêu hoa\", \"hoa phí\".","ex":"这个月我花了很多钱。","exPy":"Zhège yuè wǒ huā le hěn duō qián.","exVi":"Tháng này tôi tiêu nhiều tiền quá.","w":"这个 月 我 花 了 很 多 钱。"},{"zh":"信用卡","py":"xìnyòngkǎ","vi":"thẻ tín dụng","hv":"tín dụng ca","note":"信用 chính là \"tín dụng\" tiếng Việt. 卡 kǎ là từ mượn âm của \"card\".","ex":"可以用信用卡付钱吗？","exPy":"Kěyǐ yòng xìnyòngkǎ fùqián ma?","exVi":"Trả bằng thẻ tín dụng được không?","w":"可以 用 信用卡 付 钱 吗？"},{"zh":"礼物","py":"lǐwù","vi":"món quà","hv":"lễ vật","note":"Chính là \"lễ vật\" tiếng Việt: 礼 (lễ) + 物 (vật). Tặng quà là 送礼物 (bài 27 đã học 送).","ex":"我买了一个礼物送给妈妈。","exPy":"Wǒ mǎi le yí ge lǐwù sòng gěi māma.","exVi":"Tôi mua một món quà tặng mẹ.","w":"我 买 了 一 个 礼物 送 给 妈妈。"},{"zh":"一共","py":"yígòng","vi":"tổng cộng","hv":"nhất cộng","note":"共 = \"cộng\" trong \"công cộng\", \"tổng cộng\". Đứng trước con số tổng.","ex":"一共多少钱？","exPy":"Yígòng duōshao qián?","exVi":"Tổng cộng bao nhiêu tiền?","w":"一共 多少 钱？"},{"zh":"换","py":"huàn","vi":"đổi, thay","hv":"hoán","note":"Bộ 扌 (tay). Tiếng Việt: \"hoán đổi\", \"trao đổi\", \"chuyển hoán\".","ex":"这件太小了，我想换一件。","exPy":"Zhè jiàn tài xiǎo le, wǒ xiǎng huàn yí jiàn.","exVi":"Cái này nhỏ quá, tôi muốn đổi cái khác.","w":"这 件 太 小 了， 我 想 换 一 件。"},{"zh":"借","py":"jiè","vi":"mượn; cho mượn","hv":"tá","note":"Thú vị: 借 dùng cho CẢ HAI chiều. 我借你的书 (tôi mượn sách của bạn) và 我借给你 (tôi cho bạn mượn). Nhìn giới từ để biết chiều.","ex":"我可以借你的笔用一下吗？","exPy":"Wǒ kěyǐ jiè nǐ de bǐ yòng yíxià ma?","exVi":"Tôi mượn bút của bạn một chút được không?","w":"我 可以 借 你 的 笔 用 一下 吗？"},{"zh":"带","py":"dài","vi":"mang theo; dẫn theo","hv":"đới","note":"Có bộ 巾 (khăn vải) ở dưới — vốn là cái thắt lưng để đeo đồ. Nhấn vào việc MANG ĐI CÙNG.","ex":"出门别忘了带手机。","exPy":"Chūmén bié wàng le dài shǒujī.","exVi":"Ra ngoài đừng quên mang điện thoại.","w":"出门 别 忘 了 带 手机。"},{"zh":"拿","py":"ná","vi":"cầm, lấy","hv":"nã","note":"合 (hợp) trên 手 (tay) — khép bàn tay lại mà cầm. Nhấn vào động tác CẦM BẰNG TAY.","ex":"请把那本词典拿给我。","exPy":"Qǐng bǎ nà běn cídiǎn ná gěi wǒ.","exVi":"Đưa giúp tôi quyển từ điển kia.","w":"请 把 那 本 词典 拿 给 我。"}],"newChars":["元","花","用","卡","换","借","带","拿"],"outro":"很好！Xong bài 59."};
G.ROOMS["zh-l060"] = {"id":"zh-l060","lang":"zh","level":3,"no":60,"teacher":"wang","title":"HSK3 · Bài 60 · 买衣服 Quần áo và lượng từ","intro":["我想买一件衬衫和一条裤子。","Bài 60: Gọi tên trang phục, dùng đúng lượng từ 件 / 条 / 双 / 顶 — và cảnh giác một cái bẫy Hán Việt. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ xiǎng mǎi yí jiàn chènshān hé yì tiáo kùzi.","gram":{"t":"Bảng lượng từ cần thuộc","b":"件 áo · 条 vật dài · 双 đôi · 张 vật phẳng · 顶 mũ · 位 người (lịch sự)","d":"Đây là phần người Việt học nhanh vì tiếng Việt cũng có \"chiếc, con, tấm, đôi, vị\". Mẹo: hình dạng quyết định lượng từ — dài thì 条, phẳng thì 张, có đôi thì 双.","ex":[["一件衬衫 · 一条裤子","một áo sơ mi · một cái quần","yí jiàn chènshān · yì tiáo kùzi"],["一双鞋 · 一张票","một đôi giày · một tấm vé","yì shuāng xié · yì zhāng piào"],["两位老师","hai vị giáo viên","liǎng wèi lǎoshī"]]},"grams":[{"t":"Bảng lượng từ cần thuộc","b":"件 áo · 条 vật dài · 双 đôi · 张 vật phẳng · 顶 mũ · 位 người (lịch sự)","d":"Đây là phần người Việt học nhanh vì tiếng Việt cũng có \"chiếc, con, tấm, đôi, vị\". Mẹo: hình dạng quyết định lượng từ — dài thì 条, phẳng thì 张, có đôi thì 双.","ex":[["一件衬衫 · 一条裤子","một áo sơ mi · một cái quần","yí jiàn chènshān · yì tiáo kùzi"],["一双鞋 · 一张票","một đôi giày · một tấm vé","yì shuāng xié · yì zhāng piào"],["两位老师","hai vị giáo viên","liǎng wèi lǎoshī"]]},{"t":"Bẫy Hán Việt: 裙 là VÁY, không phải quần","b":"裙子 = váy · 裤子 = quần","d":"Âm Hán Việt của 裙 là \"quần\" nên người Việt rất dễ hiểu ngược. Nhớ mẹo: 裤 có chữ 库 (kho) — cái quần như hai cái kho úp xuống chân. Đây là bài học rằng âm Hán Việt là bạn tốt nhưng đôi khi cũng đánh lừa.","ex":[["她穿裙子，他穿裤子。","Cô ấy mặc váy, anh ấy mặc quần.","Tā chuān qúnzi, tā chuān kùzi."]]},{"t":"戴 và 穿 — nhắc lại từ bài 21","b":"穿 áo quần giày · 戴 mũ kính đồng hồ","d":"帽子 dùng 戴 chứ không dùng 穿: 戴帽子. Cũng như 戴眼镜 (đeo kính), 戴手表 (đeo đồng hồ).","ex":[["今天很冷，戴上帽子吧。","Hôm nay lạnh, đội mũ vào đi.","Jīntiān hěn lěng, dài shàng màozi ba."]]}],"items":[{"zh":"衬衫","py":"chènshān","vi":"áo sơ mi","hv":"sấn sam","note":"Cả hai chữ đều có bộ 衤 (áo quần) — nhìn bộ là biết ngay chủ đề. Lượng từ: 一件衬衫.","ex":"我想买一件衬衫和一条裤子。","exPy":"Wǒ xiǎng mǎi yí jiàn chènshān hé yì tiáo kùzi.","exVi":"Tôi muốn mua một áo sơ mi và một cái quần.","w":"我 想 买 一 件 衬衫 和 一 条 裤子。"},{"zh":"裙子","py":"qúnzi","vi":"cái váy","hv":"quần tử","note":"CẨN THẬN — bẫy Hán Việt: 裙 đọc Hán Việt là \"quần\" nhưng nghĩa là VÁY, không phải cái quần. Cái quần là 裤子.","ex":"这条裙子多少钱？","exPy":"Zhè tiáo qúnzi duōshao qián?","exVi":"Chiếc váy này bao nhiêu tiền?","w":"这 条 裙子 多少 钱？"},{"zh":"裤子","py":"kùzi","vi":"cái quần","hv":"khố tử","note":"Cũng có bộ 衤. Tiếng Việt: \"khố\" là mảnh vải quấn thân của người xưa — cùng gốc chữ này.","ex":"我要买一条裤子。","exPy":"Wǒ yào mǎi yì tiáo kùzi.","exVi":"Tôi muốn mua một cái quần.","w":"我 要 买 一 条 裤子。"},{"zh":"帽子","py":"màozi","vi":"cái mũ","hv":"mạo tử","note":"Có bộ 巾 (khăn vải) bên trái. Lượng từ đúng là 顶 dǐng, nhưng dùng 个 cũng được trong khẩu ngữ.","ex":"外面下雨，记得戴帽子。","exPy":"Wàimiàn xiàyǔ, jìde dài màozi.","exVi":"Ngoài trời mưa, nhớ đội mũ.","w":"外面 下雨， 记得 戴 帽子。"},{"zh":"双","py":"shuāng","vi":"đôi (lượng từ)","hv":"song","note":"Chính là \"song\" trong \"song sinh\", \"song phương\". Hai chữ 又 (bàn tay) ghép lại — hai cái tay là một đôi.","ex":"我穿这双鞋有点儿小。","exPy":"Wǒ chuān zhè shuāng xié yǒudiǎnr xiǎo.","exVi":"Tôi đi đôi giày này hơi chật.","w":"我 穿 这 双 鞋 有点儿 小。"},{"zh":"条","py":"tiáo","vi":"cái, con (vật dài)","hv":"điều","note":"Dùng cho mọi thứ DÀI: 一条路 (con đường), 一条鱼 (con cá), 一条裤子, 一条河. Tiếng Việt: \"điều\", \"điều kiện\".","ex":"一条裙子","exPy":"yì tiáo qúnzi","exVi":"một chiếc váy","w":"一 条 裙子"},{"zh":"张","py":"zhāng","vi":"tờ, tấm, cái (vật phẳng)","hv":"trương","note":"Dùng cho vật PHẲNG: 一张纸 (tờ giấy), 一张桌子 (cái bàn), 一张票, 一张照片. Cũng là một họ rất phổ biến.","ex":"请给我两张纸。","exPy":"Qǐng gěi wǒ liǎng zhāng zhǐ.","exVi":"Cho tôi xin hai tờ giấy.","w":"请 给 我 两 张 纸。"},{"zh":"位","py":"wèi","vi":"vị (lượng từ lịch sự cho người)","hv":"vị","note":"Chính là \"vị\" tiếng Việt (\"quý vị\", \"các vị\"). Lịch sự hơn 个 nhiều — dùng với khách, thầy cô, người lớn tuổi.","ex":"这位是我们的经理。","exPy":"Zhè wèi shì wǒmen de jīnglǐ.","exVi":"Vị này là giám đốc của chúng tôi.","w":"这 位 是 我们 的 经理。"},{"zh":"包","py":"bāo","vi":"cái túi, cặp; gói","hv":"bao","note":"Chính là \"bao\" tiếng Việt. Cũng là bộ thủ 勹 (bao bọc) đã học. Vừa là danh từ (túi) vừa là động từ (gói).","ex":"你的包放在哪儿了？","exPy":"Nǐ de bāo fàng zài nǎr le?","exVi":"Túi của bạn để đâu rồi?","w":"你 的 包 放 在 哪儿 了？"},{"zh":"行李箱","py":"xínglixiāng","vi":"va li","hv":"hành lý tương","note":"行李 chính là \"hành lý\" tiếng Việt. 箱 (thùng, hòm) có bộ 竹 vì hòm xưa đan bằng tre.","ex":"我的行李箱里有很多衣服。","exPy":"Wǒ de xínglixiāng lǐ yǒu hěn duō yīfu.","exVi":"Trong va li tôi có nhiều quần áo.","w":"我 的 行李箱 里 有 很 多 衣服。"}],"newChars":["衬","衫","裙","裤","帽","双","张","位","包","李","箱"],"outro":"很好！Xong bài 60."};
G.ROOMS["zh-l061"] = {"id":"zh-l061","lang":"zh","level":3,"no":61,"teacher":"wang","title":"HSK3 · Bài 61 · 家里的东西 Đồ đạc trong nhà","intro":["请把牛奶放进冰箱。","Bài 61: Gọi tên đồ dùng gia đình, nói việc dọn dẹp chuyển nhà, và dùng cấu trúc 把. Bấm 1 · Học để bắt đầu."],"introPy":"Qǐng bǎ niúnǎi fàng jìn bīngxiāng.","gram":{"t":"Câu chữ 把 — điểm ngữ pháp KHÓ NHẤT của HSK 3","b":"Chủ ngữ + 把 + tân ngữ + động từ + kết quả","d":"Bình thường tiếng Trung là Chủ-Động-Tân. Câu 把 đảo tân ngữ lên TRƯỚC động từ để nhấn mạnh \"xử lý cái đó thế nào\". Bắt buộc phải có phần KẾT QUẢ sau động từ (放在…上, 拿走, 打扫干净) — nói 我把书 rồi dừng là sai.","ex":[["请把盘子放在桌子上。","Xin đặt đĩa lên bàn.","Qǐng bǎ pánzi fàng zài zhuōzi shàng."],["我把房间打扫干净了。","Tôi đã dọn phòng sạch sẽ rồi.","Wǒ bǎ fángjiān dǎsǎo gānjìng le."],["他把我的伞拿走了。","Anh ấy lấy mất cái ô của tôi rồi.","Tā bǎ wǒ de sǎn ná zǒu le."]]},"grams":[{"t":"Câu chữ 把 — điểm ngữ pháp KHÓ NHẤT của HSK 3","b":"Chủ ngữ + 把 + tân ngữ + động từ + kết quả","d":"Bình thường tiếng Trung là Chủ-Động-Tân. Câu 把 đảo tân ngữ lên TRƯỚC động từ để nhấn mạnh \"xử lý cái đó thế nào\". Bắt buộc phải có phần KẾT QUẢ sau động từ (放在…上, 拿走, 打扫干净) — nói 我把书 rồi dừng là sai.","ex":[["请把盘子放在桌子上。","Xin đặt đĩa lên bàn.","Qǐng bǎ pánzi fàng zài zhuōzi shàng."],["我把房间打扫干净了。","Tôi đã dọn phòng sạch sẽ rồi.","Wǒ bǎ fángjiān dǎsǎo gānjìng le."],["他把我的伞拿走了。","Anh ấy lấy mất cái ô của tôi rồi.","Tā bǎ wǒ de sǎn ná zǒu le."]]},{"t":"Khi nào PHẢI dùng 把","b":"Khi tân ngữ là thứ XÁC ĐỊNH và bị TÁC ĐỘNG thay đổi","d":"Nói 我打扫房间 cũng được (chỉ kể việc). Nhưng muốn nói rõ căn phòng ĐÃ THÀNH sạch thì phải dùng 把: 我把房间打扫干净了. Mẹo: hễ có kết quả rõ rệt tác động lên vật, hãy nghĩ tới 把.","ex":[["我把作业写完了。","Tôi viết xong bài tập rồi.","Wǒ bǎ zuòyè xiě wán le."],["请把门关上。","Xin đóng cửa lại.","Qǐng bǎ mén guān shàng."]]},{"t":"开 và 关 — cặp bật/tắt, mở/đóng","b":"开灯 / 关灯 · 开门 / 关门 · 开空调 / 关空调","d":"开 (bài 12) và 关 dùng cho cả thiết bị điện lẫn cửa nẻo. Rất tiện: học một cặp dùng được cho hàng chục tình huống.","ex":[["天黑了，开灯吧。","Trời tối rồi, bật đèn đi.","Tiān hēi le, kāi dēng ba."],["出门前关好门窗。","Trước khi ra ngoài đóng kỹ cửa.","Chūmén qián guān hǎo ménchuāng."]]}],"items":[{"zh":"冰箱","py":"bīngxiāng","vi":"tủ lạnh","hv":"băng tương","note":"冰 (băng, đá) có bộ 冫 (hai chấm băng) + 箱 (thùng) = \"thùng băng\". Rất dễ đoán.","ex":"请把牛奶放进冰箱。","exPy":"Qǐng bǎ niúnǎi fàng jìn bīngxiāng.","exVi":"Xin cho sữa vào tủ lạnh.","w":"请 把 牛奶 放 进 冰箱。"},{"zh":"空调","py":"kōngtiáo","vi":"máy điều hoà","hv":"không điều","note":"空气 (không khí) + 调节 (điều tiết) = \"điều hoà không khí\". Tiếng Việt gọi tắt là \"điều hoà\" — cùng một cách rút gọn.","ex":"房间里太热，开空调吧。","exPy":"Fángjiān lǐ tài rè, kāi kōngtiáo ba.","exVi":"Trong phòng nóng quá, bật điều hoà đi.","w":"房间 里 太 热， 开 空调 吧。"},{"zh":"灯","py":"dēng","vi":"cái đèn","hv":"đăng","note":"Bộ 火 (lửa) bên trái — đèn xưa đốt bằng lửa. Tiếng Việt: \"hoa đăng\", \"đèn\". Bật đèn 开灯, tắt đèn 关灯.","ex":"睡觉前记得关灯。","exPy":"Shuìjiào qián jìde guān dēng.","exVi":"Trước khi ngủ nhớ tắt đèn.","w":"睡觉 前 记得 关 灯。"},{"zh":"盘子","py":"pánzi","vi":"cái đĩa","hv":"bàn tử","note":"Có bộ 皿 (đồ đựng) ở dưới — cùng bộ với 碗. Nhìn bộ này là biết đồ dùng nhà bếp.","ex":"请给我一个盘子和一个碗。","exPy":"Qǐng gěi wǒ yí ge pánzi hé yí ge wǎn.","exVi":"Cho tôi một cái đĩa và một cái bát.","w":"请 给 我 一 个 盘子 和 一 个 碗。"},{"zh":"碗","py":"wǎn","vi":"cái bát; bát (lượng từ)","hv":"uyển","note":"Bộ 石 (đá) — bát xưa nặn từ đất đá. Vừa là đồ vật vừa là lượng từ: 一碗米饭 (một bát cơm).","ex":"我要一碗面。","exPy":"Wǒ yào yì wǎn miàn.","exVi":"Cho tôi một bát mì.","w":"我 要 一 碗 面。"},{"zh":"筷子","py":"kuàizi","vi":"đôi đũa","hv":"khoái tử","note":"Bộ 竹 (tre) ở trên vì đũa làm bằng tre. Lượng từ là 双 (đôi): 一双筷子.","ex":"中国人吃饭用筷子。","exPy":"Zhōngguó rén chīfàn yòng kuàizi.","exVi":"Người Trung Quốc ăn cơm bằng đũa.","w":"中国 人 吃 饭 用 筷子。"},{"zh":"伞","py":"sǎn","vi":"cái ô, cái dù","hv":"tán","note":"Chữ TƯỢNG HÌNH đẹp nhất tiếng Trung: nhìn đúng như cái ô đang mở, có cán và nan. Tiếng Việt: \"tán\" (cái lọng).","ex":"外面下雨了，你带伞了吗？","exPy":"Wàimiàn xiàyǔ le, nǐ dài sǎn le ma?","exVi":"Ngoài trời mưa rồi, bạn mang ô chưa?","w":"外面 下雨 了， 你 带 伞 了 吗？"},{"zh":"干净","py":"gānjìng","vi":"sạch sẽ","hv":"can tịnh","note":"净 = \"tịnh\" trong \"thanh tịnh\", \"tịnh khiết\". Trái nghĩa là 脏 zāng (bẩn).","ex":"你的房间真干净。","exPy":"Nǐ de fángjiān zhēn gānjìng.","exVi":"Phòng bạn sạch thật đấy.","w":"你 的 房间 真 干净。"},{"zh":"打扫","py":"dǎsǎo","vi":"quét dọn","hv":"đả tảo","note":"打 (làm) + 扫 (quét). Cả hai đều có bộ 扌 (tay). Tiếng Việt: \"tảo\" trong \"tảo mộ\" (dọn mộ).","ex":"每个周末我都打扫一次房间。","exPy":"Měi ge zhōumò wǒ dōu dǎsǎo yí cì fángjiān.","exVi":"Cuối tuần nào tôi cũng dọn phòng một lần.","w":"每 个 周末 我 都 打扫 一 次 房间。"},{"zh":"搬","py":"bān","vi":"khiêng, dọn (nhà)","hv":"ban","note":"Bộ 扌 (tay). 搬家 = chuyển nhà, 搬东西 = khiêng đồ.","ex":"他们下个月要搬到新家去。","exPy":"Tāmen xià ge yuè yào bān dào xīn jiā qù.","exVi":"Tháng sau họ sẽ dọn sang nhà mới.","w":"他们 下 个 月 要 搬 到 新 家 去。"}],"newChars":["冰","调","灯","盘","碗","筷","伞","干","净","扫","搬"],"outro":"很好！Xong bài 61."};
G.ROOMS["zh-l062"] = {"id":"zh-l062","lang":"zh","level":3,"no":62,"teacher":"wang","title":"HSK3 · Bài 62 · 在饭馆 Ở quán ăn","intro":["服务员，请给我看看菜单。","Bài 62: Đọc thực đơn, gọi đồ uống, khen chê món ăn và dùng động từ lặp để nói \"thử một chút\". Bấm 1 · Học để bắt đầu."],"introPy":"Fúwùyuán, qǐng gěi wǒ kànkan càidān.","gram":{"t":"Động từ LẶP LẠI — làm nhẹ giọng đi","b":"试试 · 看看 · 尝尝 · 走走","d":"Lặp động từ hai lần nghĩa là \"làm một chút, thử xem\" — nghe nhẹ nhàng và thân thiện hơn hẳn. Tương đương với 一下 nhưng tự nhiên hơn trong khẩu ngữ. Từ hai chữ thì lặp cả khối: 打扫打扫, 休息休息.","ex":[["你试试。","Bạn thử xem.","Nǐ shìshi."],["我看看菜单。","Để tôi xem thực đơn chút.","Wǒ kànkan càidān."],["我们出去走走吧。","Chúng ta ra ngoài đi dạo chút đi.","Wǒmen chūqu zǒuzou ba."]]},"grams":[{"t":"Động từ LẶP LẠI — làm nhẹ giọng đi","b":"试试 · 看看 · 尝尝 · 走走","d":"Lặp động từ hai lần nghĩa là \"làm một chút, thử xem\" — nghe nhẹ nhàng và thân thiện hơn hẳn. Tương đương với 一下 nhưng tự nhiên hơn trong khẩu ngữ. Từ hai chữ thì lặp cả khối: 打扫打扫, 休息休息.","ex":[["你试试。","Bạn thử xem.","Nǐ shìshi."],["我看看菜单。","Để tôi xem thực đơn chút.","Wǒ kànkan càidān."],["我们出去走走吧。","Chúng ta ra ngoài đi dạo chút đi.","Wǒmen chūqu zǒuzou ba."]]},{"t":"来 dùng để gọi món","b":"来 + số lượng + món","d":"Trong quán ăn, 来 không có nghĩa \"đến\" mà nghĩa là \"cho tôi\". Đây là cách nói cực kỳ tự nhiên của người bản xứ: 来两瓶啤酒 nghe sành hơn 我要两瓶啤酒.","ex":[["来一碗米饭。","Cho một bát cơm.","Lái yì wǎn mǐfàn."],["再来一个菜。","Thêm một món nữa.","Zài lái yí ge cài."]]},{"t":"Các vị cơ bản","b":"甜 ngọt · 酸 chua · 苦 đắng · 辣 cay · 咸 mặn","d":"Người Trung Quốc gọi đây là 五味 (ngũ vị) — tiếng Việt cũng có \"ngũ vị hương\". Trong bài này bạn học 甜; bốn vị còn lại rất đáng nhớ luôn vì chúng xuất hiện khắp thực đơn.","ex":[["这个菜有点儿辣。","Món này hơi cay.","Zhège cài yǒudiǎnr là."],["葡萄又甜又新鲜。","Nho vừa ngọt vừa tươi.","Pútao yòu tián yòu xīnxiān."]]}],"items":[{"zh":"蛋糕","py":"dàngāo","vi":"bánh ngọt, bánh kem","hv":"đản cao","note":"蛋 (trứng, bài 23) + 糕 (bánh, bộ 米 gạo). Bánh sinh nhật là 生日蛋糕.","ex":"妈妈给我做了一个生日蛋糕。","exPy":"Māma gěi wǒ zuò le yí ge shēngrì dàngāo.","exVi":"Mẹ làm cho tôi một chiếc bánh sinh nhật.","w":"妈妈 给 我 做 了 一 个 生日 蛋糕。"},{"zh":"面包","py":"miànbāo","vi":"bánh mì","hv":"diện bao","note":"面 (diện — ở đây nghĩa là bột mì) + 包 (bao, bài 43). Nghĩa đen: gói bột — đúng là ổ bánh mì.","ex":"我早上一般吃面包喝牛奶。","exPy":"Wǒ zǎoshang yìbān chī miànbāo hē niúnǎi.","exVi":"Buổi sáng tôi thường ăn bánh mì uống sữa.","w":"我 早上 一般 吃 面包 喝 牛奶。"},{"zh":"香蕉","py":"xiāngjiāo","vi":"quả chuối","hv":"hương tiêu","note":"香 (thơm) + 蕉 (cây chuối). Cả hai đều có bộ 艹 hoặc liên quan cây cỏ. Tiếng Việt: \"hương thơm\".","ex":"香蕉和葡萄我都喜欢。","exPy":"Xiāngjiāo hé pútao wǒ dōu xǐhuan.","exVi":"Chuối và nho tôi đều thích.","w":"香蕉 和 葡萄 我 都 喜欢。"},{"zh":"葡萄","py":"pútao","vi":"quả nho","hv":"bồ đào","note":"Chính là \"bồ đào\" trong \"rượu bồ đào\" của thơ cổ Việt Nam. Cả hai chữ đều có bộ 艹.","ex":"这些葡萄很甜。","exPy":"Zhèxiē pútao hěn tián.","exVi":"Mấy quả nho này rất ngọt.","w":"这些 葡萄 很 甜。"},{"zh":"啤酒","py":"píjiǔ","vi":"bia","hv":"bia tửu","note":"啤 là mượn âm \"beer\", 酒 là \"tửu\" (rượu) có bộ 氵 (nước). Ghép âm Tây với chữ Hán.","ex":"来两瓶啤酒，谢谢。","exPy":"Lái liǎng píng píjiǔ, xièxie.","exVi":"Cho hai chai bia, cảm ơn.","w":"来 两 瓶 啤酒， 谢谢。"},{"zh":"饮料","py":"yǐnliào","vi":"đồ uống, nước ngọt","hv":"ẩm liệu","note":"饮 = \"ẩm\" trong \"ẩm thực\", có bộ 饣 (ăn uống). 料 = \"liệu\" (nguyên liệu).","ex":"你们要喝什么饮料？","exPy":"Nǐmen yào hē shénme yǐnliào?","exVi":"Các bạn uống gì?","w":"你们 要 喝 什么 饮料？"},{"zh":"菜单","py":"càidān","vi":"thực đơn","hv":"thái đơn","note":"菜 (món ăn, bài 9) + 单 (đơn, tờ). Tiếng Việt gọi là \"thực đơn\" — cùng chữ 单 (đơn).","ex":"服务员，请给我看看菜单。","exPy":"Fúwùyuán, qǐng gěi wǒ kànkan càidān.","exVi":"Bạn ơi, cho tôi xem thực đơn với.","w":"服务员， 请 给 我 看 看 菜单。"},{"zh":"甜","py":"tián","vi":"ngọt","hv":"điềm","note":"舌 (lưỡi) + 甘 (ngọt) — vị ngọt trên đầu lưỡi. Một chữ hội ý rất hay.","ex":"这个菜太甜了，我不太喜欢。","exPy":"Zhège cài tài tián le, wǒ bú tài xǐhuan.","exVi":"Món này ngọt quá, tôi không thích lắm.","w":"这个 菜 太 甜 了， 我 不 太 喜欢。"},{"zh":"新鲜","py":"xīnxiān","vi":"tươi, mới mẻ","hv":"tân tiên","note":"新 (mới, bài 21) + 鲜 (tươi) — mà 鲜 = 鱼 (cá) + 羊 (dê), hai thứ phải ăn thật tươi!","ex":"这里的鱼很新鲜。","exPy":"Zhèlǐ de yú hěn xīnxiān.","exVi":"Cá ở đây rất tươi.","w":"这里 的 鱼 很 新鲜。"},{"zh":"试","py":"shì","vi":"thử","hv":"thí","note":"Bộ 讠 (lời nói). Tiếng Việt: \"thí nghiệm\", \"khảo thí\". Thử đồ ăn, thử quần áo, thử làm — đều dùng 试.","ex":"你试试这个，很好吃。","exPy":"Nǐ shìshi zhège, hěn hǎochī.","exVi":"Bạn thử cái này đi, ngon lắm.","w":"你 试 试 这个， 很 好吃。"}],"newChars":["糕","香","蕉","葡","萄","啤","酒","饮","料","甜","鲜"],"outro":"很好！Xong bài 62."};
G.ROOMS["zh-l063"] = {"id":"zh-l063","lang":"zh","level":3,"no":63,"teacher":"wang","title":"HSK3 · Bài 63 · 自然和动物 Thiên nhiên và loài vật","intro":["今天太阳很大，别忘了戴帽子。","Bài 63: Nói về trời đất cây cối, và thấy cách người Trung Quốc ghép tên các loài vật. Bấm 1 · Học để bắt đầu."],"introPy":"Jīntiān tàiyáng hěn dà, bié wàng le dài màozi.","gram":{"t":"Ghép tên loài vật theo HÌNH DÁNG","b":"熊猫 gấu-mèo · 河马 ngựa-sông · 长颈鹿 hươu-cổ-dài","d":"Tiếng Trung ít mượn từ nước ngoài mà thích ghép chữ sẵn có để mô tả. Biết 熊 (gấu) và 猫 (mèo) là đoán ra 熊猫. Đây là lý do vốn từ tiếng Trung dễ mở rộng hơn tiếng Anh rất nhiều.","ex":[["熊猫","gấu + mèo = gấu trúc","xióngmāo"],["河马","sông + ngựa = hà mã","hémǎ"],["动物园","động vật + vườn = sở thú","dòngwùyuán"]]},"grams":[{"t":"Ghép tên loài vật theo HÌNH DÁNG","b":"熊猫 gấu-mèo · 河马 ngựa-sông · 长颈鹿 hươu-cổ-dài","d":"Tiếng Trung ít mượn từ nước ngoài mà thích ghép chữ sẵn có để mô tả. Biết 熊 (gấu) và 猫 (mèo) là đoán ra 熊猫. Đây là lý do vốn từ tiếng Trung dễ mở rộng hơn tiếng Anh rất nhiều.","ex":[["熊猫","gấu + mèo = gấu trúc","xióngmāo"],["河马","sông + ngựa = hà mã","hémǎ"],["动物园","động vật + vườn = sở thú","dòngwùyuán"]]},{"t":"Lượng từ cho động vật và cây cối","b":"只 con vật nhỏ · 匹 ngựa · 棵 cây · 条 cá, rắn","d":"一只鸟, 一只猫, 一只狗 (con vật nhỏ). Nhưng 一匹马 (ngựa) và 一棵树 (cây). Cá dùng 条 vì thân dài — nhớ quy tắc hình dạng ở bài 43.","ex":[["两只鸟 · 一匹马","hai con chim · một con ngựa","liǎng zhī niǎo · yì pǐ mǎ"],["三棵树 · 一条鱼","ba cái cây · một con cá","sān kē shù · yì tiáo yú"]]},{"t":"Thời tiết đều là ĐỘNG TỪ","b":"下雨 · 下雪 · 刮风 · 出太阳","d":"Nhắc lại bài 30: tiếng Trung coi hiện tượng thời tiết là hành động của trời. Không cần chủ ngữ, thêm 了 để báo tình hình đã đổi.","ex":[["刮风了，关上窗户吧。","Nổi gió rồi, đóng cửa sổ lại đi.","Guā fēng le, guān shàng chuānghu ba."],["出太阳了！","Nắng lên rồi!","Chū tàiyáng le!"]]}],"items":[{"zh":"太阳","py":"tàiyáng","vi":"mặt trời","hv":"thái dương","note":"Chính là \"thái dương\" tiếng Việt (\"thái dương hệ\"). 阳 là \"dương\" trong \"âm dương\".","ex":"今天太阳很大，别忘了戴帽子。","exPy":"Jīntiān tàiyáng hěn dà, bié wàng le dài màozi.","exVi":"Hôm nay nắng to, đừng quên đội mũ.","w":"今天 太阳 很 大， 别 忘 了 戴 帽子。"},{"zh":"月亮","py":"yuèliang","vi":"mặt trăng","hv":"nguyệt lượng","note":"月 (nguyệt, bài bộ thủ) + 亮 (sáng). Nghĩa đen: cái sáng của mặt trăng.","ex":"秋天的月亮特别亮。","exPy":"Qiūtiān de yuèliang tèbié liàng.","exVi":"Trăng mùa thu đặc biệt sáng.","w":"秋天 的 月亮 特别 亮。"},{"zh":"云","py":"yún","vi":"đám mây","hv":"vân","note":"Chính là \"vân\" tiếng Việt (\"vân vũ\", \"phong vân\"). Chữ giản thể chỉ còn 4 nét, rất dễ viết.","ex":"天上一片云也没有。","exPy":"Tiān shàng yí piàn yún yě méiyǒu.","exVi":"Trên trời không một gợn mây.","w":"天上 一 片 云 也 没有。"},{"zh":"刮风","py":"guā fēng","vi":"có gió, trời nổi gió","hv":"quát phong","note":"风 chính là \"phong\" tiếng Việt (\"phong ba\", \"cuồng phong\"). Như 下雨 và 下雪, thời tiết là ĐỘNG TỪ.","ex":"外面刮风了，有点儿冷。","exPy":"Wàimiàn guā fēng le, yǒudiǎnr lěng.","exVi":"Ngoài trời nổi gió, hơi lạnh.","w":"外面 刮风 了， 有点儿 冷。"},{"zh":"树","py":"shù","vi":"cái cây","hv":"thụ","note":"Bộ 木 (gỗ) bên trái. Tiếng Việt: \"thụ\" trong \"cổ thụ\", \"thụ mộc\". Lượng từ là 棵 kē.","ex":"我们家门前有一棵大树。","exPy":"Wǒmen jiā mén qián yǒu yì kē dà shù.","exVi":"Trước cửa nhà tôi có một cây to.","w":"我们 家 门 前 有 一 棵 大 树。"},{"zh":"草","py":"cǎo","vi":"cỏ","hv":"thảo","note":"Chính là bộ thủ 艹 (thảo) bạn đã học, viết ở dạng đầy đủ. Tiếng Việt: \"thảo nguyên\", \"thảo mộc\".","ex":"孩子们在草地上玩。","exPy":"Háizimen zài cǎodì shàng wán.","exVi":"Bọn trẻ chơi trên bãi cỏ.","w":"孩子 们 在 草地 上 玩。"},{"zh":"动物","py":"dòngwù","vi":"động vật","hv":"động vật","note":"Chính là \"động vật\" tiếng Việt: 动 (động, chuyển động) + 物 (vật). Sở thú là 动物园.","ex":"周末我们去动物园看熊猫吧。","exPy":"Zhōumò wǒmen qù dòngwùyuán kàn xióngmāo ba.","exVi":"Cuối tuần chúng ta đi sở thú xem gấu trúc nhé.","w":"周末 我们 去 动物园 看 熊猫 吧。"},{"zh":"熊猫","py":"xióngmāo","vi":"gấu trúc","hv":"hùng miêu","note":"熊 (gấu) + 猫 (mèo) = \"gấu mèo\". Người Trung Quốc gọi gấu trúc theo hình dáng — con gấu có mặt như mèo.","ex":"熊猫又可爱又有名。","exPy":"Xióngmāo yòu kě'ài yòu yǒumíng.","exVi":"Gấu trúc vừa đáng yêu vừa nổi tiếng.","w":"熊猫 又 可爱 又 有名。"},{"zh":"鸟","py":"niǎo","vi":"con chim","hv":"điểu","note":"Bộ thủ đã học. Tiếng Việt: \"điểu\" trong \"phi điểu\", \"đà điểu\". Lượng từ là 只 zhī.","ex":"早上我听见鸟在唱歌。","exPy":"Zǎoshang wǒ tīngjiàn niǎo zài chànggē.","exVi":"Buổi sáng tôi nghe chim hót.","w":"早上 我 听见 鸟 在 唱歌。"},{"zh":"马","py":"mǎ","vi":"con ngựa","hv":"mã","note":"Bộ thủ đã học. Tiếng Việt: \"mã\" trong \"xa mã\", \"mã lực\". Cưỡi ngựa là 骑马 (bài 41).","ex":"我第一次骑马，有点儿害怕。","exPy":"Wǒ dì-yī cì qí mǎ, yǒudiǎnr hàipà.","exVi":"Lần đầu cưỡi ngựa, tôi hơi sợ.","w":"我 第一 次 骑 马， 有点儿 害怕。"}],"newChars":["阳","云","刮","风","树","草","熊","鸟","马"],"outro":"很好！Xong bài 63."};
G.ROOMS["zh-l064"] = {"id":"zh-l064","lang":"zh","level":3,"no":64,"teacher":"wang","title":"HSK3 · Bài 64 · 春夏秋冬 Bốn mùa và ngày lễ","intro":["你最喜欢哪个季节？","Bài 64: Nói về mùa và dịp lễ, kể chuyện quá khứ bằng 以前 / 后来 — bài dễ nhớ nhất với người Việt. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ zuì xǐhuan nǎge jìjié?","gram":{"t":"Bốn mùa: xuân hạ thu đông, giống hệt tiếng Việt","b":"春天 · 夏天 · 秋天 · 冬天","d":"Bốn chữ này người Việt đã thuộc lòng từ trước khi học tiếng Trung. Thêm 天 (trời) vào sau là thành tên mùa đầy đủ. Một bài gần như miễn phí cho bạn.","ex":[["一年有四个季节：春、夏、秋、冬。","Một năm có bốn mùa: xuân, hạ, thu, đông.","Yì nián yǒu sì ge jìjié: chūn, xià, qiū, dōng."]]},"grams":[{"t":"Bốn mùa: xuân hạ thu đông, giống hệt tiếng Việt","b":"春天 · 夏天 · 秋天 · 冬天","d":"Bốn chữ này người Việt đã thuộc lòng từ trước khi học tiếng Trung. Thêm 天 (trời) vào sau là thành tên mùa đầy đủ. Một bài gần như miễn phí cho bạn.","ex":[["一年有四个季节：春、夏、秋、冬。","Một năm có bốn mùa: xuân, hạ, thu, đông.","Yì nián yǒu sì ge jìjié: chūn, xià, qiū, dōng."]]},{"t":"后来 và 以后 — đừng dùng lẫn","b":"后来 = về sau (CHỈ quá khứ) · 以后 = sau này (quá khứ và tương lai)","d":"Kể chuyện đã qua thì dùng 后来: 后来他走了. Nói dự định tương lai phải dùng 以后: 以后我要去中国. Nói 后来我要去中国 là SAI.","ex":[["后来我们就没见过面。","Về sau chúng tôi không gặp lại nữa. (quá khứ)","Hòulái wǒmen jiù méi jiàn guo miàn."],["以后我想当老师。","Sau này tôi muốn làm giáo viên. (tương lai)","Yǐhòu wǒ xiǎng dāng lǎoshī."]]},{"t":"以前 đặt sau mệnh đề","b":"[việc gì] + 以前","d":"Ngược với tiếng Việt. Ta nói \"TRƯỚC KHI ăn cơm\", tiếng Trung nói \"ăn cơm TRƯỚC\": 吃饭以前. Tương tự 以后: 下课以后 (sau khi tan học).","ex":[["吃饭以前要洗手。","Trước khi ăn phải rửa tay.","Chīfàn yǐqián yào xǐ shǒu."],["来中国以前，我不会说汉语。","Trước khi sang Trung Quốc, tôi không biết nói tiếng Trung.","Lái Zhōngguó yǐqián, wǒ bú huì shuō Hànyǔ."]]}],"items":[{"zh":"春","py":"chūn","vi":"mùa xuân","hv":"xuân","note":"Chính là \"xuân\" tiếng Việt. Có bộ 日 (mặt trời) ở dưới. Nói đủ là 春天.","ex":"春节是中国最重要的节日。","exPy":"Chūnjié shì Zhōngguó zuì zhòngyào de jiérì.","exVi":"Tết Nguyên Đán là ngày lễ quan trọng nhất Trung Quốc.","w":"春 节 是 中国 最 重要 的 节日。"},{"zh":"夏","py":"xià","vi":"mùa hè","hv":"hạ","note":"Chính là \"hạ\" tiếng Việt (\"mùa hạ\", \"hạ chí\"). Nói đủ là 夏天.","ex":"越南的夏天又热又长。","exPy":"Yuènán de xiàtiān yòu rè yòu cháng.","exVi":"Mùa hè Việt Nam vừa nóng vừa dài.","w":"越 南 的 夏天 又 热 又 长。"},{"zh":"秋","py":"qiū","vi":"mùa thu","hv":"thu","note":"Chính là \"thu\" tiếng Việt. 禾 (lúa) + 火 (lửa) — lúa chín vàng như lửa, đúng là mùa gặt.","ex":"我最喜欢秋天，不冷也不热。","exPy":"Wǒ zuì xǐhuan qiūtiān, bù lěng yě bú rè.","exVi":"Tôi thích mùa thu nhất, không lạnh cũng không nóng.","w":"我 最 喜欢 秋天， 不 冷 也 不 热。"},{"zh":"冬","py":"dōng","vi":"mùa đông","hv":"đông","note":"Chính là \"đông\" tiếng Việt. Có hai chấm 冫 (băng) ở dưới — dấu hiệu của giá lạnh.","ex":"北方的冬天会下雪。","exPy":"Běifāng de dōngtiān huì xià xuě.","exVi":"Mùa đông miền Bắc có tuyết.","w":"北方 的 冬天 会 下 雪。"},{"zh":"季节","py":"jìjié","vi":"mùa","hv":"quý tiết","note":"季 = \"quý\" trong \"quý một, quý hai\". 节 = \"tiết\" trong \"tiết trời\", \"thời tiết\".","ex":"你最喜欢哪个季节？","exPy":"Nǐ zuì xǐhuan nǎge jìjié?","exVi":"Bạn thích mùa nào nhất?","w":"你 最 喜欢 哪个 季节？"},{"zh":"周末","py":"zhōumò","vi":"cuối tuần","hv":"chu mạt","note":"周 (tuần, vòng) + 末 (cuối). Tiếng Việt: \"chu kỳ\", \"mạt kỳ\" (cuối kỳ).","ex":"这个周末你有什么打算？","exPy":"Zhège zhōumò nǐ yǒu shénme dǎsuàn?","exVi":"Cuối tuần này bạn có dự định gì?","w":"这个 周末 你 有 什么 打算？"},{"zh":"节日","py":"jiérì","vi":"ngày lễ, ngày tết","hv":"tiết nhật","note":"节 (tiết) + 日 (ngày). Tết Nguyên Đán là 春节 (xuân tiết) — người Việt cũng gọi là \"Tết\", cùng chữ 节.","ex":"春节是最重要的节日。","exPy":"Chūnjié shì zuì zhòngyào de jiérì.","exVi":"Tết là ngày lễ quan trọng nhất.","w":"春 节 是 最 重要 的 节日。"},{"zh":"以前","py":"yǐqián","vi":"trước đây, trước khi","hv":"dĩ tiền","note":"以 = \"dĩ\" trong \"dĩ nhiên\", \"sở dĩ\". Trái nghĩa là 以后 (sau này).","ex":"我以前不喜欢喝茶，现在很喜欢。","exPy":"Wǒ yǐqián bù xǐhuan hē chá, xiànzài hěn xǐhuan.","exVi":"Trước đây tôi không thích uống trà, giờ thì rất thích.","w":"我 以前 不 喜欢 喝 茶， 现在 很 喜欢。"},{"zh":"过去","py":"guòqù","vi":"quá khứ; đi qua","hv":"quá khứ","note":"Chính là \"quá khứ\" tiếng Việt. Cũng là động từ: 过去看看 = đi qua đó xem.","ex":"过去的事情别再想了。","exPy":"Guòqù de shìqing bié zài xiǎng le.","exVi":"Chuyện đã qua đừng nghĩ nữa.","w":"过去 的 事情 别 再 想 了。"},{"zh":"后来","py":"hòulái","vi":"về sau, sau đó","hv":"hậu lai","note":"后 (sau) + 来 (đến). CHỈ dùng kể chuyện đã xảy ra trong quá khứ — không dùng cho tương lai.","ex":"后来我才知道他是老师。","exPy":"Hòulái wǒ cái zhīdào tā shì lǎoshī.","exVi":"Về sau tôi mới biết anh ấy là giáo viên.","w":"后来 我 才 知道 他 是 老师。"}],"newChars":["春","夏","秋","冬","季","末"],"outro":"很好！Xong bài 64."};
G.ROOMS["zh-l065"] = {"id":"zh-l065","lang":"zh","level":3,"no":65,"teacher":"wang","title":"HSK3 · Bài 65 · 时间副词 Thời gian và tần suất","intro":["你最近忙不忙？","Bài 65: Làm chủ nhóm phó từ khó nhất tiếng Trung — nói được \"vừa nãy, lát nữa, luôn luôn, cuối cùng\". Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ zuìjìn máng bu máng?","gram":{"t":"Thang tần suất — từ ít tới nhiều","b":"有时候 < 经常 < 总是 < 一直","d":"有时候 (thỉnh thoảng) → 经常 (thường xuyên) → 总是 (lúc nào cũng) → 一直 (liên tục không ngắt). Tất cả đều đứng SAU chủ ngữ, TRƯỚC động từ — giống quy tắc của 都 và 也.","ex":[["我经常喝咖啡。","Tôi thường uống cà phê.","Wǒ jīngcháng hē kāfēi."],["他总是很忙。","Anh ấy lúc nào cũng bận.","Tā zǒngshì hěn máng."],["他一直没回来。","Anh ấy vẫn chưa về.","Tā yìzhí méi huílai."]]},"grams":[{"t":"Thang tần suất — từ ít tới nhiều","b":"有时候 < 经常 < 总是 < 一直","d":"有时候 (thỉnh thoảng) → 经常 (thường xuyên) → 总是 (lúc nào cũng) → 一直 (liên tục không ngắt). Tất cả đều đứng SAU chủ ngữ, TRƯỚC động từ — giống quy tắc của 都 và 也.","ex":[["我经常喝咖啡。","Tôi thường uống cà phê.","Wǒ jīngcháng hē kāfēi."],["他总是很忙。","Anh ấy lúc nào cũng bận.","Tā zǒngshì hěn máng."],["他一直没回来。","Anh ấy vẫn chưa về.","Tā yìzhí méi huílai."]]},{"t":"最后 và 终于 — cùng dịch \"cuối cùng\" nhưng khác hẳn","b":"最后 = vị trí cuối trong dãy · 终于 = rốt cuộc cũng đạt được","d":"最后 là DANH TỪ chỉ thứ tự: 最后一个人 (người cuối cùng). 终于 là PHÓ TỪ mang cảm xúc nhẹ nhõm sau chờ đợi: 终于来了! (cuối cùng cũng đến rồi!). Người Việt hay dùng lẫn vì tiếng Việt dùng chung một cụm.","ex":[["最后我们去了公园。","Cuối cùng (sau chót) chúng tôi đi công viên.","Zuìhòu wǒmen qù le gōngyuán."],["等了一个小时，他终于来了。","Đợi một tiếng, cuối cùng anh ấy cũng tới.","Děng le yí ge xiǎoshí, tā zhōngyú lái le."]]},{"t":"刚才 và 一会儿 — nãy và lát nữa","b":"刚才 = vừa xong (đã qua) · 一会儿 = lát nữa (sắp tới)","d":"Hai từ đối xứng nhau qua hiện tại. Cả hai đều là danh từ thời gian nên đứng linh hoạt: 刚才我在开会 hoặc 我刚才在开会 đều đúng.","ex":[["刚才他给你打电话了。","Vừa nãy anh ấy gọi cho bạn.","Gāngcái tā gěi nǐ dǎ diànhuà le."],["一会儿我们去吃饭。","Lát nữa chúng ta đi ăn.","Yíhuìr wǒmen qù chīfàn."]]}],"items":[{"zh":"刚才","py":"gāngcái","vi":"vừa nãy, ban nãy","hv":"cương tài","note":"Chỉ khoảng thời gian RẤT GẦN vừa qua. Là DANH TỪ nên đứng được đầu câu: 刚才我在开会.","ex":"刚才我在开会，没接你电话。","exPy":"Gāngcái wǒ zài kāihuì, méi jiē nǐ diànhuà.","exVi":"Vừa nãy tôi đang họp, không nghe máy được.","w":"刚才 我 在 开会， 没 接 你 电话。"},{"zh":"马上","py":"mǎshàng","vi":"ngay lập tức","hv":"mã thượng","note":"Nghĩa đen: \"trên lưng ngựa\" — thời xưa cưỡi ngựa là nhanh nhất. Hình ảnh rất đẹp.","ex":"请等一会儿，我马上就好。","exPy":"Qǐng děng yíhuìr, wǒ mǎshàng jiù hǎo.","exVi":"Đợi một lát, tôi xong ngay đây.","w":"请 等 一会儿， 我 马上 就 好。"},{"zh":"一会儿","py":"yíhuìr","vi":"một lát, chốc nữa","hv":"nhất hội nhi","note":"Đọc uốn lưỡi kiểu Bắc Kinh. Đứng trước động từ nghĩa là \"lát nữa\", đứng sau nghĩa là \"trong chốc lát\".","ex":"一会儿见。","exPy":"Yíhuìr jiàn.","exVi":"Lát nữa gặp.","w":"一会儿 见。"},{"zh":"最近","py":"zuìjìn","vi":"dạo này, gần đây","hv":"tối cận","note":"最 (nhất, bài 22) + 近 (gần, bài 24) = \"gần nhất\". Câu hỏi thăm rất hay dùng: 最近怎么样？","ex":"你最近忙不忙？","exPy":"Nǐ zuìjìn máng bu máng?","exVi":"Dạo này bạn có bận không?","w":"你 最近 忙 不 忙？"},{"zh":"最后","py":"zuìhòu","vi":"cuối cùng, sau cùng","hv":"tối hậu","note":"Tiếng Việt: \"tối hậu thư\". Chỉ VỊ TRÍ cuối cùng trong một dãy, khác 终于 (xem ngữ pháp).","ex":"最后一个问题最难。","exPy":"Zuìhòu yí ge wèntí zuì nán.","exVi":"Câu hỏi cuối cùng khó nhất.","w":"最后 一 个 问题 最 难。"},{"zh":"终于","py":"zhōngyú","vi":"cuối cùng cũng, rốt cuộc","hv":"chung ư","note":"终 = \"chung\" trong \"thuỷ chung\", \"chung kết\". Mang cảm xúc NHẸ NHÕM sau chờ đợi lâu.","ex":"学了三年，我终于能看懂中文报纸了。","exPy":"Xué le sān nián, wǒ zhōngyú néng kàn dǒng Zhōngwén bàozhǐ le.","exVi":"Học ba năm, cuối cùng tôi cũng đọc hiểu được báo tiếng Trung.","w":"学 了 三 年， 我 终于 能 看 懂 中文 报纸 了。"},{"zh":"经常","py":"jīngcháng","vi":"thường xuyên","hv":"kinh thường","note":"常 = \"thường\" trong \"bình thường\", \"thường xuyên\". Tần suất cao nhưng không phải lúc nào cũng.","ex":"他经常在周末去爬山。","exPy":"Tā jīngcháng zài zhōumò qù páshān.","exVi":"Cuối tuần anh ấy thường đi leo núi.","w":"他 经常 在 周末 去 爬山。"},{"zh":"总是","py":"zǒngshì","vi":"luôn luôn, lúc nào cũng","hv":"tổng thị","note":"总 = \"tổng\" trong \"tổng cộng\". Mạnh hơn 经常 — nghĩa là KHÔNG có ngoại lệ, đôi khi mang ý than phiền.","ex":"我妹妹总是忘记带钥匙。","exPy":"Wǒ mèimei zǒngshì wàngjì dài yàoshi.","exVi":"Em gái tôi lúc nào cũng quên mang chìa khoá.","w":"我 妹妹 总是 忘记 带 钥匙。"},{"zh":"一直","py":"yìzhí","vi":"luôn, suốt; thẳng","hv":"nhất trực","note":"直 = \"trực\" (thẳng). Hai nghĩa: liên tục không ngắt quãng, và đi thẳng: 一直走 (đi thẳng).","ex":"从早上到现在我一直在工作。","exPy":"Cóng zǎoshang dào xiànzài wǒ yìzhí zài gōngzuò.","exVi":"Từ sáng đến giờ tôi làm việc liên tục.","w":"从 早上 到 现在 我 一直 在 工作。"},{"zh":"突然","py":"tūrán","vi":"đột nhiên, bỗng nhiên","hv":"đột nhiên","note":"Chính là \"đột nhiên\" tiếng Việt. 然 là đuôi hay gặp ở phó từ: 当然, 虽然, 忽然.","ex":"他突然站起来走了。","exPy":"Tā tūrán zhàn qǐlai zǒu le.","exVi":"Anh ấy bỗng nhiên đứng dậy đi mất.","w":"他 突然 站 起来 走 了。"}],"newChars":["才","终","总","直","突"],"outro":"很好！Xong bài 65."};
G.ROOMS["zh-l066"] = {"id":"zh-l066","lang":"zh","level":3,"no":66,"teacher":"wang","title":"HSK3 · Bài 66 · 爱好和上网 Sở thích và Internet","intro":["你有什么爱好？","Bài 66: Nói về sở thích, dùng máy tính và mạng — nhóm từ hiện đại nhưng vẫn đầy gốc Hán Việt. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ yǒu shénme àihào?","gram":{"t":"Ba cách nói về sở thích","b":"我喜欢… · 我的爱好是… · 我对…感兴趣","d":"Ba mẫu câu này bổ sung cho nhau. 喜欢 nhẹ nhất, 爱好 dùng khi kể sở thích như một danh sách, 对…感兴趣 trang trọng và trí tuệ hơn.","ex":[["我喜欢听音乐。","Tôi thích nghe nhạc.","Wǒ xǐhuan tīng yīnyuè."],["我的爱好是照相和爬山。","Sở thích của tôi là chụp ảnh và leo núi.","Wǒ de àihào shì zhàoxiàng hé páshān."],["我对中国文化很感兴趣。","Tôi rất hứng thú với văn hoá Trung Quốc.","Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù."]]},"grams":[{"t":"Ba cách nói về sở thích","b":"我喜欢… · 我的爱好是… · 我对…感兴趣","d":"Ba mẫu câu này bổ sung cho nhau. 喜欢 nhẹ nhất, 爱好 dùng khi kể sở thích như một danh sách, 对…感兴趣 trang trọng và trí tuệ hơn.","ex":[["我喜欢听音乐。","Tôi thích nghe nhạc.","Wǒ xǐhuan tīng yīnyuè."],["我的爱好是照相和爬山。","Sở thích của tôi là chụp ảnh và leo núi.","Wǒ de àihào shì zhàoxiàng hé páshān."],["我对中国文化很感兴趣。","Tôi rất hứng thú với văn hoá Trung Quốc.","Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù."]]},{"t":"Từ mới thời hiện đại vẫn ghép từ chữ cũ","b":"电脑 · 电视 · 电影 · 电话 · 电梯 · 电子邮件","d":"Tiếng Trung hầu như không mượn nguyên từ nước ngoài mà GHÉP chữ sẵn có. Nhờ vậy người biết chữ đoán được nghĩa từ mới. So sánh: người Việt phải học riêng \"email\", còn người Trung nhìn 电子邮件 là hiểu ngay.","ex":[["上网 = 上 + 网","lên + lưới = vào mạng","shàngwǎng"],["照相机 = 照相 + 机","chụp ảnh + máy = máy ảnh","zhàoxiàngjī"]]},{"t":"Động từ ly hợp lại xuất hiện","b":"聊天 · 上网 · 照相","d":"Ba từ này đều tách được: 聊了一个小时天, 上了两个小时网, 照了很多相. Đến đây bạn đã gặp cả chục động từ ly hợp — hãy để ý mỗi khi muốn thêm thời lượng hay số lần vào giữa.","ex":[["我们聊了两个小时天。","Chúng tôi nói chuyện hai tiếng.","Wǒmen liáo le liǎng ge xiǎoshí tiān."],["他每天上三个小时网。","Ngày nào cậu ấy cũng lên mạng ba tiếng.","Tā měi tiān shàng sān ge xiǎoshí wǎng."]]}],"items":[{"zh":"爱好","py":"àihào","vi":"sở thích","hv":"ái hảo","note":"爱 (yêu) + 好 (thích). Chú ý 好 ở đây đọc hào (thanh 4), không phải hǎo.","ex":"你有什么爱好？","exPy":"Nǐ yǒu shénme àihào?","exVi":"Bạn có sở thích gì?","w":"你 有 什么 爱好？"},{"zh":"感兴趣","py":"gǎn xìngqù","vi":"hứng thú, quan tâm","hv":"cảm hứng thú","note":"兴趣 chính là \"hứng thú\" tiếng Việt. Luôn dùng với 对: 对…感兴趣 (bài 38).","ex":"他对音乐特别感兴趣。","exPy":"Tā duì yīnyuè tèbié gǎn xìngqù.","exVi":"Cậu ấy đặc biệt hứng thú với âm nhạc.","w":"他 对 音乐 特别 感兴趣。"},{"zh":"游戏","py":"yóuxì","vi":"trò chơi, game","hv":"du hí","note":"游 (chơi, đi rong — bộ 氵) + 戏 (trò diễn). Tiếng Việt: \"du hí\", \"du lịch\", \"hí kịch\".","ex":"弟弟每天玩两个小时游戏。","exPy":"Dìdi měi tiān wán liǎng ge xiǎoshí yóuxì.","exVi":"Em trai tôi ngày nào cũng chơi game hai tiếng.","w":"弟弟 每 天 玩 两 个 小时 游戏。"},{"zh":"节目","py":"jiémù","vi":"chương trình, tiết mục","hv":"tiết mục","note":"Chính là \"tiết mục\" tiếng Việt: 节 (tiết) + 目 (mục). Chương trình tivi cũng gọi là 节目.","ex":"晚上我喜欢看新闻节目。","exPy":"Wǎnshang wǒ xǐhuan kàn xīnwén jiémù.","exVi":"Buổi tối tôi thích xem chương trình thời sự.","w":"晚上 我 喜欢 看 新闻 节目。"},{"zh":"新闻","py":"xīnwén","vi":"tin tức, thời sự","hv":"tân văn","note":"新 (mới) + 闻 (nghe được). CẨN THẬN: 新闻 là TIN TỨC, còn \"tân văn\" tiếng Việt nghĩa khác. Báo là 报纸 (bài 30).","ex":"我每天看新闻。","exPy":"Wǒ měi tiān kàn xīnwén.","exVi":"Ngày nào tôi cũng xem thời sự.","w":"我 每 天 看 新闻。"},{"zh":"照片","py":"zhàopiàn","vi":"bức ảnh","hv":"chiếu phiến","note":"照 (chiếu, rọi) + 片 (tấm mỏng). Lượng từ là 张 (vật phẳng, bài 43): 一张照片.","ex":"这些照片是去年在北京照的。","exPy":"Zhèxiē zhàopiàn shì qùnián zài Běijīng zhào de.","exVi":"Mấy tấm ảnh này chụp ở Bắc Kinh năm ngoái.","w":"这些 照片 是 去年 在 北京 照 的。"},{"zh":"照相机","py":"zhàoxiàngjī","vi":"máy ảnh","hv":"chiếu tướng cơ","note":"照相 (chụp ảnh) + 机 (máy). Chụp ảnh là 照相 hoặc 拍照.","ex":"旅游的时候我总是带着照相机。","exPy":"Lǚyóu de shíhou wǒ zǒngshì dài zhe zhàoxiàngjī.","exVi":"Khi đi du lịch tôi luôn mang theo máy ảnh.","w":"旅游 的 时候 我 总是 带 着 照相机。"},{"zh":"上网","py":"shàngwǎng","vi":"lên mạng, vào Internet","hv":"thượng võng","note":"上 (lên) + 网 (lưới, mạng). 网 vốn là hình cái lưới đánh cá — Internet đúng là một cái lưới.","ex":"我上网跟中国朋友聊天。","exPy":"Wǒ shàngwǎng gēn Zhōngguó péngyou liáotiān.","exVi":"Tôi lên mạng nói chuyện với bạn Trung Quốc.","w":"我 上网 跟 中国 朋友 聊天。"},{"zh":"聊天","py":"liáotiān","vi":"tán gẫu, trò chuyện","hv":"liêu thiên","note":"聊 có bộ 耳 (tai) — chuyện trò là nghe nhau nói. Là động từ ly hợp: 聊了一个小时天.","ex":"我们聊了很久。","exPy":"Wǒmen liáo le hěn jiǔ.","exVi":"Chúng tôi nói chuyện rất lâu.","w":"我们 聊 了 很 久。"},{"zh":"电子邮件","py":"diànzǐ yóujiàn","vi":"thư điện tử, email","hv":"điện tử bưu kiện","note":"电子 chính là \"điện tử\", 邮件 là \"bưu kiện\". Ghép lại đúng nghĩa \"thư điện tử\". Nói tắt là 邮件.","ex":"请把资料发到我的电子邮件。","exPy":"Qǐng bǎ zīliào fā dào wǒ de diànzǐ yóujiàn.","exVi":"Xin gửi tài liệu vào email của tôi.","w":"请 把 资料 发 到 我 的 电子邮件。"}],"newChars":["戏","闻","片","聊","邮"],"outro":"很好！Xong bài 66."};
G.ROOMS["zh-l067"] = {"id":"zh-l067","lang":"zh","level":3,"no":67,"teacher":"wang","title":"HSK3 · Bài 67 · 运动和比赛 Thể thao và sự kiện","intro":["医生说要多锻炼身体。","Bài 67: Nói về rèn luyện, thi đấu, gặp gỡ — và phân biệt cặp 出现 / 发现, 见面 / 遇到. Bấm 1 · Học để bắt đầu."],"introPy":"Yīshēng shuō yào duō duànliàn shēntǐ.","gram":{"t":"出现 và 发现 — vật hiện ra hay người tìm ra?","b":"出现 = tự hiện ra · 发现 = ai đó nhận ra","d":"问题出现了 (vấn đề nảy sinh — tự nó). 我发现了问题 (tôi phát hiện ra vấn đề — có chủ thể). Tiếng Việt cũng phân biệt \"xuất hiện\" với \"phát hiện\" y hệt, nên người Việt nắm rất nhanh.","ex":[["天上出现了一道彩虹。","Trên trời xuất hiện một cầu vồng.","Tiān shàng chūxiàn le yí dào cǎihóng."],["我发现他没来。","Tôi nhận ra anh ấy không đến.","Wǒ fāxiàn tā méi lái."]]},"grams":[{"t":"出现 và 发现 — vật hiện ra hay người tìm ra?","b":"出现 = tự hiện ra · 发现 = ai đó nhận ra","d":"问题出现了 (vấn đề nảy sinh — tự nó). 我发现了问题 (tôi phát hiện ra vấn đề — có chủ thể). Tiếng Việt cũng phân biệt \"xuất hiện\" với \"phát hiện\" y hệt, nên người Việt nắm rất nhanh.","ex":[["天上出现了一道彩虹。","Trên trời xuất hiện một cầu vồng.","Tiān shàng chūxiàn le yí dào cǎihóng."],["我发现他没来。","Tôi nhận ra anh ấy không đến.","Wǒ fāxiàn tā méi lái."]]},{"t":"见面 và 遇到 — hẹn gặp hay tình cờ gặp?","b":"见面 = gặp có hẹn · 遇到 = gặp tình cờ","d":"见面 là động từ ly hợp nên phải nói 跟他见面 hoặc 我们见面. Còn 遇到 nhận tân ngữ trực tiếp: 遇到他. Đây là lỗi ngữ pháp rất hay gặp ở trình độ HSK 3.","ex":[["我明天跟他见面。","Mai tôi gặp anh ấy. (có hẹn)","Wǒ míngtiān gēn tā jiànmiàn."],["我在超市遇到了他。","Tôi tình cờ gặp anh ấy ở siêu thị.","Wǒ zài chāoshì yùdào le tā."]]},{"t":"Lượng từ 场 cho sự kiện","b":"一场比赛 · 一场电影 · 一场雨","d":"场 chǎng dùng cho những việc diễn ra trong một khoảng thời gian và không gian: trận đấu, buổi chiếu phim, cơn mưa. Tiếng Việt cũng nói \"một trận mưa\", \"một trận đấu\".","ex":[["昨天下了一场大雨。","Hôm qua có một trận mưa to.","Zuótiān xià le yì chǎng dàyǔ."],["我们去看一场比赛吧。","Chúng ta đi xem một trận đấu đi.","Wǒmen qù kàn yì chǎng bǐsài ba."]]}],"items":[{"zh":"锻炼","py":"duànliàn","vi":"rèn luyện, tập thể dục","hv":"đoàn luyện","note":"Cả hai chữ đều có bộ 钅 (kim loại) — vốn nghĩa là rèn sắt, sau chuyển sang rèn luyện thân thể. Tiếng Việt: \"tôi luyện\", \"rèn luyện\".","ex":"医生说要多锻炼身体。","exPy":"Yīshēng shuō yào duō duànliàn shēntǐ.","exVi":"Bác sĩ nói phải tập thể dục nhiều.","w":"医生 说 要 多 锻炼 身体。"},{"zh":"爬山","py":"páshān","vi":"leo núi","hv":"ba sơn","note":"爬 (bò, trèo) + 山 (núi). Là động từ ly hợp: 爬了三个小时山.","ex":"这个周末我们去爬山，怎么样？","exPy":"Zhège zhōumò wǒmen qù páshān, zěnmeyàng?","exVi":"Cuối tuần này đi leo núi nhé?","w":"这个 周末 我们 去 爬山， 怎么样？"},{"zh":"体育","py":"tǐyù","vi":"thể dục, thể thao","hv":"thể dục","note":"Chính là \"thể dục\" tiếng Việt: 体 (thể) + 育 (dục, nuôi dạy). Sân vận động là 体育场.","ex":"他从小就喜欢体育。","exPy":"Tā cóngxiǎo jiù xǐhuan tǐyù.","exVi":"Cậu ấy thích thể thao từ nhỏ.","w":"他 从小 就 喜欢 体育。"},{"zh":"比赛","py":"bǐsài","vi":"cuộc thi, trận đấu; thi đấu","hv":"tỷ tái","note":"比 (so sánh, bài 28) + 赛 (đua). Nghĩa gốc: so tài với nhau.","ex":"明天有一场很重要的比赛。","exPy":"Míngtiān yǒu yì chǎng hěn zhòngyào de bǐsài.","exVi":"Mai có một trận đấu rất quan trọng.","w":"明天 有 一 场 很 重要 的 比赛。"},{"zh":"参加","py":"cānjiā","vi":"tham gia, dự","hv":"tham gia","note":"Chính là \"tham gia\" tiếng Việt. Dùng cho hoạt động có tổ chức: 参加会议, 参加比赛, 参加考试.","ex":"一共有二十个人参加。","exPy":"Yígòng yǒu èrshí ge rén cānjiā.","exVi":"Tất cả có hai mươi người tham gia.","w":"一共 有 二 十 个人 参加。"},{"zh":"结束","py":"jiéshù","vi":"kết thúc","hv":"kết thúc","note":"Chính là \"kết thúc\" tiếng Việt. Trái nghĩa hoàn toàn với 开始 (bài 27).","ex":"比赛什么时候结束？","exPy":"Bǐsài shénme shíhou jiéshù?","exVi":"Khi nào trận đấu kết thúc?","w":"比赛 什么 时候 结束？"},{"zh":"出现","py":"chūxiàn","vi":"xuất hiện","hv":"xuất hiện","note":"Chính là \"xuất hiện\" tiếng Việt: 出 (ra) + 现 (hiện). Thứ gì đó TỰ hiện ra.","ex":"刚才路上出现了一个问题。","exPy":"Gāngcái lù shàng chūxiàn le yí ge wèntí.","exVi":"Vừa nãy trên đường xảy ra một sự cố.","w":"刚才 路上 出现 了 一 个 问题。"},{"zh":"发现","py":"fāxiàn","vi":"phát hiện, nhận ra","hv":"phát hiện","note":"Chính là \"phát hiện\" tiếng Việt. Khác 出现: 发现 là NGƯỜI tìm ra, 出现 là VẬT tự hiện ra.","ex":"我发现这个办法很有用。","exPy":"Wǒ fāxiàn zhège bànfǎ hěn yǒuyòng.","exVi":"Tôi phát hiện cách này rất hữu ích.","w":"我 发现 这个 办法 很 有用。"},{"zh":"遇到","py":"yùdào","vi":"gặp phải, tình cờ gặp","hv":"ngộ đáo","note":"遇 có bộ 辶 (đi đường) — gặp trên đường. Tiếng Việt: \"ngộ\" trong \"tao ngộ\", \"kỳ ngộ\".","ex":"我昨天在公园遇到了一个老朋友。","exPy":"Wǒ zuótiān zài gōngyuán yùdào le yí ge lǎo péngyou.","exVi":"Hôm qua tôi gặp một người bạn cũ ở công viên.","w":"我 昨天 在 公园 遇到 了 一 个 老 朋友。"},{"zh":"见面","py":"jiànmiàn","vi":"gặp mặt","hv":"kiến diện","note":"见 (thấy) + 面 (mặt). Là động từ ly hợp — gặp AI thì phải dùng 跟…见面, KHÔNG nói 见面他.","ex":"我们下个星期见面吧。","exPy":"Wǒmen xià ge xīngqī jiànmiàn ba.","exVi":"Tuần sau chúng ta gặp nhau nhé.","w":"我们 下 个 星期 见面 吧。"}],"newChars":["锻","炼","爬","山","育","赛","参","加","束","遇"],"outro":"很好！Xong bài 67."};
G.ROOMS["zh-l068"] = {"id":"zh-l068","lang":"zh","level":3,"no":68,"teacher":"wang","title":"HSK3 · Bài 68 · 生活习惯 Thói quen và quan hệ","intro":["我每天早上刷牙、洗脸、吃早饭。","Bài 68: Kể thói quen hằng ngày, xin nghỉ phép, và nói về quan hệ giữa người với người. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ měi tiān zǎoshang shuāyá, xǐliǎn, chī zǎofàn.","gram":{"t":"习惯 vừa là danh từ vừa là động từ","b":"有…的习惯 (danh từ) · 习惯了 (động từ)","d":"Nói về thói quen thì dùng như danh từ: 我有早起的习惯. Nói đã quen với hoàn cảnh thì dùng như động từ: 我已经习惯了这里的天气.","ex":[["他有早睡早起的习惯。","Anh ấy có thói quen ngủ sớm dậy sớm.","Tā yǒu zǎo shuì zǎo qǐ de xíguàn."],["我还不习惯这里的生活。","Tôi vẫn chưa quen với cuộc sống ở đây.","Wǒ hái bù xíguàn zhèlǐ de shēnghuó."]]},"grams":[{"t":"习惯 vừa là danh từ vừa là động từ","b":"有…的习惯 (danh từ) · 习惯了 (động từ)","d":"Nói về thói quen thì dùng như danh từ: 我有早起的习惯. Nói đã quen với hoàn cảnh thì dùng như động từ: 我已经习惯了这里的天气.","ex":[["他有早睡早起的习惯。","Anh ấy có thói quen ngủ sớm dậy sớm.","Tā yǒu zǎo shuì zǎo qǐ de xíguàn."],["我还不习惯这里的生活。","Tôi vẫn chưa quen với cuộc sống ở đây.","Wǒ hái bù xíguàn zhèlǐ de shēnghuó."]]},{"t":"Động từ ly hợp: chèn số lượng vào giữa","b":"请一天假 · 洗个澡 · 睡个好觉","d":"请假, 洗澡, 睡觉, 聊天, 帮忙, 见面 đều là động từ ly hợp. Muốn thêm số lượng hay lượng từ, phải chèn vào GIỮA. Nói 请假一天 nghe sai; đúng là 请一天假.","ex":[["我想请三天假。","Tôi muốn xin nghỉ ba ngày.","Wǒ xiǎng qǐng sān tiān jià."],["回家先洗个澡吧。","Về nhà tắm cái đã.","Huí jiā xiān xǐ ge zǎo ba."]]},{"t":"Sáu từ Hán Việt trùng khít trong một bài","b":"习惯 · 照顾 · 关心 · 关系 · 热情 · 欢迎","d":"Tập quán, chiếu cố, quan tâm, quan hệ, nhiệt tình, hoan nghênh — sáu từ này bạn đã dùng bằng tiếng Việt cả đời. Với người học tiếng Anh, đây là sáu từ phải học thuộc lòng; với bạn, chỉ cần nhớ mặt chữ và cách đọc.","ex":[["谢谢你的关心和照顾。","Cảm ơn sự quan tâm và chăm sóc của bạn.","Xièxie nǐ de guānxīn hé zhàogù."],["欢迎光临！","Hoan nghênh quý khách!","Huānyíng guānglín!"]]}],"items":[{"zh":"刷牙","py":"shuāyá","vi":"đánh răng","hv":"loát nha","note":"刷 (chải, có bộ 刂) + 牙 (răng). Tiếng Việt: \"nha khoa\", \"nha sĩ\" — cùng chữ 牙.","ex":"我每天早上刷牙、洗脸、吃早饭。","exPy":"Wǒ měi tiān zǎoshang shuāyá, xǐliǎn, chī zǎofàn.","exVi":"Sáng nào tôi cũng đánh răng, rửa mặt, ăn sáng.","w":"我 每 天 早上 刷牙、 洗 脸、 吃 早饭。"},{"zh":"洗澡","py":"xǐzǎo","vi":"tắm","hv":"tẩy tảo","note":"Cả hai chữ đều có bộ 氵 (nước). 洗 là \"tẩy\" đã học ở bài 21. Là động từ ly hợp.","ex":"我想先洗个澡。","exPy":"Wǒ xiǎng xiān xǐ ge zǎo.","exVi":"Tôi muốn tắm cái đã.","w":"我 想 先 洗 个 澡。"},{"zh":"习惯","py":"xíguàn","vi":"thói quen; quen với","hv":"tập quán","note":"Chính là \"tập quán\" tiếng Việt. Vừa là danh từ (thói quen) vừa là động từ (quen với): 我习惯了.","ex":"早睡早起是个好习惯。","exPy":"Zǎo shuì zǎo qǐ shì ge hǎo xíguàn.","exVi":"Ngủ sớm dậy sớm là thói quen tốt.","w":"早 睡 早 起 是 个 好 习惯。"},{"zh":"迟到","py":"chídào","vi":"đến muộn","hv":"trì đáo","note":"迟 (chậm trễ, bộ 辶) + 到 (đến). Tiếng Việt: \"trì hoãn\", \"trì trệ\".","ex":"路上堵车，所以我迟到了。","exPy":"Lù shàng dǔchē, suǒyǐ wǒ chídào le.","exVi":"Đường tắc nên tôi đến muộn.","w":"路上 堵车， 所以 我 迟到 了。"},{"zh":"请假","py":"qǐngjià","vi":"xin nghỉ phép","hv":"thỉnh giả","note":"请 (xin, bài 2) + 假 (nghỉ). Chú ý 假 ở đây đọc jià (thanh 4). Là động từ ly hợp: 请一天假.","ex":"我明天要请假去医院。","exPy":"Wǒ míngtiān yào qǐngjià qù yīyuàn.","exVi":"Mai tôi phải xin nghỉ để đi bệnh viện.","w":"我 明天 要 请假 去 医院。"},{"zh":"照顾","py":"zhàogù","vi":"chăm sóc","hv":"chiếu cố","note":"Chính là \"chiếu cố\" tiếng Việt, nhưng nghĩa tiếng Trung là CHĂM SÓC thật sự, không mang sắc thái ban ơn.","ex":"谢谢您这几天的照顾。","exPy":"Xièxie nín zhè jǐ tiān de zhàogù.","exVi":"Cảm ơn bác đã chăm sóc mấy hôm nay.","w":"谢谢 您 这 几 天 的 照顾。"},{"zh":"关心","py":"guānxīn","vi":"quan tâm","hv":"quan tâm","note":"Chính là \"quan tâm\" tiếng Việt: 关 (liên quan) + 心 (lòng). Lại một thành viên gia đình chữ 心.","ex":"他很关心自己的邻居。","exPy":"Tā hěn guānxīn zìjǐ de línjū.","exVi":"Anh ấy rất quan tâm hàng xóm của mình.","w":"他 很 关心 自己 的 邻居。"},{"zh":"关系","py":"guānxi","vi":"quan hệ, mối liên hệ","hv":"quan hệ","note":"Chính là \"quan hệ\" tiếng Việt. Đã gặp trong 没关系 (bài 15) — nghĩa đen: \"không có liên quan gì\".","ex":"我跟同事的关系一直很好。","exPy":"Wǒ gēn tóngshì de guānxi yìzhí hěn hǎo.","exVi":"Quan hệ giữa tôi với đồng nghiệp luôn rất tốt.","w":"我 跟 同事 的 关系 一直 很 好。"},{"zh":"热情","py":"rèqíng","vi":"nhiệt tình, nồng hậu","hv":"nhiệt tình","note":"Chính là \"nhiệt tình\" tiếng Việt: 热 (nóng, bài 15) + 情 (tình, có bộ 忄).","ex":"越南人对客人非常热情。","exPy":"Yuènán rén duì kèrén fēicháng rèqíng.","exVi":"Người Việt Nam rất nhiệt tình với khách.","w":"越 南 人 对 客人 非常 热情。"},{"zh":"欢迎","py":"huānyíng","vi":"hoan nghênh, chào đón","hv":"hoan nghênh","note":"Chính là \"hoan nghênh\" tiếng Việt: 欢 (vui) + 迎 (đón, bộ 辶). Biển hiệu khắp Trung Quốc ghi 欢迎光临.","ex":"欢迎大家来中国旅游！","exPy":"Huānyíng dàjiā lái Zhōngguó lǚyóu!","exVi":"Hoan nghênh mọi người đến Trung Quốc du lịch!","w":"欢迎 大家 来 中国 旅游！"}],"newChars":["刷","牙","澡","惯","迟","顾","迎"],"outro":"很好！Xong bài 68."};
G.ROOMS["zh-l069"] = {"id":"zh-l069","lang":"zh","level":3,"no":69,"teacher":"wang","title":"HSK3 · Bài 69 · 怎么形容 Miêu tả tính chất","intro":["我想买一件蓝色的衬衫。","Bài 69: Mở rộng vốn tính từ để tả người và vật — kèm hai cái bẫy Hán Việt cần nhớ. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ xiǎng mǎi yí jiàn lánsè de chènshān.","gram":{"t":"矮 và 低 — hai kiểu \"thấp\"","b":"矮 = người, vật thấp · 低 = mức độ thấp","d":"他很矮 (anh ấy thấp — chiều cao cơ thể). 价格很低 (giá thấp), 声音很低 (tiếng nhỏ), 温度很低 (nhiệt độ thấp). Nói 他很低 là sai hoàn toàn.","ex":[["这张桌子有点儿矮。","Cái bàn này hơi thấp.","Zhè zhāng zhuōzi yǒudiǎnr ǎi."],["这里的房价比较低。","Giá nhà ở đây khá thấp.","Zhèlǐ de fángjià bǐjiào dī."]]},"grams":[{"t":"矮 và 低 — hai kiểu \"thấp\"","b":"矮 = người, vật thấp · 低 = mức độ thấp","d":"他很矮 (anh ấy thấp — chiều cao cơ thể). 价格很低 (giá thấp), 声音很低 (tiếng nhỏ), 温度很低 (nhiệt độ thấp). Nói 他很低 là sai hoàn toàn.","ex":[["这张桌子有点儿矮。","Cái bàn này hơi thấp.","Zhè zhāng zhuōzi yǒudiǎnr ǎi."],["这里的房价比较低。","Giá nhà ở đây khá thấp.","Zhèlǐ de fángjià bǐjiào dī."]]},{"t":"可 + động từ = đáng để…","b":"可爱 · 可怕 · 可惜 · 可以","d":"可 nghĩa là \"có thể, đáng\". Ghép với động từ ra tính từ: 可爱 (đáng yêu), 可怕 (đáng sợ), 可惜 (đáng tiếc). Tiếng Việt cũng có \"khả ái\", \"khả kính\", \"khả nghi\" — cùng một lối ghép.","ex":[["这只小狗很可爱。","Con chó nhỏ này rất đáng yêu.","Zhè zhī xiǎo gǒu hěn kě'ài."],["太可惜了！","Đáng tiếc quá!","Tài kěxī le!"]]},{"t":"Ba mức nhấn mạnh: 很 < 非常 ≈ 特别 < 太…了","b":"很好 < 非常好 / 特别好 < 太好了","d":"很 chỉ là từ đệm (bài 1). 非常 và 特别 đều nghĩa \"rất\", dùng thay nhau được. 太…了 mạnh nhất và mang cảm thán. Nắm được thang này là câu văn của bạn có sắc thái ngay.","ex":[["这个菜很好吃。","Món này ngon.","Zhège cài hěn hǎochī."],["这个菜特别好吃。","Món này ngon đặc biệt.","Zhège cài tèbié hǎochī."],["太好吃了！","Ngon quá đi!","Tài hǎochī le!"]]}],"items":[{"zh":"蓝","py":"lán","vi":"màu xanh lam","hv":"lam","note":"Chính là \"lam\" tiếng Việt (\"màu lam\", \"lam ngọc\"). Bộ 艹 ở trên vì màu chàm nhuộm từ cây.","ex":"我想买一件蓝色的衬衫。","exPy":"Wǒ xiǎng mǎi yí jiàn lánsè de chènshān.","exVi":"Tôi muốn mua một chiếc sơ mi màu xanh lam.","w":"我 想 买 一 件 蓝 色 的 衬衫。"},{"zh":"绿","py":"lǜ","vi":"màu xanh lá","hv":"lục","note":"Chính là \"lục\" tiếng Việt (\"lục bình\", \"diệp lục\"). Bộ 纟 (sợi tơ) — màu nhuộm vải.","ex":"公园里的草是绿色的。","exPy":"Gōngyuán lǐ de cǎo shì lǜsè de.","exVi":"Cỏ trong công viên màu xanh lục.","w":"公园 里 的 草 是 绿色 的。"},{"zh":"短","py":"duǎn","vi":"ngắn","hv":"đoản","note":"Tiếng Việt: \"đoản mệnh\", \"đoản khúc\". Trái nghĩa với 长 cháng (dài, bài 28).","ex":"夏天的裤子比较短。","exPy":"Xiàtiān de kùzi bǐjiào duǎn.","exVi":"Quần mùa hè khá ngắn.","w":"夏天 的 裤子 比较 短。"},{"zh":"低","py":"dī","vi":"thấp (độ cao, giá, âm lượng)","hv":"đê","note":"Khác 矮 (bài 33): 矮 dùng cho NGƯỜI và vật thấp, còn 低 dùng cho mức độ — giá thấp, nhiệt độ thấp, tiếng nhỏ.","ex":"这里冬天的温度很低。","exPy":"Zhèlǐ dōngtiān de wēndù hěn dī.","exVi":"Nhiệt độ mùa đông ở đây rất thấp.","w":"这里 冬天 的 温度 很 低。"},{"zh":"旧","py":"jiù","vi":"cũ","hv":"cựu","note":"Chính là \"cựu\" tiếng Việt (\"cựu học sinh\", \"cựu chiến binh\"). Trái nghĩa với 新 (mới, bài 21).","ex":"这本旧词典是爷爷的。","exPy":"Zhè běn jiù cídiǎn shì yéye de.","exVi":"Quyển từ điển cũ này là của ông nội.","w":"这 本 旧 词典 是 爷爷 的。"},{"zh":"奇怪","py":"qíguài","vi":"kỳ lạ, kỳ quặc","hv":"kỳ quái","note":"Chính là \"kỳ quái\" tiếng Việt: 奇 (kỳ lạ) + 怪 (quái, có bộ 忄).","ex":"真奇怪，我的手机不见了。","exPy":"Zhēn qíguài, wǒ de shǒujī bú jiàn le.","exVi":"Lạ thật, điện thoại tôi biến mất rồi.","w":"真 奇怪， 我 的 手机 不见 了。"},{"zh":"可爱","py":"kě'ài","vi":"đáng yêu","hv":"khả ái","note":"Chính là \"khả ái\" tiếng Việt: 可 (có thể) + 爱 (yêu) — đáng để yêu. Cùng cách ghép: 可怕 (đáng sợ), 可以.","ex":"熊猫又可爱又聪明。","exPy":"Xióngmāo yòu kě'ài yòu cōngming.","exVi":"Gấu trúc vừa đáng yêu vừa thông minh.","w":"熊猫 又 可爱 又 聪明。"},{"zh":"聪明","py":"cōngming","vi":"thông minh","hv":"thông minh","note":"Chính là \"thông minh\" tiếng Việt: 聪 có bộ 耳 (tai — nghe tinh) + 明 (sáng — mắt tỏ). Tai thính mắt tinh thì thông minh.","ex":"他很聪明。","exPy":"Tā hěn cōngming.","exVi":"Cậu ấy rất thông minh.","w":"他 很 聪明。"},{"zh":"特别","py":"tèbié","vi":"đặc biệt; rất","hv":"đặc biệt","note":"Chính là \"đặc biệt\" tiếng Việt. Cũng dùng như phó từ mạnh: 特别好 = rất tốt, tương đương 非常.","ex":"他今天特别高兴。","exPy":"Tā jīntiān tèbié gāoxìng.","exVi":"Hôm nay cậu ấy đặc biệt vui.","w":"他 今天 特别 高兴。"},{"zh":"方便","py":"fāngbiàn","vi":"tiện lợi, thuận tiện","hv":"phương tiện","note":"CẨN THẬN — bẫy Hán Việt: âm là \"phương tiện\" nhưng nghĩa tiếng Trung là TIỆN LỢI, không phải \"công cụ đi lại\". Chú ý 便 ở đây đọc biàn, khác 便宜 piányi (bài 22).","ex":"住在学校附近很方便。","exPy":"Zhù zài xuéxiào fùjìn hěn fāngbiàn.","exVi":"Ở gần trường rất tiện.","w":"住 在 学校 附近 很 方便。"}],"newChars":["蓝","绿","短","旧","奇","怪","聪"],"outro":"很好！Xong bài 69."};
G.ROOMS["zh-l070"] = {"id":"zh-l070","lang":"zh","level":3,"no":70,"teacher":"wang","title":"HSK3 · Bài 70 · 东南西北 Phương hướng và vị trí","intro":["太阳从东边升起，从西边落下。","Bài 70: Nói bốn phương, chỉ chỗ ngồi, đo khoảng cách — và học thứ tự phương hướng kiểu Trung Quốc. Bấm 1 · Học để bắt đầu."],"introPy":"Tàiyáng cóng dōngbiān shēngqǐ, cóng xībiān luòxià.","gram":{"t":"Thứ tự phương hướng khác tiếng Việt","b":"东南西北 (đông-nam-tây-bắc)","d":"Người Việt đọc \"đông tây nam bắc\", người Trung Quốc đọc 东南西北 (đông-nam-tây-bắc) theo chiều kim đồng hồ. Ghép hướng: 东南 (đông nam), 西北 (tây bắc) — giống tiếng Việt.","ex":[["东南西北","đông - nam - tây - bắc","dōng nán xī běi"],["越南在中国的东南边。","Việt Nam ở phía đông nam Trung Quốc.","Yuènán zài Zhōngguó de dōngnán biān."]]},"grams":[{"t":"Thứ tự phương hướng khác tiếng Việt","b":"东南西北 (đông-nam-tây-bắc)","d":"Người Việt đọc \"đông tây nam bắc\", người Trung Quốc đọc 东南西北 (đông-nam-tây-bắc) theo chiều kim đồng hồ. Ghép hướng: 东南 (đông nam), 西北 (tây bắc) — giống tiếng Việt.","ex":[["东南西北","đông - nam - tây - bắc","dōng nán xī běi"],["越南在中国的东南边。","Việt Nam ở phía đông nam Trung Quốc.","Yuènán zài Zhōngguó de dōngnán biān."]]},{"t":"Thêm 边 hoặc 面 để thành từ chỉ vị trí","b":"东边 · 南面 · 上边 · 里面","d":"Một chữ hướng đứng riêng nghe cụt. Thêm 边 (bên) hoặc 面 (mặt) là thành danh từ vị trí hoàn chỉnh. Hai đuôi này dùng thay nhau được.","ex":[["银行在学校的东边。","Ngân hàng ở phía đông trường học.","Yínháng zài xuéxiào de dōngbiān."],["他站在我前面。","Anh ấy đứng phía trước tôi.","Tā zhàn zài wǒ qiánmiàn."]]},{"t":"Nói chiều cao và khoảng cách","b":"一米八 · 三百米 · 两公里","d":"Chiều cao người: 一米七五 (1m75), đọc thẳng các con số. Khoảng cách dùng 米 (mét) và 公里 (ki-lô-mét). Chú ý số đứng TRƯỚC đơn vị, giống tiếng Việt.","ex":[["他一米七五。","Anh ấy cao 1m75.","Tā yì mǐ qī wǔ."],["从这儿到那儿大概五百米。","Từ đây tới đó khoảng năm trăm mét.","Cóng zhèr dào nàr dàgài wǔbǎi mǐ."]]}],"items":[{"zh":"东","py":"dōng","vi":"phía đông","hv":"đông","note":"Chính là \"đông\" tiếng Việt (\"phương đông\", \"Đông Nam Á\"). Đã gặp trong 东西 (đồ vật, bài 10).","ex":"太阳从东边升起，从西边落下。","exPy":"Tàiyáng cóng dōngbiān shēngqǐ, cóng xībiān luòxià.","exVi":"Mặt trời mọc đằng đông, lặn đằng tây.","w":"太阳 从 东 边 升 起， 从 西 边 落 下。"},{"zh":"南","py":"nán","vi":"phía nam","hv":"nam","note":"Chính là \"nam\" tiếng Việt (\"miền Nam\", \"Việt Nam\" — nghĩa đen là \"nước Việt phương Nam\").","ex":"越南在中国的南边。","exPy":"Yuènán zài Zhōngguó de nánbiān.","exVi":"Việt Nam ở phía nam Trung Quốc.","w":"越 南 在 中国 的 南 边。"},{"zh":"西","py":"xī","vi":"phía tây","hv":"tây","note":"Chính là \"tây\" tiếng Việt (\"phương Tây\", \"Tây Ban Nha\"). Hình cái tổ chim — chim về tổ lúc mặt trời lặn ở phía tây.","ex":"他住在城市西边。","exPy":"Tā zhù zài chéngshì xībiān.","exVi":"Anh ấy sống ở phía tây thành phố.","w":"他 住 在 城市 西 边。"},{"zh":"北方","py":"běifāng","vi":"miền Bắc, phương Bắc","hv":"bắc phương","note":"北 (bắc, đã gặp trong 北京) + 方 (phương). Trái nghĩa là 南方 (miền Nam).","ex":"北方人喜欢吃面，南方人喜欢吃米饭。","exPy":"Běifāng rén xǐhuan chī miàn, nánfāng rén xǐhuan chī mǐfàn.","exVi":"Người miền Bắc thích ăn mì, người miền Nam thích ăn cơm.","w":"北方 人 喜欢 吃 面， 南方 人 喜欢 吃 米饭。"},{"zh":"向","py":"xiàng","vi":"về phía, hướng về","hv":"hướng","note":"Chính là \"hướng\" tiếng Việt. Gần nghĩa với 往 (bài 24) nhưng 向 dùng được cả với người: 向他学习.","ex":"到了路口向右转。","exPy":"Dào le lùkǒu xiàng yòu zhuǎn.","exVi":"Tới ngã tư thì rẽ phải.","w":"到 了 路口 向 右 转。"},{"zh":"座","py":"zuò","vi":"toà, ngọn (lượng từ vật lớn)","hv":"toạ","note":"Dùng cho vật LỚN và cố định: 一座山 (ngọn núi), 一座楼 (toà nhà), 一座桥 (cây cầu). Tiếng Việt cũng nói \"một toà nhà\".","ex":"那座楼有三十层。","exPy":"Nà zuò lóu yǒu sānshí céng.","exVi":"Toà nhà kia có ba mươi tầng.","w":"那 座 楼 有 三 十 层。"},{"zh":"座位","py":"zuòwèi","vi":"chỗ ngồi","hv":"toạ vị","note":"座 (chỗ ngồi) + 位 (vị trí, bài 43). Tiếng Việt: \"toạ độ\", \"vị trí\".","ex":"对不起，这个座位有人了。","exPy":"Duìbuqǐ, zhège zuòwèi yǒu rén le.","exVi":"Xin lỗi, chỗ này có người rồi.","w":"对不起， 这个 座位 有 人 了。"},{"zh":"口","py":"kǒu","vi":"miệng, cửa; người (lượng từ)","hv":"khẩu","note":"Bộ thủ đã học, nay dùng như từ độc lập: 门口 (cửa ra vào), 路口 (ngã tư). Cũng là lượng từ đếm nhân khẩu: 五口人.","ex":"我在学校门口等你。","exPy":"Wǒ zài xuéxiào ménkǒu děng nǐ.","exVi":"Tôi đợi bạn ở cổng trường.","w":"我 在 学校 门口 等 你。"},{"zh":"角","py":"jiǎo","vi":"góc; hào (tiền)","hv":"giác","note":"Chính là \"giác\" tiếng Việt (\"tam giác\", \"góc độ\"). Cũng là đơn vị tiền: 1 角 = 1/10 đồng.","ex":"这个房间的角落里有一盏灯。","exPy":"Zhège fángjiān de jiǎoluò lǐ yǒu yì zhǎn dēng.","exVi":"Góc phòng này có một cái đèn.","w":"这个 房间 的 角落 里 有 一 盏 灯。"},{"zh":"米","py":"mǐ","vi":"mét (đơn vị đo)","hv":"mễ","note":"Cùng chữ với 米饭 (gạo, bài 9) nhưng đây là nghĩa hiện đại: đơn vị MÉT. Người Trung Quốc mượn âm \"mètre\" gán vào chữ 米.","ex":"我弟弟已经一米八了。","exPy":"Wǒ dìdi yǐjīng yì mǐ bā le.","exVi":"Em trai tôi đã cao một mét tám rồi.","w":"我 弟弟 已经 一 米 八 了。"}],"newChars":["南","向","座","口","角"],"outro":"很好！Xong bài 70."};
G.ROOMS["zh-l071"] = {"id":"zh-l071","lang":"zh","level":3,"no":71,"teacher":"wang","title":"HSK3 · Bài 71 · 数量和程度 Đơn vị và mức độ","intro":["现在几点？— 差一刻三点。","Bài 71: Đo đếm chính xác hơn, và làm chủ cấu trúc 越…越… — càng… càng… Bấm 1 · Học để bắt đầu."],"introPy":"Xiànzài jǐ diǎn? — Chà yí kè sān diǎn.","gram":{"t":"越 … 越 … — càng… càng…","b":"越 + động từ/tính từ + 越 + tính từ","d":"Cấu trúc rất hay dùng, giống hệt \"càng… càng…\" tiếng Việt. Có biến thể 越来越… nghĩa là \"ngày càng…\": 越来越好 (ngày càng tốt hơn).","ex":[["汉语越学越有意思。","Tiếng Trung càng học càng thú vị.","Hànyǔ yuè xué yuè yǒu yìsi."],["他的汉语越来越好了。","Tiếng Trung của cậu ấy ngày càng khá lên.","Tā de Hànyǔ yuè lái yuè hǎo le."],["天气越来越冷了。","Trời ngày càng lạnh.","Tiānqì yuè lái yuè lěng le."]]},"grams":[{"t":"越 … 越 … — càng… càng…","b":"越 + động từ/tính từ + 越 + tính từ","d":"Cấu trúc rất hay dùng, giống hệt \"càng… càng…\" tiếng Việt. Có biến thể 越来越… nghĩa là \"ngày càng…\": 越来越好 (ngày càng tốt hơn).","ex":[["汉语越学越有意思。","Tiếng Trung càng học càng thú vị.","Hànyǔ yuè xué yuè yǒu yìsi."],["他的汉语越来越好了。","Tiếng Trung của cậu ấy ngày càng khá lên.","Tā de Hànyǔ yuè lái yuè hǎo le."],["天气越来越冷了。","Trời ngày càng lạnh.","Tiānqì yuè lái yuè lěng le."]]},{"t":"Xem giờ đầy đủ","b":"点 giờ · 分 phút · 刻 15 phút · 半 rưỡi · 差 kém","d":"8:15 = 八点一刻 hoặc 八点十五分. 8:30 = 八点半. 8:45 = 八点三刻 hoặc 差一刻九点. 7:50 = 差十分八点. Cách nói 差 giống hệt \"tám giờ kém mười\" của tiếng Việt.","ex":[["六点半","6 giờ rưỡi","liù diǎn bàn"],["九点一刻","9 giờ 15","jiǔ diǎn yí kè"],["差五分十点","10 giờ kém 5","chà wǔ fēn shí diǎn"]]},{"t":"极了 — đặt SAU tính từ","b":"tính từ + 极了","d":"Khác mọi phó từ khác (很, 非常, 太) đều đứng TRƯỚC, riêng 极了 đứng SAU tính từ. Mức độ rất mạnh, mang cảm thán: 好极了! 累极了!","ex":[["好极了！","Tuyệt cực!","Hǎo jí le!"],["今天热极了。","Hôm nay nóng kinh khủng.","Jīntiān rè jí le."]]}],"items":[{"zh":"半","py":"bàn","vi":"một nửa, rưỡi","hv":"bán","note":"Chính là \"bán\" tiếng Việt (\"bán cầu\", \"bán đảo\", \"bán kính\"). 八 (chia) trên 牛 — chia con trâu làm đôi.","ex":"我们等了半个小时。","exPy":"Wǒmen děng le bàn ge xiǎoshí.","exVi":"Chúng tôi đợi nửa tiếng.","w":"我们 等 了 半 个 小时。"},{"zh":"分","py":"fēn","vi":"phút; điểm; xu","hv":"phân","note":"Chính là \"phân\" tiếng Việt (\"phân chia\", \"phân số\"). Ba nghĩa: phút, điểm số, và đơn vị tiền nhỏ nhất.","ex":"这次考试他得了一百分。","exPy":"Zhè cì kǎoshì tā dé le yìbǎi fēn.","exVi":"Kỳ thi này cậu ấy được một trăm điểm.","w":"这 次 考试 他 得了 一 百 分。"},{"zh":"刻","py":"kè","vi":"khắc (15 phút)","hv":"khắc","note":"Chính là \"khắc\" tiếng Việt (\"một khắc\" = 15 phút trong cách nói cổ). 一刻 = 15 phút, 三刻 = 45 phút.","ex":"现在几点？— 差一刻三点。","exPy":"Xiànzài jǐ diǎn? — Chà yí kè sān diǎn.","exVi":"Bây giờ mấy giờ? — Ba giờ kém mười lăm.","w":"现在 几 点？— 差 一 刻 三 点。"},{"zh":"段","py":"duàn","vi":"đoạn, khúc","hv":"đoạn","note":"Chính là \"đoạn\" tiếng Việt. Dùng cho đoạn đường, đoạn văn, quãng thời gian: 一段路, 一段时间.","ex":"这段路很不好走。","exPy":"Zhè duàn lù hěn bù hǎo zǒu.","exVi":"Đoạn đường này rất khó đi.","w":"这 段 路 很 不 好 走。"},{"zh":"辆","py":"liàng","vi":"chiếc (lượng từ cho xe)","hv":"lượng","note":"Có bộ 车 (xe) bên trái — nhìn là biết dùng cho xe cộ: 一辆车, 一辆自行车.","ex":"门口停着两辆自行车。","exPy":"Ménkǒu tíng zhe liǎng liàng zìxíngchē.","exVi":"Ngoài cửa đỗ hai chiếc xe đạp.","w":"门口 停 着 两 辆 自行车。"},{"zh":"种","py":"zhǒng","vi":"loại, thứ","hv":"chủng","note":"Chính là \"chủng\" tiếng Việt (\"chủng loại\", \"nhân chủng\"). Bộ 禾 (lúa) — vốn nghĩa là giống cây.","ex":"这种茶你喝过吗？","exPy":"Zhè zhǒng chá nǐ hē guo ma?","exVi":"Loại trà này bạn uống bao giờ chưa?","w":"这 种 茶 你 喝 过 吗？"},{"zh":"极","py":"jí","vi":"cực kỳ","hv":"cực","note":"Chính là \"cực\" tiếng Việt (\"cực kỳ\", \"tích cực\"). Thường đặt SAU tính từ kèm 了: 好极了 = tuyệt cực.","ex":"昨天的比赛精彩极了！","exPy":"Zuótiān de bǐsài jīngcǎi jí le!","exVi":"Trận đấu hôm qua hay cực kỳ!","w":"昨天 的 比赛 精彩 极 了！"},{"zh":"几乎","py":"jīhū","vi":"hầu như, gần như","hv":"kỷ hồ","note":"几 (mấy) + 乎 (trợ từ cổ). Đứng trước động từ hoặc tính từ: 几乎忘了 (suýt quên).","ex":"我几乎忘了今天有会议。","exPy":"Wǒ jīhū wàng le jīntiān yǒu huìyì.","exVi":"Tôi suýt quên hôm nay có họp.","w":"我 几乎 忘 了 今天 有 会议。"},{"zh":"差","py":"chà","vi":"kém, thiếu; tệ","hv":"sai","note":"Hai cách dùng: xem giờ (差五分八点 = tám giờ kém năm) và chê chất lượng (成绩很差 = điểm kém).","ex":"他的成绩比以前差了一点儿。","exPy":"Tā de chéngjì bǐ yǐqián chà le yìdiǎnr.","exVi":"Điểm của cậu ấy kém hơn trước một chút.","w":"他 的 成绩 比 以前 差 了 一点儿。"},{"zh":"越","py":"yuè","vi":"càng (trong 越…越…)","hv":"việt","note":"Chính là chữ \"Việt\" trong 越南 (Việt Nam), nghĩa gốc là VƯỢT QUA. Dùng trong cấu trúc 越…越… rất thông dụng.","ex":"越努力，成绩越好。","exPy":"Yuè nǔlì, chéngjì yuè hǎo.","exVi":"Càng cố gắng, điểm càng cao.","w":"越 努力， 成绩 越 好。"}],"newChars":["半","刻","段","辆","种","极","乎","差","越"],"outro":"很好！Xong bài 71."};
G.ROOMS["zh-l072"] = {"id":"zh-l072","lang":"zh","level":3,"no":72,"teacher":"wang","title":"HSK3 · Bài 72 · 连接句子 Liên từ và điều kiện","intro":["如果明天天气好，我们就去爬山。","Bài 72: Ghép câu dài mạch lạc — bộ liên từ này là ranh giới giữa nói bập bẹ và nói trôi chảy. Bấm 1 · Học để bắt đầu."],"introPy":"Rúguǒ míngtiān tiānqì hǎo, wǒmen jiù qù páshān.","gram":{"t":"或者 và 还是 — hai chữ \"hoặc\" không thay nhau được","b":"或者 dùng trong câu KỂ · 还是 dùng trong câu HỎI","d":"Đây là lỗi kinh điển. 你喝茶还是咖啡？(bạn uống trà hay cà phê? — câu hỏi). 我喝茶或者咖啡都行 (trà hay cà phê đều được — câu kể). Dùng ngược là người bản xứ thấy sai ngay.","ex":[["你去还是我去？","Bạn đi hay tôi đi? (HỎI)","Nǐ qù háishi wǒ qù?"],["你去或者我去都可以。","Bạn đi hay tôi đi đều được. (KỂ)","Nǐ qù huòzhě wǒ qù dōu kěyǐ."]]},"grams":[{"t":"或者 và 还是 — hai chữ \"hoặc\" không thay nhau được","b":"或者 dùng trong câu KỂ · 还是 dùng trong câu HỎI","d":"Đây là lỗi kinh điển. 你喝茶还是咖啡？(bạn uống trà hay cà phê? — câu hỏi). 我喝茶或者咖啡都行 (trà hay cà phê đều được — câu kể). Dùng ngược là người bản xứ thấy sai ngay.","ex":[["你去还是我去？","Bạn đi hay tôi đi? (HỎI)","Nǐ qù háishi wǒ qù?"],["你去或者我去都可以。","Bạn đi hay tôi đi đều được. (KỂ)","Nǐ qù huòzhě wǒ qù dōu kěyǐ."]]},{"t":"除了 có HAI nghĩa trái ngược — nhìn 都 hay 也 mà đoán","b":"除了…, 都… (loại trừ) · 除了…, 也… (bao gồm)","d":"Vế sau dùng 都 thì nghĩa là LOẠI TRỪ: 除了他，大家都去了 (trừ anh ấy, mọi người đều đi). Vế sau dùng 也/还 thì nghĩa là NGOÀI RA CÒN: 除了汉语，我还会说英语 (ngoài tiếng Trung, tôi còn biết tiếng Anh).","ex":[["除了小王，我们都去过北京。","Trừ Tiểu Vương, chúng tôi đều từng đi Bắc Kinh.","Chúle Xiǎo Wáng, wǒmen dōu qù guo Běijīng."],["除了苹果，我还买了葡萄。","Ngoài táo, tôi còn mua nho.","Chúle píngguǒ, wǒ hái mǎi le pútao."]]},{"t":"Bốn cặp liên từ cần thuộc lòng","b":"因为…所以… · 虽然…但是… · 不但…而且… · 只有…才…","d":"Tiếng Trung dùng ĐỦ CẢ CẶP, khác tiếng Anh thường lược một vế. May mắn là tiếng Việt cũng đi theo cặp: vì…nên…, tuy…nhưng…, không những…mà còn…, chỉ có…mới…. Người Việt nắm phần này rất nhanh.","ex":[["他不但聪明，而且很努力。","Cậu ấy không những thông minh, mà còn rất chăm.","Tā bùdàn cōngming, érqiě hěn nǔlì."],["只有多练习，才能提高水平。","Chỉ có luyện nhiều mới nâng được trình độ.","Zhǐyǒu duō liànxí, cái néng tígāo shuǐpíng."]]},{"t":"为了 và 因为 — mục đích khác nguyên nhân","b":"为了 + mục đích · 因为 + nguyên nhân","d":"为了健康，我每天运动 (VÌ MỤC ĐÍCH sức khoẻ — hướng tới tương lai). 因为生病，我没去上班 (VÌ LÝ DO ốm — đã xảy ra). Người Việt hay dùng lẫn vì tiếng Việt đều nói \"vì\".","ex":[["为了考试，我复习了一个星期。","Để thi, tôi ôn cả tuần.","Wèile kǎoshì, wǒ fùxí le yí ge xīngqī."],["因为下雨，比赛结束了。","Vì mưa nên trận đấu kết thúc.","Yīnwèi xiàyǔ, bǐsài jiéshù le."]]}],"items":[{"zh":"如果","py":"rúguǒ","vi":"nếu","hv":"như quả","note":"如 = \"như\" trong \"ví như\", \"như ý\". Vế sau thường có 就: 如果…就….","ex":"如果明天天气好，我们就去爬山。","exPy":"Rúguǒ míngtiān tiānqì hǎo, wǒmen jiù qù páshān.","exVi":"Nếu mai trời đẹp thì chúng ta đi leo núi.","w":"如果 明天 天气 好， 我们 就 去 爬山。"},{"zh":"或者","py":"huòzhě","vi":"hoặc (trong câu kể)","hv":"hoặc giả","note":"Chính là \"hoặc giả\" tiếng Việt. QUAN TRỌNG: chỉ dùng trong câu KỂ, không dùng để hỏi — câu hỏi phải dùng 还是.","ex":"你可以坐地铁或者坐公共汽车。","exPy":"Nǐ kěyǐ zuò dìtiě huòzhě zuò gōnggòng qìchē.","exVi":"Bạn có thể đi tàu điện hoặc xe buýt.","w":"你 可以 坐 地铁 或者 坐 公共汽车。"},{"zh":"然后","py":"ránhòu","vi":"sau đó, rồi thì","hv":"nhiên hậu","note":"然 là đuôi quen thuộc (当然, 虽然, 突然). Dùng để kể trình tự các bước.","ex":"我先去银行，然后去超市。","exPy":"Wǒ xiān qù yínháng, ránhòu qù chāoshì.","exVi":"Tôi đi ngân hàng trước, rồi đi siêu thị.","w":"我 先 去 银行， 然后 去 超市。"},{"zh":"除了","py":"chúle","vi":"ngoài… ra","hv":"trừ liễu","note":"除 = \"trừ\" trong \"loại trừ\", \"trừ phi\". Hai nghĩa trái ngược nhau, xem phần ngữ pháp.","ex":"除了我，别人都同意了。","exPy":"Chúle wǒ, biéren dōu tóngyì le.","exVi":"Trừ tôi ra, người khác đều đồng ý.","w":"除了 我， 别人 都 同意 了。"},{"zh":"不但","py":"bùdàn","vi":"không những","hv":"bất đãn","note":"不 (không) + 但 (chỉ). Luôn đi cặp với 而且 ở vế sau.","ex":"这里不但安静，而且很方便。","exPy":"Zhèlǐ bùdàn ānjìng, érqiě hěn fāngbiàn.","exVi":"Ở đây không những yên tĩnh mà còn rất tiện.","w":"这里 不但 安静， 而且 很 方便。"},{"zh":"而且","py":"érqiě","vi":"mà còn, hơn nữa","hv":"nhi thả","note":"Đứng đầu vế thứ hai. Có thể dùng một mình mà không cần 不但: 这里很近，而且很方便.","ex":"这个菜好吃，而且便宜。","exPy":"Zhège cài hǎochī, érqiě piányi.","exVi":"Món này ngon, mà lại rẻ.","w":"这个 菜 好吃， 而且 便宜。"},{"zh":"只有","py":"zhǐyǒu","vi":"chỉ có, chỉ khi","hv":"chỉ hữu","note":"Đi cặp với 才 ở vế sau: 只有…才… (chỉ khi… mới…). Nhấn mạnh điều kiện DUY NHẤT.","ex":"只有每天练习，才能写好汉字。","exPy":"Zhǐyǒu měi tiān liànxí, cái néng xiě hǎo Hànzì.","exVi":"Chỉ có luyện mỗi ngày mới viết đẹp chữ Hán.","w":"只有 每 天 练习， 才能 写 好 汉字。"},{"zh":"根据","py":"gēnjù","vi":"căn cứ vào, dựa theo","hv":"căn cứ","note":"Chính là \"căn cứ\" tiếng Việt: 根 (rễ, gốc) + 据 (dựa). Đứng đầu câu.","ex":"根据我的经验，这个办法最好。","exPy":"Gēnjù wǒ de jīngyàn, zhège bànfǎ zuì hǎo.","exVi":"Theo kinh nghiệm của tôi, cách này tốt nhất.","w":"根据 我 的 经验， 这个 办法 最好。"},{"zh":"关于","py":"guānyú","vi":"về, liên quan tới","hv":"quan ư","note":"关 (liên quan) + 于 (ở). Đứng ĐẦU câu: 关于这个问题, 我有话说.","ex":"关于这件事，我不太清楚。","exPy":"Guānyú zhè jiàn shì, wǒ bú tài qīngchu.","exVi":"Về việc này, tôi không rõ lắm.","w":"关于 这 件 事， 我 不 太 清楚。"},{"zh":"为了","py":"wèile","vi":"để, vì mục đích","hv":"vị liễu","note":"Chỉ MỤC ĐÍCH (làm gì để đạt được gì), khác 因为 chỉ NGUYÊN NHÂN. Đứng đầu câu.","ex":"为了身体健康，他每天早上跑步。","exPy":"Wèile shēntǐ jiànkāng, tā měi tiān zǎoshang pǎobù.","exVi":"Vì sức khoẻ, sáng nào anh ấy cũng chạy bộ.","w":"为了 身体 健康， 他 每 天 早上 跑步。"}],"newChars":["或","除","根","据"],"outro":"很好！Xong bài 72."};
G.ROOMS["zh-l073"] = {"id":"zh-l073","lang":"zh","level":3,"no":73,"teacher":"wang","title":"HSK3 · Bài 73 · 重要的语法词 Ngữ pháp trọng tâm","intro":["请把这些东西放在桌子上。","Bài 73: Câu bị động với 被, so sánh bằng 跟…一样, và trạng ngữ với 地 — ba cột trụ của HSK 3. Bấm 1 · Học để bắt đầu."],"introPy":"Qǐng bǎ zhèxiē dōngxi fàng zài zhuōzi shàng.","gram":{"t":"Câu bị động với 被","b":"Người/vật bị + 被 (+ kẻ gây ra) + động từ + kết quả","d":"被 gần như là chữ \"bị\" tiếng Việt, cả về âm lẫn nghĩa. Kẻ gây ra có thể lược đi: 我的车被偷了. Giống câu 把, sau động từ BẮT BUỘC có phần kết quả (了, 走, 完…). Lưu ý: tiếng Trung dùng 被 ít hơn tiếng Việt nhiều, và thường cho việc KHÔNG MAY.","ex":[["我的手机被弟弟拿走了。","Điện thoại tôi bị em trai lấy mất.","Wǒ de shǒujī bèi dìdi ná zǒu le."],["蛋糕被孩子们吃完了。","Bánh bị bọn trẻ ăn hết rồi.","Dàngāo bèi háizimen chī wán le."]]},"grams":[{"t":"Câu bị động với 被","b":"Người/vật bị + 被 (+ kẻ gây ra) + động từ + kết quả","d":"被 gần như là chữ \"bị\" tiếng Việt, cả về âm lẫn nghĩa. Kẻ gây ra có thể lược đi: 我的车被偷了. Giống câu 把, sau động từ BẮT BUỘC có phần kết quả (了, 走, 完…). Lưu ý: tiếng Trung dùng 被 ít hơn tiếng Việt nhiều, và thường cho việc KHÔNG MAY.","ex":[["我的手机被弟弟拿走了。","Điện thoại tôi bị em trai lấy mất.","Wǒ de shǒujī bèi dìdi ná zǒu le."],["蛋糕被孩子们吃完了。","Bánh bị bọn trẻ ăn hết rồi.","Dàngāo bèi háizimen chī wán le."]]},{"t":"把 và 被 — hai mặt của một đồng xu","b":"把 = tôi làm gì đó với nó · 被 = nó bị làm gì đó","d":"Cùng một sự việc, hai góc nhìn: 弟弟把蛋糕吃完了 (em trai ăn hết bánh) và 蛋糕被弟弟吃完了 (bánh bị em trai ăn hết). Cả hai đều cần phần KẾT QUẢ sau động từ.","ex":[["他把窗户打开了。","Anh ấy mở cửa sổ ra.","Tā bǎ chuānghu dǎkāi le."],["窗户被他打开了。","Cửa sổ bị anh ấy mở ra.","Chuānghu bèi tā dǎkāi le."]]},{"t":"跟 … 一样 — giống như","b":"A + 跟 + B + 一样 (+ tính từ)","d":"Nói hai thứ giống nhau. Thêm tính từ để nói giống ở điểm nào: 他跟我一样高 (anh ấy cao bằng tôi). Phủ định: 不一样.","ex":[["我的手机跟你的一样。","Điện thoại của tôi giống của bạn.","Wǒ de shǒujī gēn nǐ de yíyàng."],["他跟我一样大。","Anh ấy bằng tuổi tôi.","Tā gēn wǒ yíyàng dà."],["这两件衣服不一样。","Hai bộ đồ này không giống nhau.","Zhè liǎng jiàn yīfu bù yíyàng."]]},{"t":"地 — biến tính từ thành trạng ngữ","b":"tính từ + 地 + động từ","d":"Đừng nhầm ba chữ đọc \"de\": 的 (sở hữu, đứng trước DANH TỪ), 得 (bổ ngữ, đứng SAU động từ), 地 (trạng ngữ, đứng TRƯỚC động từ). Ba chữ này là cửa ải lớn của HSK 3.","ex":[["他高兴地笑了。","Anh ấy cười vui vẻ. (地 trước động từ)","Tā gāoxìng de xiào le."],["他笑得很高兴。","Anh ấy cười rất vui. (得 sau động từ)","Tā xiào de hěn gāoxìng."],["他是一个高兴的人。","Anh ấy là người vui vẻ. (的 trước danh từ)","Tā shì yí ge gāoxìng de rén."]]}],"items":[{"zh":"把","py":"bǎ","vi":"(giới từ đưa tân ngữ lên trước)","hv":"bả","note":"Đã học ở bài 44. Bộ 扌 (tay) — nghĩa gốc là \"nắm lấy\". Cũng là lượng từ: 一把伞 (một cái ô).","ex":"请把这些东西放在桌子上。","exPy":"Qǐng bǎ zhèxiē dōngxi fàng zài zhuōzi shàng.","exVi":"Xin đặt mấy thứ này lên bàn.","w":"请 把 这些 东西 放 在 桌子 上。"},{"zh":"被","py":"bèi","vi":"bị, được (câu bị động)","hv":"bị","note":"Chính là chữ \"bị\" trong \"bị động\", \"bị hại\" của tiếng Việt. Bộ 衤 (áo) — nghĩa gốc là cái chăn đắp lên người.","ex":"我的伞被人拿走了。","exPy":"Wǒ de sǎn bèi rén ná zǒu le.","exVi":"Cái ô của tôi bị người ta lấy mất.","w":"我 的 伞 被 人 拿 走 了。"},{"zh":"地","py":"de","vi":"(trợ từ nối trạng ngữ)","hv":"địa","note":"Cùng chữ với 地方 (bài 40) nhưng khi làm trợ từ thì đọc nhẹ là de. Nối tính từ với động từ.","ex":"孩子们高兴地跑了出去。","exPy":"Háizimen gāoxìng de pǎo le chūqu.","exVi":"Bọn trẻ vui vẻ chạy ra ngoài.","w":"孩子 们 高兴 地 跑 了 出去。"},{"zh":"跟","py":"gēn","vi":"với, cùng; theo","hv":"cân","note":"Bộ ⻊ (chân) — nghĩa gốc là đi theo sau. Gần nghĩa với 和 nhưng 跟 dùng được với động từ: 跟我来 (đi theo tôi).","ex":"我跟他一起去看电影。","exPy":"Wǒ gēn tā yìqǐ qù kàn diànyǐng.","exVi":"Tôi đi xem phim cùng anh ấy.","w":"我 跟 他 一起 去 看 电影。"},{"zh":"更","py":"gèng","vi":"càng, hơn nữa","hv":"cánh","note":"Dùng khi đã có một mức so sánh sẵn: 这个好，那个更好 (cái này tốt, cái kia còn tốt hơn).","ex":"这个比那个更便宜。","exPy":"Zhège bǐ nàge gèng piányi.","exVi":"Cái này còn rẻ hơn cái kia.","w":"这个 比 那个 更 便宜。"},{"zh":"又","py":"yòu","vi":"lại (việc ĐÃ xảy ra)","hv":"hựu","note":"Bộ thủ đã học (hình bàn tay). Khác 再 (bài 30): 又 cho việc đã lặp lại rồi, 再 cho việc sắp lặp lại.","ex":"他昨天来了，今天又来了。","exPy":"Tā zuótiān lái le, jīntiān yòu lái le.","exVi":"Hôm qua anh ấy đến, hôm nay lại đến nữa.","w":"他 昨天 来 了， 今天 又 来 了。"},{"zh":"比较","py":"bǐjiào","vi":"khá, tương đối; so sánh","hv":"tỷ giảo","note":"比 (so, bài 28) + 较 (so đo). Làm phó từ nghĩa là \"khá\" — nhẹ hơn 很: 比较好 = khá tốt.","ex":"今天的作业比较简单。","exPy":"Jīntiān de zuòyè bǐjiào jiǎndān.","exVi":"Bài tập hôm nay khá đơn giản.","w":"今天 的 作业 比较 简单。"},{"zh":"一样","py":"yíyàng","vi":"giống nhau, như nhau","hv":"nhất dạng","note":"样 = \"dạng\" trong \"hình dạng\", \"đa dạng\". Dùng trong cấu trúc 跟…一样.","ex":"我的想法跟你的一样。","exPy":"Wǒ de xiǎngfǎ gēn nǐ de yíyàng.","exVi":"Suy nghĩ của tôi giống bạn.","w":"我 的 想法 跟 你 的 一样。"},{"zh":"一定","py":"yídìng","vi":"nhất định, chắc chắn","hv":"nhất định","note":"Chính là \"nhất định\" tiếng Việt. Đứng trước động từ: 我一定去.","ex":"你放心，我一定帮你。","exPy":"Nǐ fàngxīn, wǒ yídìng bāng nǐ.","exVi":"Bạn yên tâm, tôi nhất định giúp bạn.","w":"你 放心， 我 一定 帮 你。"},{"zh":"应该","py":"yīnggāi","vi":"nên, phải","hv":"ứng cai","note":"Nói về bổn phận và lời khuyên. Nói tắt là 该. Phủ định: 不应该 (không nên).","ex":"生病了就应该去看医生。","exPy":"Shēngbìng le jiù yīnggāi qù kàn yīshēng.","exVi":"Ốm rồi thì nên đi khám bác sĩ.","w":"生病 了 就 应该 去 看 医生。"}],"newChars":["把","被","跟","更","又","较","应","该"],"outro":"很好！Xong bài 73."};
G.ROOMS["zh-l074"] = {"id":"zh-l074","lang":"zh","level":3,"no":74,"teacher":"wang","title":"HSK3 · Bài 74 · 计划和重要的事 Dự định và điều quan trọng","intro":["你毕业以后有什么打算？","Bài 74: Nói kế hoạch, nhấn mạnh điều cần chú ý — bài có mật độ từ Hán Việt cao nhất giáo trình. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ bìyè yǐhòu yǒu shénme dǎsuàn?","gram":{"t":"Thang bắt buộc: 想 < 要 < 应该 < 必须","b":"想 muốn · 要 cần · 应该 nên · 必须 bắt buộc","d":"Bốn mức tăng dần. 我想去 (tôi muốn đi), 我要去 (tôi cần đi), 我应该去 (tôi nên đi), 我必须去 (tôi buộc phải đi). Chọn đúng mức là câu nói có sắc thái chuẩn xác.","ex":[["你应该多练习。","Bạn nên luyện nhiều hơn. (lời khuyên)","Nǐ yīnggāi duō liànxí."],["你必须参加考试。","Bạn bắt buộc phải dự thi. (không có lựa chọn)","Nǐ bìxū cānjiā kǎoshì."]]},"grams":[{"t":"Thang bắt buộc: 想 < 要 < 应该 < 必须","b":"想 muốn · 要 cần · 应该 nên · 必须 bắt buộc","d":"Bốn mức tăng dần. 我想去 (tôi muốn đi), 我要去 (tôi cần đi), 我应该去 (tôi nên đi), 我必须去 (tôi buộc phải đi). Chọn đúng mức là câu nói có sắc thái chuẩn xác.","ex":[["你应该多练习。","Bạn nên luyện nhiều hơn. (lời khuyên)","Nǐ yīnggāi duō liànxí."],["你必须参加考试。","Bạn bắt buộc phải dự thi. (không có lựa chọn)","Nǐ bìxū cānjiā kǎoshì."]]},{"t":"用 làm giới từ: dùng cái gì để làm gì","b":"用 + công cụ + động từ","d":"Cả cụm 用… đứng TRƯỚC động từ chính, đúng quy tắc của 在, 给, 对 đã học. Nói 我吃饭用筷子 là sai trật tự; đúng là 我用筷子吃饭.","ex":[["中国人用筷子吃饭。","Người Trung Quốc dùng đũa ăn cơm.","Zhōngguó rén yòng kuàizi chīfàn."],["请用铅笔写。","Xin viết bằng bút chì.","Qǐng yòng qiānbǐ xiě."]]},{"t":"Bảy từ Hán Việt trùng khít trong một bài","b":"当然 · 机会 · 影响 · 变化 · 主要 · 重要 · 注意","d":"Đương nhiên, cơ hội, ảnh hưởng, biến hoá, chủ yếu, trọng yếu, chú ý — bảy từ này bạn đã dùng bằng tiếng Việt suốt đời. Đây là bài minh hoạ rõ nhất vì sao người Việt học tiếng Trung nhanh hơn người phương Tây rất nhiều ở trình độ trung cấp: vốn từ trừu tượng gần như có sẵn.","ex":[["这件事很重要，请注意。","Việc này rất quan trọng, xin chú ý.","Zhè jiàn shì hěn zhòngyào, qǐng zhùyì."],["这个机会对我影响很大。","Cơ hội này ảnh hưởng lớn tới tôi.","Zhège jīhuì duì wǒ yǐngxiǎng hěn dà."]]}],"items":[{"zh":"打算","py":"dǎsuàn","vi":"dự định, tính toán","hv":"đả toán","note":"打 (làm) + 算 (tính, bộ 竹 vì bàn tính làm bằng tre). Gần nghĩa với 准备 (bài 20) nhưng nhấn vào việc ĐÃ NGHĨ SẴN.","ex":"你毕业以后有什么打算？","exPy":"Nǐ bìyè yǐhòu yǒu shénme dǎsuàn?","exVi":"Sau khi tốt nghiệp bạn dự định gì?","w":"你 毕业 以后 有 什么 打算？"},{"zh":"当然","py":"dāngrán","vi":"đương nhiên, tất nhiên","hv":"đương nhiên","note":"Chính là \"đương nhiên\" tiếng Việt. Trả lời đồng ý dứt khoát: 当然可以！","ex":"当然可以，没问题。","exPy":"Dāngrán kěyǐ, méi wèntí.","exVi":"Tất nhiên được, không vấn đề gì.","w":"当然 可以， 没 问题。"},{"zh":"必须","py":"bìxū","vi":"bắt buộc phải","hv":"tất tu","note":"必 = \"tất\" trong \"tất yếu\", \"tất nhiên\". Mạnh hơn 应该 (nên) — 必须 là BẮT BUỘC, không có lựa chọn.","ex":"考试的时候必须带学生证。","exPy":"Kǎoshì de shíhou bìxū dài xuéshēngzhèng.","exVi":"Khi thi bắt buộc mang thẻ học sinh.","w":"考试 的 时候 必须 带 学生 证。"},{"zh":"机会","py":"jīhuì","vi":"cơ hội","hv":"cơ hội","note":"Chính là \"cơ hội\" tiếng Việt: 机 (cơ, thời cơ) + 会 (hội). Không sai một ly.","ex":"这是提高汉语水平的好机会。","exPy":"Zhè shì tígāo Hànyǔ shuǐpíng de hǎo jīhuì.","exVi":"Đây là cơ hội tốt để nâng cao trình độ tiếng Trung.","w":"这 是 提高 汉语 水平 的 好 机会。"},{"zh":"影响","py":"yǐngxiǎng","vi":"ảnh hưởng","hv":"ảnh hưởng","note":"Chính là \"ảnh hưởng\" tiếng Việt: 影 (bóng) + 响 (tiếng vang). Bóng và tiếng vọng lại — hình ảnh rất hay.","ex":"天气不好，影响了比赛。","exPy":"Tiānqì bù hǎo, yǐngxiǎng le bǐsài.","exVi":"Thời tiết xấu đã ảnh hưởng tới trận đấu.","w":"天气 不 好， 影响 了 比赛。"},{"zh":"变化","py":"biànhuà","vi":"thay đổi, biến đổi","hv":"biến hoá","note":"Chính là \"biến hoá\" tiếng Việt: 变 (biến) + 化 (hoá).","ex":"十年来这个城市变化很大。","exPy":"Shí nián lái zhège chéngshì biànhuà hěn dà.","exVi":"Mười năm qua thành phố này thay đổi rất nhiều.","w":"十 年 来 这个 城市 变化 很 大。"},{"zh":"主要","py":"zhǔyào","vi":"chủ yếu","hv":"chủ yếu","note":"Chính là \"chủ yếu\" tiếng Việt: 主 (chủ) + 要 (yếu).","ex":"我们今天主要谈这个问题。","exPy":"Wǒmen jīntiān zhǔyào tán zhège wèntí.","exVi":"Hôm nay chúng ta chủ yếu bàn vấn đề này.","w":"我们 今天 主要 谈 这个 问题。"},{"zh":"重要","py":"zhòngyào","vi":"quan trọng","hv":"trọng yếu","note":"Chính là \"trọng yếu\" tiếng Việt. Chú ý 重 ở đây đọc zhòng (trọng), còn khi nghĩa \"lặp lại\" thì đọc chóng.","ex":"身体健康最重要。","exPy":"Shēntǐ jiànkāng zuì zhòngyào.","exVi":"Sức khoẻ là quan trọng nhất.","w":"身体 健康 最 重要。"},{"zh":"注意","py":"zhùyì","vi":"chú ý, để ý","hv":"chú ý","note":"Chính là \"chú ý\" tiếng Việt: 注 (rót vào, bộ 氵) + 意 (ý) — dồn ý vào một chỗ.","ex":"过马路的时候要注意安全。","exPy":"Guò mǎlù de shíhou yào zhùyì ānquán.","exVi":"Khi qua đường phải chú ý an toàn.","w":"过 马路 的 时候 要 注意 安全。"},{"zh":"用","py":"yòng","vi":"dùng, sử dụng","hv":"dụng","note":"Chính là \"dụng\" tiếng Việt (\"sử dụng\", \"công dụng\", \"hữu dụng\"). Cũng là giới từ: 用筷子吃饭.","ex":"你可以用我的电脑。","exPy":"Nǐ kěyǐ yòng wǒ de diànnǎo.","exVi":"Bạn có thể dùng máy tính của tôi.","w":"你 可以 用 我 的 电脑。"}],"newChars":["算","必","须","主","注"],"outro":"很好！Xong bài 74."};
G.ROOMS["zh-l075"] = {"id":"zh-l075","lang":"zh","level":3,"no":75,"teacher":"wang","title":"HSK3 · Bài 75 · 留学和环境 Du học và môi trường","intro":["他去年去中国留学了。","Bài 75: Nói về việc học xa nhà, mô tả âm thanh và hoàn cảnh, dùng 其他 để nói \"những cái khác\". Bấm 1 · Học để bắt đầu."],"introPy":"Tā qùnián qù Zhōngguó liúxué le.","gram":{"t":"Đuôi 者 — người làm việc gì đó","b":"作者 · 读者 · 记者 · 学者","d":"者 nghĩa là \"người\". Ghép sau động từ ra tên nghề hoặc vai trò. Tiếng Việt cũng có \"tác giả\", \"độc giả\", \"ký giả\", \"học giả\" — cùng một cách ghép, nên bạn đoán được ngay.","ex":[["作者 · 读者 · 记者","tác giả · độc giả · ký giả","zuòzhě · dúzhě · jìzhě"]]},"grams":[{"t":"Đuôi 者 — người làm việc gì đó","b":"作者 · 读者 · 记者 · 学者","d":"者 nghĩa là \"người\". Ghép sau động từ ra tên nghề hoặc vai trò. Tiếng Việt cũng có \"tác giả\", \"độc giả\", \"ký giả\", \"học giả\" — cùng một cách ghép, nên bạn đoán được ngay.","ex":[["作者 · 读者 · 记者","tác giả · độc giả · ký giả","zuòzhě · dúzhě · jìzhě"]]},{"t":"经过 — hai nghĩa, hai cách dùng","b":"经过 + nơi chốn (đi ngang) · 经过 + quá trình (trải qua)","d":"经过银行 (đi ngang ngân hàng). 经过三年的努力 (sau ba năm cố gắng). Nghĩa thứ hai rất hay dùng ở đầu câu để nêu quá trình dẫn tới kết quả.","ex":[["我每天上班都经过这个公园。","Ngày nào đi làm tôi cũng đi qua công viên này.","Wǒ měi tiān shàngbān dōu jīngguò zhège gōngyuán."],["经过检查，医生说我很健康。","Sau khi khám, bác sĩ nói tôi rất khoẻ.","Jīngguò jiǎnchá, yīshēng shuō wǒ hěn jiànkāng."]]},{"t":"好久不见 — câu chào của người quen cũ","b":"好久不见！","d":"Câu chào bắt buộc thuộc, dùng khi gặp lại người lâu không gặp. 好 ở đây nghĩa là \"rất\", không phải \"tốt\". Đáp lại cũng bằng chính câu đó.","ex":[["好久不见！你最近怎么样？","Lâu rồi không gặp! Dạo này bạn thế nào?","Hǎo jiǔ bú jiàn! Nǐ zuìjìn zěnmeyàng?"]]}],"items":[{"zh":"留学","py":"liúxué","vi":"du học","hv":"lưu học","note":"留 (ở lại) + 学 (học) — ở lại nước ngoài mà học. Du học sinh là 留学生. Là động từ ly hợp: 留了三年学.","ex":"他去年去中国留学了。","exPy":"Tā qùnián qù Zhōngguó liúxué le.","exVi":"Năm ngoái cậu ấy đi du học Trung Quốc.","w":"他 去年 去 中国 留学 了。"},{"zh":"经过","py":"jīngguò","vi":"đi qua; trải qua","hv":"kinh quá","note":"经 (kinh, trải) + 过 (qua, bài 25). Hai nghĩa: đi ngang qua một nơi, và trải qua một quá trình.","ex":"经过一年的学习，我能看懂中文报纸了。","exPy":"Jīngguò yì nián de xuéxí, wǒ néng kàn dǒng Zhōngwén bàozhǐ le.","exVi":"Sau một năm học, tôi đã đọc hiểu được báo tiếng Trung.","w":"经过 一 年 的 学习， 我 能 看 懂 中文 报纸 了。"},{"zh":"久","py":"jiǔ","vi":"lâu","hv":"cửu","note":"Chính là \"cửu\" tiếng Việt (\"vĩnh cửu\", \"trường cửu\"). Câu chào người lâu không gặp: 好久不见！","ex":"好久不见，你变化真大！","exPy":"Hǎo jiǔ bú jiàn, nǐ biànhuà zhēn dà!","exVi":"Lâu rồi không gặp, bạn thay đổi nhiều thật!","w":"好久 不见， 你 变化 真 大！"},{"zh":"声音","py":"shēngyīn","vi":"âm thanh, giọng","hv":"thanh âm","note":"Chính là \"thanh âm\" tiếng Việt: 声 (thanh) + 音 (âm). 音 cũng nằm trong 音乐 (bài 38).","ex":"外面的声音太大了，我听不清楚。","exPy":"Wàimiàn de shēngyīn tài dà le, wǒ tīng bu qīngchu.","exVi":"Tiếng bên ngoài to quá, tôi nghe không rõ.","w":"外面 的 声音 太 大 了， 我 听 不 清楚。"},{"zh":"哭","py":"kū","vi":"khóc","hv":"khốc","note":"Chính là \"khốc\" tiếng Việt (\"khốc liệt\", \"thống khốc\"). Chữ tượng hình: hai con mắt 口口 đang chảy nước. Trái nghĩa với 笑 (cười, bài 26).","ex":"妹妹一看这个电影就哭了。","exPy":"Mèimei yí kàn zhège diànyǐng jiù kū le.","exVi":"Em gái vừa xem phim này là khóc.","w":"妹妹 一 看 这个 电影 就 哭 了。"},{"zh":"黄河","py":"Huáng Hé","vi":"sông Hoàng Hà","hv":"Hoàng Hà","note":"Chính là \"Hoàng Hà\" tiếng Việt: 黄 (vàng) + 河 (sông, bộ 氵). Cái nôi của văn minh Trung Hoa.","ex":"黄河经过很多城市。","exPy":"Huáng Hé jīngguò hěn duō chéngshì.","exVi":"Sông Hoàng Hà chảy qua nhiều thành phố.","w":"黄河 经过 很 多 城市。"},{"zh":"环境","py":"huánjìng","vi":"môi trường, hoàn cảnh","hv":"hoàn cảnh","note":"Âm Hán Việt là \"hoàn cảnh\" nhưng nghĩa thường dùng là MÔI TRƯỜNG (thiên nhiên, nơi sống). 环 = vòng, 境 = cảnh giới.","ex":"我们应该关心环境问题。","exPy":"Wǒmen yīnggāi guānxīn huánjìng wèntí.","exVi":"Chúng ta nên quan tâm tới vấn đề môi trường.","w":"我们 应该 关心 环境 问题。"},{"zh":"作者","py":"zuòzhě","vi":"tác giả","hv":"tác giả","note":"Chính là \"tác giả\" tiếng Việt: 作 (làm, sáng tác) + 者 (giả, người). Đuôi 者 rất hay gặp: 记者 (ký giả), 读者 (độc giả).","ex":"这本书的作者是一位年轻人。","exPy":"Zhè běn shū de zuòzhě shì yí wèi niánqīng rén.","exVi":"Tác giả quyển sách này là một người trẻ.","w":"这 本 书 的 作者 是 一 位 年轻 人。"},{"zh":"作用","py":"zuòyòng","vi":"tác dụng, vai trò","hv":"tác dụng","note":"Chính là \"tác dụng\" tiếng Việt: 作 (tác) + 用 (dụng, bài 57).","ex":"多锻炼对身体有很大的作用。","exPy":"Duō duànliàn duì shēntǐ yǒu hěn dà de zuòyòng.","exVi":"Tập luyện nhiều rất có tác dụng với sức khoẻ.","w":"多 锻炼 对 身体 有 很 大 的 作用。"},{"zh":"其他","py":"qítā","vi":"cái khác, những cái khác","hv":"kỳ tha","note":"其 = \"kỳ\" trong \"kỳ thực\", \"kỳ dư\". Dùng cho cả người lẫn vật, trang trọng hơn 别的.","ex":"除了他，其他人我都不认识。","exPy":"Chúle tā, qítā rén wǒ dōu bú rènshi.","exVi":"Ngoài anh ấy ra, những người khác tôi đều không quen.","w":"除了 他， 其他 人 我 都 不 认识。"}],"newChars":["久","声","哭","黄","河","环","境"],"outro":"很好！Xong bài 75."};
G.ROOMS["zh-l076"] = {"id":"zh-l076","lang":"zh","level":3,"no":76,"teacher":"wang","title":"HSK3 · Bài 76 · 口语常用词 Từ hay gặp khi nói chuyện","intro":["好啊，就这么定吧！","Bài 76: Nắm những từ nhỏ mà người bản xứ dùng liên tục — 一边…一边…, 还是, 其实. Bấm 1 · Học để bắt đầu."],"introPy":"Hǎo a, jiù zhème dìng ba!","gram":{"t":"一边 … 一边 … — vừa làm việc này vừa làm việc kia","b":"一边 + động từ 1 + 一边 + động từ 2","d":"Hai việc diễn ra CÙNG LÚC, cùng một người làm. Giống hệt \"vừa… vừa…\" tiếng Việt nên rất dễ nhớ. Nói tắt được thành 边…边….","ex":[["我一边吃饭一边看电视。","Tôi vừa ăn cơm vừa xem tivi.","Wǒ yìbiān chīfàn yìbiān kàn diànshì."],["别一边走路一边看手机。","Đừng vừa đi vừa xem điện thoại.","Bié yìbiān zǒulù yìbiān kàn shǒujī."]]},"grams":[{"t":"一边 … 一边 … — vừa làm việc này vừa làm việc kia","b":"一边 + động từ 1 + 一边 + động từ 2","d":"Hai việc diễn ra CÙNG LÚC, cùng một người làm. Giống hệt \"vừa… vừa…\" tiếng Việt nên rất dễ nhớ. Nói tắt được thành 边…边….","ex":[["我一边吃饭一边看电视。","Tôi vừa ăn cơm vừa xem tivi.","Wǒ yìbiān chīfàn yìbiān kàn diànshì."],["别一边走路一边看手机。","Đừng vừa đi vừa xem điện thoại.","Bié yìbiān zǒulù yìbiān kàn shǒujī."]]},{"t":"还是 dùng để HỎI, 或者 dùng để KỂ","b":"A 还是 B？(hỏi) · A 或者 B (kể)","d":"Nhắc lại bài 55 vì đây là lỗi rất dai dẳng. Trong câu hỏi lựa chọn luôn dùng 还是. 还是 còn nghĩa \"vẫn nên\" khi đưa lời khuyên sau khi cân nhắc: 你还是早点儿去吧.","ex":[["我们今天去还是明天去？","Chúng ta đi hôm nay hay mai?","Wǒmen jīntiān qù háishi míngtiān qù?"],["外面下雨，你还是带伞吧。","Ngoài trời mưa, bạn vẫn nên mang ô đi.","Wàimiàn xiàyǔ, nǐ háishi dài sǎn ba."]]},{"t":"像 — ba cách dùng","b":"A 像 B · 好像 · 像…一样","d":"他像他爸爸 (giống bố). 好像下雨了 (hình như mưa rồi — phỏng đoán). 像我一样 (giống như tôi). Ba cách này phủ gần hết nhu cầu so sánh hằng ngày.","ex":[["你妹妹很像你。","Em gái bạn rất giống bạn.","Nǐ mèimei hěn xiàng nǐ."],["外面好像下雪了。","Hình như bên ngoài có tuyết rồi.","Wàimiàn hǎoxiàng xià xuě le."]]}],"items":[{"zh":"啊","py":"a","vi":"(thán từ cuối câu)","hv":"a","note":"Bộ 口 (miệng). Đặt cuối câu làm giọng mềm và thân mật hơn: 好啊！是啊！Không dịch được sang tiếng Việt, chỉ cảm nhận.","ex":"好啊，就这么定吧！","exPy":"Hǎo a, jiù zhème dìng ba!","exVi":"Được đấy, cứ quyết vậy đi!","w":"好 啊， 就 这么 定 吧！"},{"zh":"其实","py":"qíshí","vi":"thật ra, kỳ thực","hv":"kỳ thực","note":"Chính là \"kỳ thực\" tiếng Việt. Dùng để nói ra điều trái với vẻ ngoài hoặc trái với điều người ta tưởng.","ex":"其实这个问题很简单。","exPy":"Qíshí zhège wèntí hěn jiǎndān.","exVi":"Thật ra vấn đề này rất đơn giản.","w":"其实 这个 问题 很 简单。"},{"zh":"先","py":"xiān","vi":"trước, trước hết","hv":"tiên","note":"Chính là \"tiên\" tiếng Việt (\"tiên phong\", \"ưu tiên\"). Đã gặp trong 先生 (bài 5). Hay đi với 然后.","ex":"我们先吃饭，然后去看电影。","exPy":"Wǒmen xiān chīfàn, ránhòu qù kàn diànyǐng.","exVi":"Chúng ta ăn cơm trước, rồi đi xem phim.","w":"我们 先 吃 饭， 然后 去 看 电影。"},{"zh":"一般","py":"yìbān","vi":"thông thường; bình thường","hv":"nhất bàn","note":"Hai nghĩa: \"thường thì\" (một phó từ chỉ thói quen) và \"bình thường thôi\" (đánh giá mức trung bình, hơi chê).","ex":"周末我一般在家休息。","exPy":"Zhōumò wǒ yìbān zài jiā xiūxi.","exVi":"Cuối tuần tôi thường ở nhà nghỉ.","w":"周末 我 一般 在 家 休息。"},{"zh":"一边","py":"yìbiān","vi":"một bên; vừa… vừa…","hv":"nhất biên","note":"Dùng cặp 一边…一边… để nói hai việc làm CÙNG LÚC. Giống hệt \"vừa… vừa…\" tiếng Việt.","ex":"他一边听音乐一边做作业。","exPy":"Tā yìbiān tīng yīnyuè yìbiān zuò zuòyè.","exVi":"Cậu ấy vừa nghe nhạc vừa làm bài.","w":"他 一边 听 音乐 一边 做 作业。"},{"zh":"像","py":"xiàng","vi":"giống, trông như","hv":"tượng","note":"Bộ 亻 (người) + 象 (con voi, hình tượng). Tiếng Việt: \"hình tượng\", \"tượng trưng\".","ex":"这个孩子长得很像他妈妈。","exPy":"Zhège háizi zhǎng de hěn xiàng tā māma.","exVi":"Đứa bé này trông rất giống mẹ.","w":"这个 孩子 长 得 很 像 他 妈妈。"},{"zh":"只","py":"zhǐ","vi":"chỉ, chỉ có","hv":"chỉ","note":"Chính là \"chỉ\" tiếng Việt. Đứng trước động từ. Chú ý: đọc zhī thì lại là lượng từ cho động vật (一只猫).","ex":"我只想休息一会儿。","exPy":"Wǒ zhǐ xiǎng xiūxi yíhuìr.","exVi":"Tôi chỉ muốn nghỉ một lát.","w":"我 只 想 休息 一会儿。"},{"zh":"还是","py":"háishi","vi":"hay là (trong câu hỏi); vẫn nên","hv":"hoàn thị","note":"Dùng để hỏi lựa chọn — khác 或者 chỉ dùng trong câu kể (bài 55). Nghĩa thứ hai: \"vẫn nên\" khi khuyên.","ex":"你要红色的还是蓝色的？","exPy":"Nǐ yào hóngsè de háishi lánsè de?","exVi":"Bạn lấy màu đỏ hay màu xanh?","w":"你 要 红色 的 还是 蓝 色 的？"},{"zh":"关","py":"guān","vi":"đóng, tắt","hv":"quan","note":"Trái nghĩa với 开 (bài 12). 关门 đóng cửa, 关灯 tắt đèn, 关手机 tắt điện thoại. Cùng chữ với 关心, 关系 (bài 51).","ex":"出门前请关好门窗和灯。","exPy":"Chūmén qián qǐng guān hǎo ménchuāng hé dēng.","exVi":"Trước khi ra ngoài xin đóng kỹ cửa và tắt đèn.","w":"出门 前 请 关 好 门 窗 和 灯。"},{"zh":"鞋","py":"xié","vi":"giày, dép","hv":"hài","note":"Bộ 革 (da thuộc) bên trái — giày làm bằng da. Tiếng Việt: \"hài\" trong \"hài nhi\"? Không — là \"hài\" trong \"đôi hài\" của truyện cổ tích. Lượng từ là 双.","ex":"我想买一双运动鞋。","exPy":"Wǒ xiǎng mǎi yì shuāng yùndòng xié.","exVi":"Tôi muốn mua một đôi giày thể thao.","w":"我 想 买 一 双 运动 鞋。"}],"newChars":["啊","实","般","鞋"],"outro":"很好！Xong bài 76."};
G.ROOMS["zh-l077"] = {"id":"zh-l077","lang":"zh","level":3,"no":77,"teacher":"wang","title":"HSK3 · Bài 77 · 生活中的事 Chuyện đời sống","intro":["老师把答案写在黑板上了。","Bài 77: Bài cuối HSK 3: giấy tờ, cưới hỏi, và cặp phó từ 才 / 就 khép lại toàn bộ giáo trình. Bấm 1 · Học để bắt đầu."],"introPy":"Lǎoshī bǎ dá'àn xiě zài hēibǎn shàng le.","gram":{"t":"才 và 就 — cặp phó từ tinh tế nhất tiếng Trung","b":"就 = sớm hơn mong đợi · 才 = muộn hơn mong đợi","d":"Cùng một sự việc, hai thái độ khác hẳn. 他七点就来了 (mới bảy giờ anh ấy ĐÃ đến — sớm thế). 他九点才来 (mãi chín giờ anh ấy MỚI đến — muộn quá). Câu có 才 thường KHÔNG dùng 了 ở cuối. Nắm được cặp này là tiếng Trung của bạn có sắc thái như người bản xứ.","ex":[["我五点就起床了。","Mới năm giờ tôi đã dậy rồi.","Wǒ wǔ diǎn jiù qǐchuáng le."],["我十点才起床。","Mãi mười giờ tôi mới dậy.","Wǒ shí diǎn cái qǐchuáng."],["学了三年，他才学会。","Học ba năm cậu ấy mới học được.","Xué le sān nián, tā cái xué huì."]]},"grams":[{"t":"才 và 就 — cặp phó từ tinh tế nhất tiếng Trung","b":"就 = sớm hơn mong đợi · 才 = muộn hơn mong đợi","d":"Cùng một sự việc, hai thái độ khác hẳn. 他七点就来了 (mới bảy giờ anh ấy ĐÃ đến — sớm thế). 他九点才来 (mãi chín giờ anh ấy MỚI đến — muộn quá). Câu có 才 thường KHÔNG dùng 了 ở cuối. Nắm được cặp này là tiếng Trung của bạn có sắc thái như người bản xứ.","ex":[["我五点就起床了。","Mới năm giờ tôi đã dậy rồi.","Wǒ wǔ diǎn jiù qǐchuáng le."],["我十点才起床。","Mãi mười giờ tôi mới dậy.","Wǒ shí diǎn cái qǐchuáng."],["学了三年，他才学会。","Học ba năm cậu ấy mới học được.","Xué le sān nián, tā cái xué huì."]]},{"t":"Câu cảm thán với 多么 … 啊！","b":"多么 + tính từ + 啊！","d":"Mẫu cảm thán trang trọng, hay gặp trong văn viết và bài hát. Trong khẩu ngữ thường nói tắt: 多好啊！Giống \"…biết bao!\" của tiếng Việt.","ex":[["今天的天气多么好啊！","Thời tiết hôm nay đẹp biết bao!","Jīntiān de tiānqì duōme hǎo a!"],["他画得多好啊！","Cậu ấy vẽ đẹp thật!","Tā huà de duō hǎo a!"]]},{"t":"结婚 là động từ ly hợp","b":"跟 + người + 结婚","d":"Không nói 结婚他. Phải nói 跟他结婚 (cưới anh ấy). Cùng nhóm với 见面, 帮忙, 请假, 聊天 — đến bài cuối này bạn đã gặp hơn mười động từ ly hợp.","ex":[["她跟一个中国人结婚了。","Cô ấy lấy một người Trung Quốc.","Tā gēn yí ge Zhōngguó rén jiéhūn le."],["他们结婚三年了。","Họ cưới nhau ba năm rồi.","Tāmen jiéhūn sān nián le."]]},{"t":"Chúc mừng bạn đã học hết HSK 3","b":"600 từ · 60 bài · hơn 600 chữ Hán","d":"Với vốn này bạn đọc hiểu được biển báo, thực đơn, tin nhắn đơn giản và nói chuyện hằng ngày về gia đình, công việc, sức khoẻ, du lịch. Đừng dừng lại: hãy tiếp tục ôn bằng thẻ viết tay mỗi ngày, vì chữ Hán quên rất nhanh nếu không luyện bút.","ex":[["学了三年，我才明白学习是一辈子的事。","Học ba năm tôi mới hiểu học là việc cả đời.","Xué le sān nián, wǒ cái míngbai xuéxí shì yí bèizi de shì."],["只要每天练习，就一定会进步。","Chỉ cần ngày nào cũng luyện, nhất định sẽ tiến bộ.","Zhǐyào měi tiān liànxí, jiù yídìng huì jìnbù."]]}],"items":[{"zh":"黑板","py":"hēibǎn","vi":"bảng đen","hv":"hắc bản","note":"黑 (đen, bài 21) + 板 (tấm ván, bộ 木). Tiếng Việt: \"hắc\" trong \"hắc ám\", \"bản\" trong \"bảng biểu\".","ex":"老师把答案写在黑板上了。","exPy":"Lǎoshī bǎ dá'àn xiě zài hēibǎn shàng le.","exVi":"Thầy viết đáp án lên bảng rồi.","w":"老师 把 答案 写 在 黑板 上 了。"},{"zh":"护照","py":"hùzhào","vi":"hộ chiếu","hv":"hộ chiếu","note":"Chính là \"hộ chiếu\" tiếng Việt: 护 (bảo hộ) + 照 (giấy chứng). Không sai một ly.","ex":"别忘了带护照和机票。","exPy":"Bié wàng le dài hùzhào hé jīpiào.","exVi":"Đừng quên mang hộ chiếu và vé máy bay.","w":"别 忘 了 带 护照 和 机票。"},{"zh":"画","py":"huà","vi":"vẽ; bức tranh","hv":"hoạ","note":"Chính là \"hoạ\" tiếng Việt (\"hội hoạ\", \"hoạ sĩ\"). Có bộ 田 (ruộng) — vốn là vẽ ranh giới thửa ruộng.","ex":"我妹妹很喜欢画画儿。","exPy":"Wǒ mèimei hěn xǐhuan huà huàr.","exVi":"Em gái tôi rất thích vẽ tranh.","w":"我 妹妹 很 喜欢 画 画 儿。"},{"zh":"坏","py":"huài","vi":"hỏng; xấu, ác","hv":"hoại","note":"Chính là \"hoại\" tiếng Việt (\"phá hoại\", \"hư hoại\"). Trái nghĩa với 好. Hai nghĩa: đồ hỏng và người xấu.","ex":"电梯坏了，我们走楼梯吧。","exPy":"Diàntī huài le, wǒmen zǒu lóutī ba.","exVi":"Thang máy hỏng rồi, ta đi thang bộ nhé.","w":"电梯 坏 了， 我们 走 楼梯 吧。"},{"zh":"结婚","py":"jiéhūn","vi":"kết hôn, cưới","hv":"kết hôn","note":"Chính là \"kết hôn\" tiếng Việt: 结 (kết, bài 50 trong 结束) + 婚 (hôn, có bộ 女). Là động từ ly hợp — cưới AI thì dùng 跟…结婚.","ex":"他们下个月就要结婚了。","exPy":"Tāmen xià ge yuè jiù yào jiéhūn le.","exVi":"Tháng sau họ sẽ cưới rồi.","w":"他们 下 个 月 就 要 结婚 了。"},{"zh":"为","py":"wèi","vi":"vì, cho","hv":"vị","note":"Ngắn gọn hơn 为了 (bài 55). 为你高兴 = mừng cho bạn. Đọc wéi (thanh 2) thì lại nghĩa là \"làm, là\".","ex":"我为你的成绩感到高兴。","exPy":"Wǒ wèi nǐ de chéngjì gǎndào gāoxìng.","exVi":"Tôi mừng cho kết quả của bạn.","w":"我 为 你 的 成绩 感到 高兴。"},{"zh":"多么","py":"duōme","vi":"biết bao, thật là","hv":"đa ma","note":"Dùng trong câu CẢM THÁN, thường kèm 啊 ở cuối: 多么漂亮啊！Nói tắt được thành 多.","ex":"这个地方多么安静啊！","exPy":"Zhège dìfang duōme ānjìng a!","exVi":"Chỗ này yên tĩnh biết bao!","w":"这个 地方 多么 安静 啊！"},{"zh":"放","py":"fàng","vi":"đặt, để; thả; nghỉ","hv":"phóng","note":"Chính là \"phóng\" tiếng Việt (\"phóng thích\", \"giải phóng\"). Đã gặp trong 放心 (bài 34). 放假 = nghỉ lễ.","ex":"请把行李箱放在这儿。","exPy":"Qǐng bǎ xínglixiāng fàng zài zhèr.","exVi":"Xin để va li ở đây.","w":"请 把 行李箱 放 在 这儿。"},{"zh":"安静","py":"ānjìng","vi":"yên tĩnh","hv":"an tĩnh","note":"Chính là \"an tĩnh\" tiếng Việt (nay hay nói \"yên tĩnh\"): 安 (an toàn, bộ 宀 mái nhà + 女) + 静 (tĩnh lặng).","ex":"图书馆里很安静。","exPy":"Túshūguǎn lǐ hěn ānjìng.","exVi":"Trong thư viện rất yên tĩnh.","w":"图书馆 里 很 安静。"},{"zh":"才","py":"cái","vi":"mới (muộn hơn mong đợi)","hv":"tài","note":"Trái ngược hoàn toàn với 就 (bài 18). 就 = sớm hơn mong đợi, 才 = muộn hơn mong đợi. Cặp này là đỉnh cao sắc thái tiếng Trung.","ex":"我等了一个小时，他才来。","exPy":"Wǒ děng le yí ge xiǎoshí, tā cái lái.","exVi":"Tôi đợi một tiếng, anh ấy mới đến.","w":"我 等 了 一 个 小时， 他 才 来。"}],"newChars":["板","护","画","坏","婚","安","静"],"outro":"很好！Xong bài 77."};
G.ROOMS["zh-l078"] = {"id":"zh-l078","lang":"zh","level":3,"no":78,"teacher":"wang","title":"HSK3 · Bài 78 · 四季 Bốn mùa và thời tiết","intro":["越南南方没有冬天。","Bài 78: Gọi tên bốn mùa, nói về gió, băng, biển, và mùa nào thích nhất. Bấm 1 · Học để bắt đầu."],"introPy":"Yuènán nánfāng méiyǒu dōngtiān.","gram":{"t":"刮风 / 下雨 / 下雪","b":"刮 + 风 · 下 + 雨 / 雪","d":"Thời tiết trong tiếng Trung dùng động từ cố định: gió thì 刮, mưa tuyết thì 下.","ex":[["明天可能会刮风。","Mai có thể có gió.","Míngtiān kěnéng huì guā fēng."],["冬天北京常常下雪。","Mùa đông Bắc Kinh hay có tuyết.","Dōngtiān Běijīng chángcháng xià xuě."]]},"grams":[{"t":"刮风 / 下雨 / 下雪","b":"刮 + 风 · 下 + 雨 / 雪","d":"Thời tiết trong tiếng Trung dùng động từ cố định: gió thì 刮, mưa tuyết thì 下.","ex":[["明天可能会刮风。","Mai có thể có gió.","Míngtiān kěnéng huì guā fēng."],["冬天北京常常下雪。","Mùa đông Bắc Kinh hay có tuyết.","Dōngtiān Běijīng chángcháng xià xuě."]]},{"t":"最 + tính từ / động từ","b":"最 + 冷 / 美 / 喜欢","d":"最 là \"nhất\", đứng trước tính từ hoặc động từ tâm lý.","ex":[["你最喜欢哪个季节？","Bạn thích mùa nào nhất?","Nǐ zuì xǐhuan nǎge jìjié?"],["一月最冷。","Tháng một lạnh nhất.","Yī yuè zuì lěng."]]}],"items":[{"zh":"春天","py":"chūntiān","vi":"mùa xuân","hv":"xuân thiên","note":"春 = \"xuân\" trong \"thanh xuân\", \"Tết xuân\".","ex":"春天天气不冷也不热。","exPy":"Chūntiān tiānqì bù lěng yě bú rè.","exVi":"Mùa xuân trời không lạnh cũng không nóng.","w":"春天 天气 不 冷 也 不 热。"},{"zh":"夏天","py":"xiàtiān","vi":"mùa hè","hv":"hạ thiên","note":"夏 = \"hạ\" trong \"mùa hạ\".","ex":"夏天我们常去海边。","exPy":"Xiàtiān wǒmen cháng qù hǎibiān.","exVi":"Mùa hè chúng tôi hay ra biển.","w":"夏天 我们 常 去 海 边。"},{"zh":"秋天","py":"qiūtiān","vi":"mùa thu","hv":"thu thiên","note":"秋 = \"thu\" trong \"Trung thu\".","ex":"北京的秋天最美。","exPy":"Běijīng de qiūtiān zuì měi.","exVi":"Mùa thu Bắc Kinh đẹp nhất.","w":"北京 的 秋天 最 美。"},{"zh":"冬天","py":"dōngtiān","vi":"mùa đông","hv":"đông thiên","note":"冬 = \"đông\" trong \"mùa đông\".","ex":"越南南方没有冬天。","exPy":"Yuènán nánfāng méiyǒu dōngtiān.","exVi":"Miền Nam Việt Nam không có mùa đông.","w":"越 南 南方 没有 冬天。"},{"zh":"四季","py":"sìjì","vi":"bốn mùa","hv":"tứ quý","note":"Chính là \"tứ quý\" trong \"tứ quý xuân hạ thu đông\".","ex":"这里四季都很暖和。","exPy":"Zhèlǐ sìjì dōu hěn nuǎnhuo.","exVi":"Ở đây bốn mùa đều ấm áp.","w":"这里 四季 都 很 暖和。"},{"zh":"季","py":"jì","vi":"mùa; quý","hv":"quý","note":"\"Quý\" trong \"quý một\", \"quý hai\" của năm. 季节 là mùa.","ex":"一年有四个季节。","exPy":"Yì nián yǒu sì ge jìjié.","exVi":"Một năm có bốn mùa.","w":"一 年 有 四 个 季节。"},{"zh":"风","py":"fēng","vi":"gió","hv":"phong","note":"\"Phong\" trong \"phong ba\", \"phong cảnh\".","ex":"风太大了，我们回家吧。","exPy":"Fēng tài dà le, wǒmen huí jiā ba.","exVi":"Gió to quá, mình về nhà thôi.","w":"风 太 大 了， 我们 回 家 吧。"},{"zh":"刮","py":"guā","vi":"thổi (gió); cạo","hv":"quát","note":"Gió thổi dùng 刮风, không dùng 吹.","ex":"外面在刮大风。","exPy":"Wàimian zài guā dà fēng.","exVi":"Bên ngoài đang có gió to.","w":"外面 在 刮 大 风。"},{"zh":"冰","py":"bīng","vi":"băng, đá lạnh","hv":"băng","note":"Chính là \"băng\" trong \"băng tuyết\". Đồ uống thêm đá: 加冰.","ex":"我要一杯冰水。","exPy":"Wǒ yào yì bēi bīng shuǐ.","exVi":"Cho tôi một cốc nước đá.","w":"我 要 一 杯 冰 水。"},{"zh":"海","py":"hǎi","vi":"biển","hv":"hải","note":"\"Hải\" trong \"hải quân\", \"hải sản\". Bộ 氵 (nước).","ex":"我们去海边玩儿吧。","exPy":"Wǒmen qù hǎibiān wánr ba.","exVi":"Mình ra biển chơi nhé.","w":"我们 去 海 边 玩 儿 吧。"}],"newChars":["海"],"outro":"很好！Xong bài 78."};
G.ROOMS["zh-l079"] = {"id":"zh-l079","lang":"zh","level":3,"no":79,"teacher":"wang","title":"HSK3 · Bài 79 · 东南西北 Phương hướng","intro":["河内在越南的北方。","Bài 79: Nói các hướng Đông Tây Nam Bắc, phương Đông, phương Tây, và trên, dưới, giữa. Bấm 1 · Học để bắt đầu."],"introPy":"Hénèi zài Yuènán de běifāng.","gram":{"t":"Thứ tự phương hướng","b":"东南 · 西北 · 东北 · 西南","d":"Giống tiếng Việt: Đông / Tây đứng trước Nam / Bắc. Tiếng Anh thì ngược lại (south-east).","ex":[["机场在城市的东南。","Sân bay ở phía đông nam thành phố.","Jīchǎng zài chéngshì de dōngnán."],["风从西北刮来。","Gió thổi từ hướng tây bắc.","Fēng cóng xīběi guā lái."]]},"grams":[{"t":"Thứ tự phương hướng","b":"东南 · 西北 · 东北 · 西南","d":"Giống tiếng Việt: Đông / Tây đứng trước Nam / Bắc. Tiếng Anh thì ngược lại (south-east).","ex":[["机场在城市的东南。","Sân bay ở phía đông nam thành phố.","Jīchǎng zài chéngshì de dōngnán."],["风从西北刮来。","Gió thổi từ hướng tây bắc.","Fēng cóng xīběi guā lái."]]},{"t":"在…中 / 在…里","b":"在 + nhóm + 中 · 在 + nơi + 里","d":"中 dùng cho nhóm người hay phạm vi trừu tượng, 里 cho không gian.","ex":[["在这些书中，我最喜欢这本。","Trong những cuốn sách này, tôi thích cuốn này nhất.","Zài zhèxiē shū zhōng, wǒ zuì xǐhuan zhè běn."],["在学习中，他帮了我很多。","Trong việc học, anh ấy giúp tôi rất nhiều.","Zài xuéxí zhōng, tā bāng le wǒ hěn duō."]]}],"items":[{"zh":"北","py":"běi","vi":"phía bắc","hv":"bắc","note":"\"Bắc\" trong \"miền Bắc\", \"Bắc Kinh\". Phía bắc là 北边 hoặc 北方.","ex":"河内在越南的北方。","exPy":"Hénèi zài Yuènán de běifāng.","exVi":"Hà Nội ở miền Bắc Việt Nam.","w":"河 内在 越 南 的 北方。"},{"zh":"南方","py":"nánfāng","vi":"miền nam, phương nam","hv":"nam phương","note":"南 = \"nam\" trong \"Việt Nam\".","ex":"你是北方人还是南方人？","exPy":"Nǐ shì běifāng rén háishi nánfāng rén?","exVi":"Bạn là người miền Bắc hay miền Nam?","w":"你 是 北方 人 还是 南方 人？"},{"zh":"东方","py":"dōngfāng","vi":"phương Đông","hv":"đông phương","note":"东 (đông) + 方 (phương).","ex":"东方和西方的文化很不一样。","exPy":"Dōngfāng hé xīfāng de wénhuà hěn bù yíyàng.","exVi":"Văn hoá phương Đông và phương Tây rất khác nhau.","w":"东方 和 西方 的 文化 很 不 一样。"},{"zh":"西方","py":"xīfāng","vi":"phương Tây","hv":"tây phương","note":"Cũng chỉ các nước Âu Mỹ: 西方国家.","ex":"很多西方人喜欢中国菜。","exPy":"Hěn duō xīfāng rén xǐhuan Zhōngguó cài.","exVi":"Nhiều người phương Tây thích món Trung Quốc.","w":"很 多 西方 人 喜欢 中国 菜。"},{"zh":"东北","py":"dōngběi","vi":"đông bắc","hv":"đông bắc","note":"Tiếng Trung nói \"đông bắc\", \"tây nam\" giống tiếng Việt. Riêng 东北 còn là tên vùng Đông Bắc Trung Quốc.","ex":"东北的冬天非常冷。","exPy":"Dōngběi de dōngtiān fēicháng lěng.","exVi":"Mùa đông vùng Đông Bắc cực kỳ lạnh.","w":"东北 的 冬天 非常 冷。"},{"zh":"东南","py":"dōngnán","vi":"đông nam","hv":"đông nam","note":"Đông Nam Á là 东南亚.","ex":"越南在东南亚。","exPy":"Yuènán zài Dōngnányà.","exVi":"Việt Nam ở Đông Nam Á.","w":"越 南 在 东南 亚。"},{"zh":"西北","py":"xīběi","vi":"tây bắc","hv":"tây bắc","note":"Vùng Tây Bắc Việt Nam cũng gọi là 西北.","ex":"中国的西北有很多山。","exPy":"Zhōngguó de xīběi yǒu hěn duō shān.","exVi":"Tây Bắc Trung Quốc có nhiều núi.","w":"中国 的 西北 有 很 多 山。"},{"zh":"西南","py":"xīnán","vi":"tây nam","hv":"tây nam","note":"Ghép như 西 + 南.","ex":"云南在中国的西南。","exPy":"Yúnnán zài Zhōngguó de xīnán.","exVi":"Vân Nam ở phía tây nam Trung Quốc.","w":"云 南 在 中国 的 西南。"},{"zh":"中","py":"zhōng","vi":"giữa, trong","hv":"trung","note":"\"Trung\" trong \"trung tâm\", \"Trung Quốc\". 在…中 là \"trong…\".","ex":"在我们班中，他最高。","exPy":"Zài wǒmen bān zhōng, tā zuì gāo.","exVi":"Trong lớp chúng tôi, cậu ấy cao nhất.","w":"在 我们 班 中， 他 最 高。"},{"zh":"以上","py":"yǐshàng","vi":"trở lên, trên","hv":"dĩ thượng","note":"Số + 以上: 十八岁以上 (từ 18 tuổi trở lên).","ex":"一百人以上参加了这个活动。","exPy":"Yìbǎi rén yǐshàng cānjiā le zhège huódòng.","exVi":"Hơn một trăm người tham gia hoạt động này.","w":"一 百 人 以上 参加 了 这个 活动。"}],"newChars":[],"outro":"很好！Xong bài 79."};
G.ROOMS["zh-l080"] = {"id":"zh-l080","lang":"zh","level":3,"no":80,"teacher":"wang","title":"HSK3 · Bài 80 · 过马路 Trên phố","intro":["红灯停，绿灯行。","Bài 80: Nói về đường phố, ngã tư, đèn giao thông, ô tô, tàu cao tốc, thành phố, khu dân cư. Bấm 1 · Học để bắt đầu."],"introPy":"Hóng dēng tíng, lǜ dēng xíng.","gram":{"t":"Lượng từ 条 cho vật dài","b":"一条街 · 一条马路 · 一条河","d":"Đường, sông, phố, cá, quần… đều đếm bằng 条.","ex":[["这条马路很宽。","Con đường này rất rộng.","Zhè tiáo mǎlù hěn kuān."],["我家前面有一条小河。","Trước nhà tôi có một con sông nhỏ.","Wǒ jiā qiánmian yǒu yì tiáo xiǎo hé."]]},"grams":[{"t":"Lượng từ 条 cho vật dài","b":"一条街 · 一条马路 · 一条河","d":"Đường, sông, phố, cá, quần… đều đếm bằng 条.","ex":[["这条马路很宽。","Con đường này rất rộng.","Zhè tiáo mǎlù hěn kuān."],["我家前面有一条小河。","Trước nhà tôi có một con sông nhỏ.","Wǒ jiā qiánmian yǒu yì tiáo xiǎo hé."]]},{"t":"从 A 到 B","b":"从 + nơi / giờ + 到 + nơi / giờ","d":"Diễn tả khoảng cách hoặc khoảng thời gian.","ex":[["从我家到学校要二十分钟。","Từ nhà tôi đến trường mất hai mươi phút.","Cóng wǒ jiā dào xuéxiào yào èrshí fēnzhōng."],["我从早上到晚上都很忙。","Tôi bận từ sáng đến tối.","Wǒ cóng zǎoshang dào wǎnshang dōu hěn máng."]]}],"items":[{"zh":"街","py":"jiē","vi":"phố, đường phố","hv":"nhai","note":"Ra phố mua sắm là 逛街.","ex":"这个城市的街上人很多。","exPy":"Zhège chéngshì de jiē shang rén hěn duō.","exVi":"Phố xá thành phố này rất đông người.","w":"这个 城市 的 街 上 人 很 多。"},{"zh":"马路","py":"mǎlù","vi":"đường cái, lòng đường","hv":"mã lộ","note":"Nghĩa đen \"đường cho ngựa\". Qua đường là 过马路.","ex":"过马路要小心。","exPy":"Guò mǎlù yào xiǎoxīn.","exVi":"Qua đường phải cẩn thận.","w":"过 马路 要 小心。"},{"zh":"路口","py":"lùkǒu","vi":"ngã tư, giao lộ","hv":"lộ khẩu","note":"路 + 口 (miệng, cửa). Ngã tư là 十字路口.","ex":"在前面的路口往右拐。","exPy":"Zài qiánmian de lùkǒu wǎng yòu guǎi.","exVi":"Đến ngã tư phía trước thì rẽ phải.","w":"在 前面 的 路口 往 右 拐。"},{"zh":"路边","py":"lùbiān","vi":"lề đường, ven đường","hv":"lộ biên","note":"路 + 边.","ex":"他把车停在路边。","exPy":"Tā bǎ chē tíng zài lùbiān.","exVi":"Anh ấy đỗ xe ở lề đường.","w":"他 把 车 停 在 路边。"},{"zh":"红绿灯","py":"hóng-lǜdēng","vi":"đèn giao thông","hv":"hồng lục đăng","note":"Nghĩa đen \"đèn đỏ xanh\". 灯 = \"đăng\" trong \"hải đăng\".","ex":"看见红绿灯要停下来。","exPy":"Kànjiàn hóng-lǜdēng yào tíng xiàlai.","exVi":"Thấy đèn giao thông phải dừng lại.","w":"看见 红绿灯 要 停 下来。"},{"zh":"汽车","py":"qìchē","vi":"ô tô","hv":"khí xa","note":"汽 (hơi) + 车. Chú ý: 汽车 là ô tô, không phải \"tàu hoả\".","ex":"他买了一辆新汽车。","exPy":"Tā mǎi le yí liàng xīn qìchē.","exVi":"Anh ấy mua một chiếc ô tô mới.","w":"他 买 了 一 辆 新 汽车。"},{"zh":"高铁","py":"gāotiě","vi":"tàu cao tốc","hv":"cao thiết","note":"Viết tắt của 高速铁路 (đường sắt cao tốc).","ex":"坐高铁比坐飞机方便。","exPy":"Zuò gāotiě bǐ zuò fēijī fāngbiàn.","exVi":"Đi tàu cao tốc tiện hơn đi máy bay.","w":"坐 高铁 比 坐 飞机 方便。"},{"zh":"市","py":"shì","vi":"thành phố; chợ","hv":"thị","note":"\"Thị\" trong \"thành thị\", \"thị trường\". Hà Nội là 河内市.","ex":"我住在胡志明市。","exPy":"Wǒ zhù zài Húzhìmíng Shì.","exVi":"Tôi sống ở Thành phố Hồ Chí Minh.","w":"我 住 在 胡 志 明 市。"},{"zh":"小区","py":"xiǎoqū","vi":"khu dân cư, khu chung cư","hv":"tiểu khu","note":"小 + 区 (khu vực).","ex":"我们小区里有一个公园。","exPy":"Wǒmen xiǎoqū lǐ yǒu yí ge gōngyuán.","exVi":"Trong khu nhà chúng tôi có một công viên.","w":"我们 小区 里 有 一 个 公园。"},{"zh":"外地","py":"wàidì","vi":"nơi khác, tỉnh khác","hv":"ngoại địa","note":"Người từ tỉnh khác đến là 外地人.","ex":"很多外地人来这里工作。","exPy":"Hěn duō wàidì rén lái zhèlǐ gōngzuò.","exVi":"Nhiều người nơi khác đến đây làm việc.","w":"很 多 外地 人 来 这里 工作。"}],"newChars":["区"],"outro":"很好！Xong bài 80."};
G.ROOMS["zh-l081"] = {"id":"zh-l081","lang":"zh","level":3,"no":81,"teacher":"wang","title":"HSK3 · Bài 81 · 动物园 Thiên nhiên và động vật","intro":["山上的风景很美。","Bài 81: Nói về núi, sông, bãi cỏ, vườn hoa, hoa nở, và các con vật quen thuộc. Bấm 1 · Học để bắt đầu."],"introPy":"Shān shang de fēngjǐng hěn měi.","gram":{"t":"Lượng từ cho động vật","b":"一头牛 · 一只羊 / 鸡 / 熊猫 · 一条鱼","d":"Bò, lợn to dùng 头; gà, chim, mèo, phần lớn con vật dùng 只; cá và rắn dùng 条.","ex":[["那只鸡在草地上走。","Con gà kia đi trên bãi cỏ.","Nà zhī jī zài cǎodì shang zǒu."],["河里有一条大鱼。","Dưới sông có một con cá to.","Hé lǐ yǒu yì tiáo dà yú."]]},"grams":[{"t":"Lượng từ cho động vật","b":"一头牛 · 一只羊 / 鸡 / 熊猫 · 一条鱼","d":"Bò, lợn to dùng 头; gà, chim, mèo, phần lớn con vật dùng 只; cá và rắn dùng 条.","ex":[["那只鸡在草地上走。","Con gà kia đi trên bãi cỏ.","Nà zhī jī zài cǎodì shang zǒu."],["河里有一条大鱼。","Dưới sông có một con cá to.","Hé lǐ yǒu yì tiáo dà yú."]]},{"t":"带 + người + 去 + nơi","b":"带孩子去动物园","d":"Dẫn ai đi đâu: 带 + người + 去 + nơi chốn.","ex":[["爸爸带我去爬山。","Bố dẫn tôi đi leo núi.","Bàba dài wǒ qù pá shān."],["你可以带我去花园看看吗？","Bạn dẫn tôi ra vườn hoa xem được không?","Nǐ kěyǐ dài wǒ qù huāyuán kànkan ma?"]]}],"items":[{"zh":"山","py":"shān","vi":"núi","hv":"sơn","note":"Chữ tượng hình: ba đỉnh núi. \"Sơn\" trong \"giang sơn\".","ex":"山上的风景很美。","exPy":"Shān shang de fēngjǐng hěn měi.","exVi":"Phong cảnh trên núi rất đẹp.","w":"山 上 的 风景 很 美。"},{"zh":"河","py":"hé","vi":"sông","hv":"hà","note":"\"Hà\" trong \"sơn hà\", \"Hà Nội\" (thành phố trong sông).","ex":"小时候我常在河边玩儿。","exPy":"Xiǎoshíhou wǒ cháng zài hébiān wánr.","exVi":"Hồi nhỏ tôi hay chơi ở bờ sông.","w":"小时候 我 常 在 河 边 玩 儿。"},{"zh":"草地","py":"cǎodì","vi":"bãi cỏ","hv":"thảo địa","note":"草 = \"thảo\" trong \"thảo nguyên\".","ex":"孩子们在草地上玩儿。","exPy":"Háizimen zài cǎodì shang wánr.","exVi":"Bọn trẻ chơi trên bãi cỏ.","w":"孩子 们 在 草地 上 玩 儿。"},{"zh":"花园","py":"huāyuán","vi":"vườn hoa","hv":"hoa viên","note":"Chính là \"hoa viên\".","ex":"春天花园里的花都开了。","exPy":"Chūntiān huāyuán lǐ de huā dōu kāi le.","exVi":"Mùa xuân hoa trong vườn nở hết rồi.","w":"春天 花园 里 的 花 都 开 了。"},{"zh":"开花","py":"kāihuā","vi":"nở hoa","hv":"khai hoa","note":"开 (mở) + 花.","ex":"春天到了，树都开花了。","exPy":"Chūntiān dào le, shù dōu kāihuā le.","exVi":"Mùa xuân đến, cây đều nở hoa.","w":"春天 到 了， 树 都 开花 了。"},{"zh":"牛","py":"niú","vi":"con bò, con trâu","hv":"ngưu","note":"\"Ngưu\" trong \"Ngưu Lang\". Thịt bò là 牛肉, sữa bò là 牛奶.","ex":"农民家里有两头牛。","exPy":"Nóngmín jiā lǐ yǒu liǎng tóu niú.","exVi":"Nhà nông dân có hai con bò.","w":"农民 家 里 有 两 头 牛。"},{"zh":"羊","py":"yáng","vi":"con dê, con cừu","hv":"dương","note":"\"Dương\" trong \"sơn dương\".","ex":"草地上有很多羊。","exPy":"Cǎodì shang yǒu hěn duō yáng.","exVi":"Trên bãi cỏ có nhiều cừu.","w":"草地 上 有 很 多 羊。"},{"zh":"鸡","py":"jī","vi":"con gà","hv":"kê","note":"\"Kê\" trong \"kê gia\". Thịt gà là 鸡肉, trứng gà là 鸡蛋.","ex":"我奶奶养了很多鸡。","exPy":"Wǒ nǎinai yǎng le hěn duō jī.","exVi":"Bà tôi nuôi nhiều gà.","w":"我 奶奶 养 了 很 多 鸡。"},{"zh":"大熊猫","py":"dàxióngmāo","vi":"gấu trúc lớn","hv":"đại hùng miêu","note":"Nghĩa đen \"con mèo gấu lớn\". Biểu tượng của Trung Quốc.","ex":"动物园里有大熊猫吗？","exPy":"Dòngwùyuán lǐ yǒu dàxióngmāo ma?","exVi":"Trong sở thú có gấu trúc không?","w":"动物园 里 有 大熊猫 吗？"},{"zh":"动物园","py":"dòngwùyuán","vi":"vườn thú","hv":"động vật viên","note":"动物 (động vật) + 园 (vườn).","ex":"我们带孩子去动物园吧。","exPy":"Wǒmen dài háizi qù dòngwùyuán ba.","exVi":"Mình dẫn con đi sở thú nhé.","w":"我们 带 孩子 去 动物园 吧。"}],"newChars":[],"outro":"很好！Xong bài 81."};
G.ROOMS["zh-l082"] = {"id":"zh-l082","lang":"zh","level":3,"no":82,"teacher":"wang","title":"HSK3 · Bài 82 · 男人和女人 Người quanh ta","intro":["我爱人在医院工作。","Bài 82: Gọi các nhóm người: vợ chồng, chị em, người lớn, người già, nam, nữ, bạn học nam nữ. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ àiren zài yīyuàn gōngzuò.","gram":{"t":"一对 + đôi","b":"一对夫妻 · 一对姐妹","d":"对 là lượng từ cho một cặp người hoặc vật đi đôi.","ex":[["他们是一对好朋友。","Họ là một đôi bạn thân.","Tāmen shì yí duì hǎo péngyou."],["我买了一对耳环。","Tôi mua một đôi bông tai.","Wǒ mǎi le yí duì ěrhuán."]]},"grams":[{"t":"一对 + đôi","b":"一对夫妻 · 一对姐妹","d":"对 là lượng từ cho một cặp người hoặc vật đi đôi.","ex":[["他们是一对好朋友。","Họ là một đôi bạn thân.","Tāmen shì yí duì hǎo péngyou."],["我买了一对耳环。","Tôi mua một đôi bông tai.","Wǒ mǎi le yí duì ěrhuán."]]},{"t":"给 + người + động từ","b":"给老人让座 · 给妈妈打电话","d":"给 đưa người nhận lên trước động từ.","ex":[["我给爱人买了一件礼物。","Tôi mua cho vợ một món quà.","Wǒ gěi àiren mǎi le yí jiàn lǐwù."],["请给老人让个座。","Xin nhường chỗ cho người già.","Qǐng gěi lǎorén ràng ge zuò."]]}],"items":[{"zh":"爱人","py":"àiren","vi":"vợ, chồng","hv":"ái nhân","note":"Ở Trung Quốc đại lục, 爱人 là cách gọi vợ hoặc chồng, không phải \"người yêu\".","ex":"我爱人在医院工作。","exPy":"Wǒ àiren zài yīyuàn gōngzuò.","exVi":"Vợ (chồng) tôi làm ở bệnh viện.","w":"我 爱人 在 医院 工作。"},{"zh":"夫妻","py":"fūqī","vi":"vợ chồng","hv":"phu thê","note":"Chính là \"phu thê\".","ex":"他们是一对老夫妻。","exPy":"Tāmen shì yí duì lǎo fūqī.","exVi":"Họ là một đôi vợ chồng già.","w":"他们 是 一 对 老 夫妻。"},{"zh":"姐妹","py":"jiěmèi","vi":"chị em gái","hv":"tỷ muội","note":"Chính là \"tỷ muội\". Anh em trai là 兄弟.","ex":"她们是好姐妹。","exPy":"Tāmen shì hǎo jiěmèi.","exVi":"Họ là chị em thân thiết.","w":"她们 是 好 姐妹。"},{"zh":"大人","py":"dàren","vi":"người lớn","hv":"đại nhân","note":"Khác \"đại nhân\" (quan) trong tiếng Việt: 大人 là người lớn, đối lập với trẻ con.","ex":"大人说话，小孩儿别说。","exPy":"Dàren shuōhuà, xiǎoháir bié shuō.","exVi":"Người lớn nói chuyện, trẻ con đừng chen vào.","w":"大人 说话， 小孩儿 别说。"},{"zh":"老人","py":"lǎorén","vi":"người già","hv":"lão nhân","note":"Chính là \"lão nhân\".","ex":"公交车上要给老人让座。","exPy":"Gōngjiāochē shang yào gěi lǎorén ràngzuò.","exVi":"Trên xe buýt phải nhường chỗ cho người già.","w":"公交车 上 要 给 老人 让 座。"},{"zh":"男人","py":"nánrén","vi":"đàn ông","hv":"nam nhân","note":"男 + 人.","ex":"那个男人是我们的新老师。","exPy":"Nàge nánrén shì wǒmen de xīn lǎoshī.","exVi":"Người đàn ông kia là thầy giáo mới của chúng tôi.","w":"那个 男人 是 我们 的 新 老师。"},{"zh":"女人","py":"nǚrén","vi":"phụ nữ, đàn bà","hv":"nữ nhân","note":"Lịch sự hơn thì dùng 女士.","ex":"那个女人在等谁？","exPy":"Nàge nǚrén zài děng shéi?","exVi":"Người phụ nữ kia đang đợi ai?","w":"那个 女人 在 等 谁？"},{"zh":"男生","py":"nánshēng","vi":"bạn nam, nam sinh","hv":"nam sinh","note":"Dùng trong trường học cho bạn nam.","ex":"我们班女生比男生多。","exPy":"Wǒmen bān nǚshēng bǐ nánshēng duō.","exVi":"Lớp chúng tôi bạn nữ đông hơn bạn nam.","w":"我们 班 女生 比 男生 多。"},{"zh":"女生","py":"nǚshēng","vi":"bạn nữ, nữ sinh","hv":"nữ sinh","note":"Đối xứng với 男生.","ex":"女生们在唱歌。","exPy":"Nǚshēngmen zài chànggē.","exVi":"Các bạn nữ đang hát.","w":"女生 们 在 唱歌。"},{"zh":"身边","py":"shēnbiān","vi":"bên cạnh (người)","hv":"thân biên","note":"身 (thân) + 边: ngay bên mình.","ex":"身边的人对我都很好。","exPy":"Shēnbiān de rén duì wǒ dōu hěn hǎo.","exVi":"Những người quanh tôi đều rất tốt với tôi.","w":"身边 的 人 对 我 都 很 好。"}],"newChars":[],"outro":"很好！Xong bài 82."};
G.ROOMS["zh-l083"] = {"id":"zh-l083","lang":"zh","level":3,"no":83,"teacher":"wang","title":"HSK3 · Bài 83 · 放学以后 Ở trường","intro":["留学生的宿舍在校园东边。","Bài 83: Nói về lớp học, cấp hai, sách giáo khoa, bài khoá, ghi chép, từ điển, khuôn viên, du học sinh, tan học và nghỉ lễ. Bấm 1 · Học để bắt đầu."],"introPy":"Liúxuéshēng de sùshè zài xiàoyuán dōngbian.","gram":{"t":"下课 và 放学","b":"下课 = hết một tiết · 放学 = hết buổi, ra về","d":"Một ngày có nhiều lần 下课 nhưng chỉ một lần 放学.","ex":[["下课了，我们休息十分钟。","Hết tiết rồi, chúng ta nghỉ mười phút.","Xiàkè le, wǒmen xiūxi shí fēnzhōng."],["四点半放学，妈妈来接我。","Bốn rưỡi tan học, mẹ đến đón tôi.","Sì diǎn bàn fàngxué, māma lái jiē wǒ."]]},"grams":[{"t":"下课 và 放学","b":"下课 = hết một tiết · 放学 = hết buổi, ra về","d":"Một ngày có nhiều lần 下课 nhưng chỉ một lần 放学.","ex":[["下课了，我们休息十分钟。","Hết tiết rồi, chúng ta nghỉ mười phút.","Xiàkè le, wǒmen xiūxi shí fēnzhōng."],["四点半放学，妈妈来接我。","Bốn rưỡi tan học, mẹ đến đón tôi.","Sì diǎn bàn fàngxué, māma lái jiē wǒ."]]},{"t":"记 / 查 + tân ngữ","b":"记笔记 · 记生词 · 查字典","d":"Ghi nhớ hay ghi chép dùng 记; tra cứu dùng 查.","ex":[["我每天记十个生词。","Mỗi ngày tôi ghi nhớ mười từ mới.","Wǒ měi tiān jì shí ge shēngcí."],["这个词我查了字典。","Từ này tôi đã tra từ điển.","Zhège cí wǒ chá le zìdiǎn."]]}],"items":[{"zh":"班级","py":"bānjí","vi":"lớp học (tập thể lớp)","hv":"ban cấp","note":"Trang trọng hơn 班.","ex":"我们班级有三十个学生。","exPy":"Wǒmen bānjí yǒu sānshí ge xuésheng.","exVi":"Lớp chúng tôi có ba mươi học sinh.","w":"我们 班级 有 三 十 个 学生。"},{"zh":"初中","py":"chūzhōng","vi":"trung học cơ sở, cấp hai","hv":"sơ trung","note":"初 = \"sơ\" trong \"sơ cấp\". Cấp ba là 高中.","ex":"我弟弟在上初中。","exPy":"Wǒ dìdi zài shàng chūzhōng.","exVi":"Em trai tôi đang học cấp hai.","w":"我 弟弟 在 上 初中。"},{"zh":"课本","py":"kèběn","vi":"sách giáo khoa","hv":"khoá bản","note":"课 (bài học) + 本 (sách).","ex":"请打开课本。","exPy":"Qǐng dǎkāi kèběn.","exVi":"Mời mở sách giáo khoa.","w":"请 打开 课本。"},{"zh":"课文","py":"kèwén","vi":"bài khoá, bài đọc","hv":"khoá văn","note":"课 + 文 (văn).","ex":"课文里有很多新词。","exPy":"Kèwén lǐ yǒu hěn duō xīn cí.","exVi":"Trong bài khoá có nhiều từ mới.","w":"课文 里 有 很 多 新 词。"},{"zh":"笔记","py":"bǐjì","vi":"ghi chép, vở ghi","hv":"bút ký","note":"Chính là \"bút ký\". Ghi chép là 记笔记.","ex":"你的笔记能借我看看吗？","exPy":"Nǐ de bǐjì néng jiè wǒ kànkan ma?","exVi":"Cho tôi mượn vở ghi của bạn xem được không?","w":"你 的 笔记 能 借 我 看 看 吗？"},{"zh":"字典","py":"zìdiǎn","vi":"từ điển (tra chữ)","hv":"tự điển","note":"Chính là \"tự điển\". 词典 là từ điển tra từ.","ex":"不认识的字可以查字典。","exPy":"Bú rènshi de zì kěyǐ chá zìdiǎn.","exVi":"Chữ không biết có thể tra từ điển.","w":"不 认识 的 字 可以 查 字典。"},{"zh":"校园","py":"xiàoyuán","vi":"khuôn viên trường","hv":"hiệu viên","note":"校 (trường, \"hiệu\" trong \"hiệu trưởng\") + 园.","ex":"留学生的宿舍在校园东边。","exPy":"Liúxuéshēng de sùshè zài xiàoyuán dōngbian.","exVi":"Ký túc xá du học sinh ở phía đông khuôn viên trường.","w":"留学生 的 宿舍 在 校园 东 边。"},{"zh":"留学生","py":"liúxuéshēng","vi":"du học sinh","hv":"lưu học sinh","note":"Chính là \"lưu học sinh\".","ex":"这个大学有很多留学生。","exPy":"Zhège dàxué yǒu hěn duō liúxuéshēng.","exVi":"Trường đại học này có nhiều du học sinh.","w":"这个 大学 有 很 多 留学生。"},{"zh":"放学","py":"fàngxué","vi":"tan học (cả trường)","hv":"phóng học","note":"放 = thả. Khác 下课 (hết một tiết), 放学 là hết buổi học, ra về.","ex":"放学以后我去踢足球。","exPy":"Fàngxué yǐhòu wǒ qù tī zúqiú.","exVi":"Tan học tôi đi đá bóng.","w":"放学 以后 我 去 踢足球。"},{"zh":"放假","py":"fàngjià","vi":"được nghỉ (lễ, hè)","hv":"phóng giả","note":"假 (jià) = kỳ nghỉ. Nghỉ hè là 放暑假.","ex":"放假的时候你想去哪儿？","exPy":"Fàngjià de shíhou nǐ xiǎng qù nǎr?","exVi":"Kỳ nghỉ bạn muốn đi đâu?","w":"放假 的 时候 你 想 去 哪儿？"}],"newChars":["初"],"outro":"很好！Xong bài 83."};
G.ROOMS["zh-l084"] = {"id":"zh-l084","lang":"zh","level":3,"no":84,"teacher":"wang","title":"HSK3 · Bài 84 · 练汉语 Luyện ngoại ngữ","intro":["学外语要多练多说。","Bài 84: Nói về luyện tập, ghi nhớ, tra cứu, chọn lựa, câu, ngoại ngữ, hiểu biết và hứng thú. Bấm 1 · Học để bắt đầu."],"introPy":"Xué wàiyǔ yào duō liàn duō shuō.","gram":{"t":"对 + đối tượng + 有兴趣","b":"对 A 有兴趣 / 感兴趣","d":"Đối tượng đứng giữa 对 và 有兴趣, khác tiếng Việt \"có hứng thú với A\".","ex":[["他对足球没有兴趣。","Anh ấy không có hứng thú với bóng đá.","Tā duì zúqiú méiyǒu xìngqù."],["你对什么有兴趣？","Bạn có hứng thú với cái gì?","Nǐ duì shénme yǒu xìngqù?"]]},"grams":[{"t":"对 + đối tượng + 有兴趣","b":"对 A 有兴趣 / 感兴趣","d":"Đối tượng đứng giữa 对 và 有兴趣, khác tiếng Việt \"có hứng thú với A\".","ex":[["他对足球没有兴趣。","Anh ấy không có hứng thú với bóng đá.","Tā duì zúqiú méiyǒu xìngqù."],["你对什么有兴趣？","Bạn có hứng thú với cái gì?","Nǐ duì shénme yǒu xìngqù?"]]},{"t":"Động từ + 住: giữ chắc kết quả","b":"记住 · 拿住 · 站住","d":"住 sau động từ cho biết kết quả được giữ chắc, không mất.","ex":[["这些生词你要记住。","Những từ mới này bạn phải nhớ kỹ.","Zhèxiē shēngcí nǐ yào jìzhù."],["站住！别跑！","Đứng lại! Đừng chạy!","Zhànzhù! Bié pǎo!"]]}],"items":[{"zh":"练","py":"liàn","vi":"luyện, tập","hv":"luyện","note":"Chính là \"luyện\". 练习 là luyện tập; 练 đi một mình gọn hơn: 练口语.","ex":"学外语要多练多说。","exPy":"Xué wàiyǔ yào duō liàn duō shuō.","exVi":"Học ngoại ngữ phải luyện nhiều, nói nhiều.","w":"学 外语 要 多 练 多 说。"},{"zh":"记","py":"jì","vi":"nhớ; ghi","hv":"ký","note":"\"Ký\" trong \"ký ức\", \"nhật ký\". 记住 là nhớ kỹ.","ex":"你记住我的电话号码了吗？","exPy":"Nǐ jìzhù wǒ de diànhuà hàomǎ le ma?","exVi":"Bạn nhớ số điện thoại của tôi chưa?","w":"你 记 住 我 的 电话 号码 了 吗？"},{"zh":"查","py":"chá","vi":"tra, kiểm tra","hv":"tra","note":"Chính là \"tra\" trong \"tra cứu\", \"điều tra\".","ex":"我在网上查了一下。","exPy":"Wǒ zài wǎngshang chá le yíxià.","exVi":"Tôi đã tra trên mạng một chút.","w":"我 在 网上 查 了 一下。"},{"zh":"选","py":"xuǎn","vi":"chọn","hv":"tuyển","note":"\"Tuyển\" trong \"tuyển chọn\", \"tuyển thủ\".","ex":"你选哪个？","exPy":"Nǐ xuǎn nǎge?","exVi":"Bạn chọn cái nào?","w":"你 选 哪个？"},{"zh":"句","py":"jù","vi":"câu (lượng từ)","hv":"cú","note":"\"Cú\" trong \"cú pháp\". Một câu nói: 一句话.","ex":"这句话是什么意思？","exPy":"Zhè jù huà shì shénme yìsi?","exVi":"Câu này nghĩa là gì?","w":"这 句 话 是 什么 意思？"},{"zh":"外语","py":"wàiyǔ","vi":"ngoại ngữ","hv":"ngoại ngữ","note":"Chính là \"ngoại ngữ\".","ex":"你会几门外语？","exPy":"Nǐ huì jǐ mén wàiyǔ?","exVi":"Bạn biết mấy ngoại ngữ?","w":"你 会 几 门 外语？"},{"zh":"懂得","py":"dǒngde","vi":"hiểu, biết (đạo lý)","hv":"đổng đắc","note":"Sâu hơn 懂: hiểu một đạo lý, biết cách làm.","ex":"他懂得怎么照顾别人。","exPy":"Tā dǒngde zěnme zhàogù biérén.","exVi":"Anh ấy biết cách chăm sóc người khác.","w":"他 懂得 怎么 照顾 别人。"},{"zh":"认得","py":"rènde","vi":"nhận ra, biết mặt","hv":"nhận đắc","note":"Gần nghĩa 认识, hay dùng cho chữ, đường, người.","ex":"这些汉字你都认得吗？","exPy":"Zhèxiē Hànzì nǐ dōu rènde ma?","exVi":"Những chữ Hán này bạn đều nhận ra chứ?","w":"这些 汉字 你 都 认得 吗？"},{"zh":"兴趣","py":"xìngqù","vi":"hứng thú, sở thích","hv":"hứng thú","note":"Chính là \"hứng thú\". 对…有兴趣 là có hứng thú với…","ex":"他对学汉语很有兴趣。","exPy":"Tā duì xué Hànyǔ hěn yǒu xìngqù.","exVi":"Anh ấy rất hứng thú với việc học tiếng Trung.","w":"他 对 学 汉语 很 有 兴趣。"},{"zh":"难题","py":"nántí","vi":"bài khó, vấn đề nan giải","hv":"nan đề","note":"难 (khó, \"nan\") + 题 (đề).","ex":"这道难题我不会做。","exPy":"Zhè dào nántí wǒ bú huì zuò.","exVi":"Bài khó này tôi không làm được.","w":"这 道 难题 我 不 会 做。"}],"newChars":[],"outro":"很好！Xong bài 84."};
G.ROOMS["zh-l085"] = {"id":"zh-l085","lang":"zh","level":3,"no":85,"teacher":"wang","title":"HSK3 · Bài 85 · 发邮件 Điện thoại và thư điện tử","intro":["手机快没电了，我要关机了。","Bài 85: Nói về điện, sách điện tử, tai nghe, bật tắt máy, gửi nhận thư, theo dõi trên mạng. Bấm 1 · Học để bắt đầu."],"introPy":"Shǒujī kuài méi diàn le, wǒ yào guānjī le.","gram":{"t":"给 + người + 发 + thư / tin","b":"给他发邮件 · 给我发信息","d":"Người nhận đứng sau 给, trước động từ 发.","ex":[["我明天给你发邮件。","Mai tôi gửi email cho bạn.","Wǒ míngtiān gěi nǐ fā yóujiàn."],["他给我发了一张照片。","Anh ấy gửi cho tôi một tấm ảnh.","Tā gěi wǒ fā le yì zhāng zhàopiàn."]]},"grams":[{"t":"给 + người + 发 + thư / tin","b":"给他发邮件 · 给我发信息","d":"Người nhận đứng sau 给, trước động từ 发.","ex":[["我明天给你发邮件。","Mai tôi gửi email cho bạn.","Wǒ míngtiān gěi nǐ fā yóujiàn."],["他给我发了一张照片。","Anh ấy gửi cho tôi một tấm ảnh.","Tā gěi wǒ fā le yì zhāng zhàopiàn."]]},{"t":"Động từ + 到: đạt được","b":"收到 · 买到 · 找到 · 看到","d":"到 sau động từ cho biết hành động đạt kết quả.","ex":[["我找到我的耳机了。","Tôi tìm thấy tai nghe rồi.","Wǒ zhǎodào wǒ de ěrjī le."],["票买到了吗？","Mua được vé chưa?","Piào mǎidào le ma?"]]}],"items":[{"zh":"电","py":"diàn","vi":"điện","hv":"điện","note":"\"Điện\" trong \"điện thoại\", \"điện ảnh\". Hết pin là 没电了.","ex":"手机快没电了，我要关机了。","exPy":"Shǒujī kuài méi diàn le, wǒ yào guānjī le.","exVi":"Điện thoại sắp hết pin, tôi phải tắt máy đây.","w":"手机 快 没 电 了， 我 要 关机 了。"},{"zh":"电子书","py":"diànzǐshū","vi":"sách điện tử","hv":"điện tử thư","note":"电子 (điện tử) + 书.","ex":"现在很多人看电子书。","exPy":"Xiànzài hěn duō rén kàn diànzǐshū.","exVi":"Bây giờ nhiều người đọc sách điện tử.","w":"现在 很 多 人 看 电子书。"},{"zh":"耳机","py":"ěrjī","vi":"tai nghe","hv":"nhĩ cơ","note":"耳 = \"nhĩ\" (tai) + 机 (máy).","ex":"坐地铁的时候我喜欢戴耳机。","exPy":"Zuò dìtiě de shíhou wǒ xǐhuan dài ěrjī.","exVi":"Lúc đi tàu điện ngầm tôi thích đeo tai nghe.","w":"坐 地铁 的 时候 我 喜欢 戴 耳机。"},{"zh":"开机","py":"kāijī","vi":"bật máy, mở máy","hv":"khai cơ","note":"开 + 机. Ngược lại là 关机.","ex":"请先开机。","exPy":"Qǐng xiān kāijī.","exVi":"Xin hãy bật máy trước.","w":"请 先 开机。"},{"zh":"关机","py":"guānjī","vi":"tắt máy","hv":"quan cơ","note":"关 = đóng, tắt.","ex":"上课的时候请关机。","exPy":"Shàngkè de shíhou qǐng guānjī.","exVi":"Trong giờ học xin tắt máy.","w":"上课 的 时候 请 关机。"},{"zh":"邮件","py":"yóujiàn","vi":"thư, email","hv":"bưu kiện","note":"Tiếng Việt \"bưu kiện\" là gói hàng; trong tiếng Trung hiện đại 邮件 thường là email (电子邮件).","ex":"收到邮件以后请回复我。","exPy":"Shōudào yóujiàn yǐhòu qǐng huífù wǒ.","exVi":"Nhận được email xin trả lời tôi.","w":"收到 邮件 以后 请 回复 我。"},{"zh":"邮箱","py":"yóuxiāng","vi":"hộp thư; địa chỉ email","hv":"bưu tương","note":"邮 (bưu) + 箱 (hòm).","ex":"你的邮箱是什么？","exPy":"Nǐ de yóuxiāng shì shénme?","exVi":"Email của bạn là gì?","w":"你 的 邮箱 是 什么？"},{"zh":"发","py":"fā","vi":"gửi; phát ra","hv":"phát","note":"\"Phát\" trong \"phát thư\", \"phát biểu\". Gửi tin nhắn: 发短信, 发微信.","ex":"到了以后给我发个信息。","exPy":"Dào le yǐhòu gěi wǒ fā ge xìnxī.","exVi":"Đến nơi thì nhắn tin cho tôi nhé.","w":"到 了 以后 给 我 发 个 信息。"},{"zh":"收到","py":"shōudào","vi":"nhận được","hv":"thu đáo","note":"收 (thu nhận) + 到 (tới). Trả lời \"đã nhận\" ngắn gọn: 收到.","ex":"你的邮件我收到了。","exPy":"Nǐ de yóujiàn wǒ shōudào le.","exVi":"Email của bạn tôi nhận được rồi.","w":"你 的 邮件 我 收到 了。"},{"zh":"关注","py":"guānzhù","vi":"theo dõi, quan tâm","hv":"quan chú","note":"Trên mạng xã hội, bấm theo dõi là 关注.","ex":"我关注了很多学汉语的账号。","exPy":"Wǒ guānzhù le hěn duō xué Hànyǔ de zhànghào.","exVi":"Tôi theo dõi rất nhiều tài khoản học tiếng Trung.","w":"我 关注 了 很 多 学 汉语 的 账号。"}],"newChars":["收"],"outro":"很好！Xong bài 85."};
G.ROOMS["zh-l086"] = {"id":"zh-l086","lang":"zh","level":3,"no":86,"teacher":"wang","title":"HSK3 · Bài 86 · 叫外卖 Mua sắm và ăn uống","intro":["我想要一杯咖啡，加冰，不加糖。","Bài 86: Nói về thẻ, thẻ ngân hàng, đồ ăn giao tận nơi, mì gói, cân, thêm, chai, giấy, rượu và kem. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ xiǎng yào yì bēi kāfēi, jiā bīng, bù jiā táng.","gram":{"t":"Hỏi giá theo đơn vị","b":"多少钱一斤 / 一瓶 / 一个？","d":"Người Trung Quốc đặt giá trước, đơn vị sau: 多少钱一斤 (bao nhiêu tiền một cân).","ex":[["这种水多少钱一瓶？","Loại nước này bao nhiêu tiền một chai?","Zhè zhǒng shuǐ duōshao qián yì píng?"],["鸡蛋五块钱一斤。","Trứng năm tệ một cân.","Jīdàn wǔ kuài qián yì jīn."]]},"grams":[{"t":"Hỏi giá theo đơn vị","b":"多少钱一斤 / 一瓶 / 一个？","d":"Người Trung Quốc đặt giá trước, đơn vị sau: 多少钱一斤 (bao nhiêu tiền một cân).","ex":[["这种水多少钱一瓶？","Loại nước này bao nhiêu tiền một chai?","Zhè zhǒng shuǐ duōshao qián yì píng?"],["鸡蛋五块钱一斤。","Trứng năm tệ một cân.","Jīdàn wǔ kuài qián yì jīn."]]},{"t":"别总 + động từ","b":"别总 + 吃 / 玩 / 说","d":"总 là \"suốt, lúc nào cũng\". 别总… nghĩa là \"đừng cứ… mãi\".","ex":[["别总玩手机。","Đừng chơi điện thoại suốt thế.","Bié zǒng wán shǒujī."],["你别总说\"不行\"。","Bạn đừng cứ nói \"không được\" mãi.","Nǐ bié zǒng shuō \"bù xíng\"."]]}],"items":[{"zh":"卡","py":"kǎ","vi":"thẻ","hv":"ca","note":"Mượn âm tiếng Anh \"card\". Thẻ xe buýt 公交卡, thẻ ngân hàng 银行卡.","ex":"这里可以用银行卡吗？","exPy":"Zhèlǐ kěyǐ yòng yínhángkǎ ma?","exVi":"Ở đây dùng thẻ ngân hàng được không?","w":"这里 可以 用 银行卡 吗？"},{"zh":"银行卡","py":"yínhángkǎ","vi":"thẻ ngân hàng","hv":"ngân hàng ca","note":"银行 + 卡.","ex":"我的银行卡找不到了。","exPy":"Wǒ de yínhángkǎ zhǎo bu dào le.","exVi":"Tôi không tìm thấy thẻ ngân hàng.","w":"我 的 银行卡 找 不 到 了。"},{"zh":"外卖","py":"wàimài","vi":"đồ ăn mang về, giao đồ ăn","hv":"ngoại mại","note":"Nghĩa đen \"bán ra ngoài\". Gọi đồ ăn là 点外卖 hoặc 叫外卖.","ex":"外卖三十分钟就到。","exPy":"Wàimài sānshí fēnzhōng jiù dào.","exVi":"Đồ ăn ba mươi phút là tới.","w":"外卖 三 十分 钟 就 到。"},{"zh":"方便面","py":"fāngbiànmiàn","vi":"mì ăn liền","hv":"phương tiện diện","note":"Nghĩa đen \"mì tiện lợi\". 方便 = tiện lợi.","ex":"别总吃方便面。","exPy":"Bié zǒng chī fāngbiànmiàn.","exVi":"Đừng ăn mì gói suốt.","w":"别 总 吃 方便面。"},{"zh":"斤","py":"jīn","vi":"cân (nửa ký)","hv":"cân","note":"Chú ý: 一斤 = 500 gam, không phải 1 kg. Một ký là 一公斤.","ex":"我买了两斤苹果。","exPy":"Wǒ mǎi le liǎng jīn píngguǒ.","exVi":"Tôi mua hai cân táo.","w":"我 买 了 两 斤 苹果。"},{"zh":"加","py":"jiā","vi":"thêm, cộng","hv":"gia","note":"\"Gia\" trong \"gia tăng\". 加冰 (thêm đá), 加油 (cố lên).","ex":"我想要一杯咖啡，加冰，不加糖。","exPy":"Wǒ xiǎng yào yì bēi kāfēi, jiā bīng, bù jiā táng.","exVi":"Tôi muốn một cốc cà phê, thêm đá, không đường.","w":"我 想 要 一 杯 咖啡， 加 冰， 不 加 糖。"},{"zh":"瓶子","py":"píngzi","vi":"cái chai, cái lọ","hv":"bình tử","note":"瓶 = \"bình\". Làm lượng từ: 一瓶水.","ex":"这个瓶子是空的。","exPy":"Zhège píngzi shì kōng de.","exVi":"Cái chai này rỗng.","w":"这个 瓶子 是 空 的。"},{"zh":"纸","py":"zhǐ","vi":"giấy","hv":"chỉ","note":"Có bộ 纟 (sợi): giấy xưa làm từ sợi. Đếm bằng 张: 一张纸.","ex":"给我一张纸，我写一下。","exPy":"Gěi wǒ yì zhāng zhǐ, wǒ xiě yíxià.","exVi":"Đưa tôi một tờ giấy, tôi viết chút.","w":"给 我 一 张 纸， 我 写 一下。"},{"zh":"酒","py":"jiǔ","vi":"rượu","hv":"tửu","note":"\"Tửu\" trong \"tửu lượng\". Bia là 啤酒, rượu vang là 葡萄酒.","ex":"开车不能喝酒。","exPy":"Kāichē bù néng hē jiǔ.","exVi":"Lái xe không được uống rượu.","w":"开车 不 能 喝 酒。"},{"zh":"冰激凌","py":"bīngjīlíng","vi":"kem (ăn)","hv":"băng kích lăng","note":"Phiên âm từ \"ice cream\", có chữ 冰 (băng).","ex":"夏天我最喜欢吃冰激凌。","exPy":"Xiàtiān wǒ zuì xǐhuan chī bīngjīlíng.","exVi":"Mùa hè tôi thích ăn kem nhất.","w":"夏天 我 最 喜欢 吃 冰激凌。"}],"newChars":["瓶","激","凌"],"outro":"很好！Xong bài 86."};
G.ROOMS["zh-l087"] = {"id":"zh-l087","lang":"zh","level":3,"no":87,"teacher":"wang","title":"HSK3 · Bài 87 · 带好行李 Quần áo và đồ đạc","intro":["这间屋子不大，但是很干净。","Bài 87: Nói về áo khoác, áo, quần đùi, áo mưa, nhà cửa, phòng, máy giặt, vali và hành lý. Bấm 1 · Học để bắt đầu."],"introPy":"Zhè jiān wūzi bú dà, dànshì hěn gānjìng.","gram":{"t":"穿 + quần áo · 戴 + phụ kiện","b":"穿大衣 / 短裤 · 戴帽子 / 眼镜 / 耳机","d":"Mặc quần áo dùng 穿; đeo đội đồ phụ kiện dùng 戴.","ex":[["他穿着大衣，戴着帽子。","Anh ấy mặc áo khoác, đội mũ.","Tā chuān zhe dàyī, dài zhe màozi."],["出门别忘了穿雨衣。","Ra ngoài đừng quên mặc áo mưa.","Chūmén bié wàng le chuān yǔyī."]]},"grams":[{"t":"穿 + quần áo · 戴 + phụ kiện","b":"穿大衣 / 短裤 · 戴帽子 / 眼镜 / 耳机","d":"Mặc quần áo dùng 穿; đeo đội đồ phụ kiện dùng 戴.","ex":[["他穿着大衣，戴着帽子。","Anh ấy mặc áo khoác, đội mũ.","Tā chuān zhe dàyī, dài zhe màozi."],["出门别忘了穿雨衣。","Ra ngoài đừng quên mặc áo mưa.","Chūmén bié wàng le chuān yǔyī."]]},{"t":"Động từ + 好: làm xong, ổn thoả","b":"带好 · 准备好 · 收拾好","d":"好 sau động từ nghĩa là đã làm xong, đâu vào đấy.","ex":[["行李我已经准备好了。","Hành lý tôi đã chuẩn bị xong.","Xíngli wǒ yǐjīng zhǔnbèi hǎo le."],["请坐好，我们要开车了。","Mời ngồi yên, chúng ta sắp chạy rồi.","Qǐng zuò hǎo, wǒmen yào kāichē le."]]}],"items":[{"zh":"大衣","py":"dàyī","vi":"áo khoác dài","hv":"đại y","note":"大 + 衣 (áo). Áo khoác ngắn là 外套.","ex":"冬天要穿大衣，夏天穿短裤。","exPy":"Dōngtiān yào chuān dàyī, xiàtiān chuān duǎnkù.","exVi":"Mùa đông phải mặc áo khoác, mùa hè mặc quần đùi.","w":"冬天 要 穿 大衣， 夏天 穿 短裤。"},{"zh":"上衣","py":"shàngyī","vi":"áo (phần trên)","hv":"thượng y","note":"上 (trên) + 衣. Đối lập với 裤子 (quần).","ex":"这件上衣很好看。","exPy":"Zhè jiàn shàngyī hěn hǎokàn.","exVi":"Chiếc áo này rất đẹp.","w":"这 件 上衣 很 好看。"},{"zh":"短裤","py":"duǎnkù","vi":"quần đùi, quần soóc","hv":"đoản khố","note":"短 (ngắn, \"đoản\") + 裤 (quần).","ex":"夏天我常穿短裤。","exPy":"Xiàtiān wǒ cháng chuān duǎnkù.","exVi":"Mùa hè tôi hay mặc quần đùi.","w":"夏天 我 常 穿 短裤。"},{"zh":"雨衣","py":"yǔyī","vi":"áo mưa","hv":"vũ y","note":"雨 + 衣. Người Việt đi xe máy ngày mưa đều cần 雨衣.","ex":"下雨了，快穿雨衣。","exPy":"Xià yǔ le, kuài chuān yǔyī.","exVi":"Mưa rồi, mặc áo mưa nhanh lên.","w":"下雨 了， 快 穿 雨衣。"},{"zh":"房子","py":"fángzi","vi":"căn nhà","hv":"phòng tử","note":"房 = nhà, phòng. Mua nhà là 买房子.","ex":"我们想买一套大一点儿的房子。","exPy":"Wǒmen xiǎng mǎi yí tào dà yìdiǎnr de fángzi.","exVi":"Chúng tôi muốn mua một căn nhà rộng hơn chút.","w":"我们 想 买 一 套 大 一点儿 的 房子。"},{"zh":"屋子","py":"wūzi","vi":"căn phòng, gian nhà","hv":"ốc tử","note":"屋 = \"ốc\" trong \"ốc xá\" (nhà cửa).","ex":"这间屋子不大，但是很干净。","exPy":"Zhè jiān wūzi bú dà, dànshì hěn gānjìng.","exVi":"Căn phòng này không rộng, nhưng rất sạch.","w":"这 间 屋子 不 大， 但是 很 干净。"},{"zh":"室","py":"shì","vi":"phòng","hv":"thất","note":"\"Thất\" trong \"giáo thất\", \"phòng thất\". Ghép: 教室 (lớp học), 办公室 (văn phòng).","ex":"老师在办公室。","exPy":"Lǎoshī zài bàngōngshì.","exVi":"Thầy giáo ở văn phòng.","w":"老师 在 办公室。"},{"zh":"洗衣机","py":"xǐyījī","vi":"máy giặt","hv":"tẩy y cơ","note":"洗 (giặt) + 衣 (quần áo) + 机 (máy).","ex":"洗衣机坏了。","exPy":"Xǐyījī huài le.","exVi":"Máy giặt hỏng rồi.","w":"洗衣机 坏 了。"},{"zh":"箱子","py":"xiāngzi","vi":"cái hòm, vali","hv":"tương tử","note":"箱 = hòm. Vali kéo là 行李箱.","ex":"这个箱子太重了。","exPy":"Zhège xiāngzi tài zhòng le.","exVi":"Cái vali này nặng quá.","w":"这个 箱子 太 重 了。"},{"zh":"行李","py":"xíngli","vi":"hành lý","hv":"hành lý","note":"Chính là \"hành lý\".","ex":"我的行李箱是黑色的。","exPy":"Wǒ de xínglixiāng shì hēisè de.","exVi":"Vali của tôi màu đen.","w":"我 的 行李箱 是 黑色 的。"}],"newChars":["屋"],"outro":"很好！Xong bài 87."};
G.ROOMS["zh-l088"] = {"id":"zh-l088","lang":"zh","level":3,"no":88,"teacher":"wang","title":"HSK3 · Bài 88 · 前天和后天 Hôm kia, ngày kia","intro":["好久不见，你最近怎么样？","Bài 88: Nói các ngày, các năm trước sau, khoảng thời gian dài ngắn, ngày làm việc và năm mới. Bấm 1 · Học để bắt đầu."],"introPy":"Hǎojiǔ bú jiàn, nǐ zuìjìn zěnmeyàng?","gram":{"t":"Dãy ngày và dãy năm","b":"前天 · 昨天 · 今天 · 明天 · 后天 / 前年 · 去年 · 今年 · 明年 · 后年","d":"Học theo dãy cho dễ nhớ. Chú ý \"năm ngoái\" là 去年, không phải 昨年.","ex":[["去年我在上海，今年在北京。","Năm ngoái tôi ở Thượng Hải, năm nay ở Bắc Kinh.","Qùnián wǒ zài Shànghǎi, jīnnián zài Běijīng."],["我们后天见。","Ngày kia chúng ta gặp nhé.","Wǒmen hòutiān jiàn."]]},"grams":[{"t":"Dãy ngày và dãy năm","b":"前天 · 昨天 · 今天 · 明天 · 后天 / 前年 · 去年 · 今年 · 明年 · 后年","d":"Học theo dãy cho dễ nhớ. Chú ý \"năm ngoái\" là 去年, không phải 昨年.","ex":[["去年我在上海，今年在北京。","Năm ngoái tôi ở Thượng Hải, năm nay ở Bắc Kinh.","Qùnián wǒ zài Shànghǎi, jīnnián zài Běijīng."],["我们后天见。","Ngày kia chúng ta gặp nhé.","Wǒmen hòutiān jiàn."]]},{"t":"Động từ + khoảng thời gian","b":"等了半天 · 学了两年 · 睡了八个小时","d":"Thời lượng đứng SAU động từ, khác mốc thời gian đứng trước động từ.","ex":[["我学了三年汉语。","Tôi đã học tiếng Trung ba năm.","Wǒ xué le sān nián Hànyǔ."],["他睡了好久。","Anh ấy ngủ rất lâu.","Tā shuì le hǎojiǔ."]]}],"items":[{"zh":"前天","py":"qiántiān","vi":"hôm kia","hv":"tiền thiên","note":"前 (trước) + 天. Hôm qua là 昨天, hôm kia là 前天.","ex":"我前天去了北京。","exPy":"Wǒ qiántiān qù le Běijīng.","exVi":"Hôm kia tôi đi Bắc Kinh.","w":"我 前天 去 了 北京。"},{"zh":"后天","py":"hòutiān","vi":"ngày kia","hv":"hậu thiên","note":"后 (sau) + 天. Ngày mai là 明天, ngày kia là 后天.","ex":"后天是我的生日。","exPy":"Hòutiān shì wǒ de shēngrì.","exVi":"Ngày kia là sinh nhật tôi.","w":"后天 是 我 的 生日。"},{"zh":"前年","py":"qiánnián","vi":"năm kia","hv":"tiền niên","note":"Năm ngoái là 去年, năm kia là 前年.","ex":"我前年来的中国。","exPy":"Wǒ qiánnián lái de Zhōngguó.","exVi":"Tôi đến Trung Quốc từ năm kia.","w":"我 前年 来 的 中国。"},{"zh":"后年","py":"hòunián","vi":"năm kia (tương lai), hai năm nữa","hv":"hậu niên","note":"Năm sau là 明年, hai năm nữa là 后年.","ex":"后年我就大学毕业了。","exPy":"Hòunián wǒ jiù dàxué bìyè le.","exVi":"Hai năm nữa tôi tốt nghiệp đại học.","w":"后年 我 就 大学 毕业 了。"},{"zh":"半天","py":"bàntiān","vi":"nửa ngày; mãi, lâu lắm","hv":"bán thiên","note":"Ngoài nghĩa \"nửa ngày\", khẩu ngữ còn dùng để than \"lâu lắm\": 等了半天.","ex":"我等了你半天了！","exPy":"Wǒ děng le nǐ bàntiān le!","exVi":"Tôi đợi bạn mãi rồi đấy!","w":"我 等 了 你 半天 了！"},{"zh":"好久","py":"hǎojiǔ","vi":"rất lâu","hv":"hảo cửu","note":"好 ở đây là \"rất\". Câu chào quen thuộc: 好久不见 (lâu lắm không gặp).","ex":"好久不见，你最近怎么样？","exPy":"Hǎojiǔ bú jiàn, nǐ zuìjìn zěnmeyàng?","exVi":"Lâu lắm không gặp, dạo này bạn thế nào?","w":"好久 不见， 你 最近 怎么样？"},{"zh":"不久","py":"bùjiǔ","vi":"không lâu, chẳng bao lâu","hv":"bất cửu","note":"久 = \"cửu\" trong \"vĩnh cửu\". 不久以后 là \"không lâu sau\".","ex":"不久以后他就回来了。","exPy":"Bùjiǔ yǐhòu tā jiù huílai le.","exVi":"Không lâu sau anh ấy đã quay về.","w":"不久 以后 他 就 回来 了。"},{"zh":"刚刚","py":"gānggāng","vi":"vừa mới","hv":"cương cương","note":"Nhấn mạnh hơn 刚: vừa xong ngay lúc nãy.","ex":"我刚刚吃完饭。","exPy":"Wǒ gānggāng chī wán fàn.","exVi":"Tôi vừa ăn cơm xong.","w":"我 刚刚 吃 完 饭。"},{"zh":"工作日","py":"gōngzuòrì","vi":"ngày làm việc","hv":"công tác nhật","note":"工作 + 日 (ngày). Cuối tuần là 周末.","ex":"工作日我很忙，周末才有时间。","exPy":"Gōngzuòrì wǒ hěn máng, zhōumò cái yǒu shíjiān.","exVi":"Ngày thường tôi bận, cuối tuần mới có thời gian.","w":"工作日 我 很 忙， 周末 才 有时 间。"},{"zh":"新年","py":"xīnnián","vi":"năm mới","hv":"tân niên","note":"Chúc mừng năm mới: 新年快乐.","ex":"新年的时候，我们全家一起吃饭。","exPy":"Xīnnián de shíhou, wǒmen quán jiā yìqǐ chīfàn.","exVi":"Dịp năm mới, cả nhà chúng tôi cùng ăn cơm.","w":"新年 的 时候， 我们 全 家 一起 吃 饭。"}],"newChars":[],"outro":"很好！Xong bài 88."};
G.ROOMS["zh-l089"] = {"id":"zh-l089","lang":"zh","level":3,"no":89,"teacher":"wang","title":"HSK3 · Bài 89 · 过节 Lễ hội và tụ họp","intro":["中秋节你们怎么过节？","Bài 89: Nói về đón lễ, dạ hội, mời khách, làm khách, họp, kỳ nghỉ, đại hội thể thao, du khách, và làm cùng nhau. Bấm 1 · Học để bắt đầu."],"introPy":"Zhōngqiū Jié nǐmen zěnme guòjié?","gram":{"t":"欢迎 + người + động từ","b":"欢迎你来做客 · 欢迎大家参加","d":"Mời ai đến làm gì một cách lịch sự.","ex":[["欢迎大家来参加晚会。","Hoan nghênh mọi người đến dự buổi liên hoan.","Huānyíng dàjiā lái cānjiā wǎnhuì."],["欢迎你再来。","Mời bạn lại đến nhé.","Huānyíng nǐ zài lái."]]},"grams":[{"t":"欢迎 + người + động từ","b":"欢迎你来做客 · 欢迎大家参加","d":"Mời ai đến làm gì một cách lịch sự.","ex":[["欢迎大家来参加晚会。","Hoan nghênh mọi người đến dự buổi liên hoan.","Huānyíng dàjiā lái cānjiā wǎnhuì."],["欢迎你再来。","Mời bạn lại đến nhé.","Huānyíng nǐ zài lái."]]},{"t":"Chủ ngữ + 在 + động từ: đang","b":"他在开会 · 我在吃饭","d":"在 đứng trước động từ để nói việc đang diễn ra.","ex":[["老师在上课，不能接电话。","Thầy đang dạy, không nghe điện thoại được.","Lǎoshī zài shàngkè, bù néng jiē diànhuà."],["你在做什么？","Bạn đang làm gì?","Nǐ zài zuò shénme?"]]}],"items":[{"zh":"过节","py":"guòjié","vi":"đón lễ, ăn tết","hv":"quá tiết","note":"节 = \"tiết\" trong \"tiết Trung thu\", nghĩa là ngày lễ.","ex":"中秋节你们怎么过节？","exPy":"Zhōngqiū Jié nǐmen zěnme guòjié?","exVi":"Trung thu các bạn đón lễ thế nào?","w":"中 秋 节 你们 怎么 过节？"},{"zh":"晚会","py":"wǎnhuì","vi":"dạ hội, buổi liên hoan tối","hv":"vãn hội","note":"晚 (tối) + 会 (hội).","ex":"晚会上大家唱歌跳舞。","exPy":"Wǎnhuì shang dàjiā chànggē tiàowǔ.","exVi":"Ở buổi liên hoan mọi người hát và nhảy.","w":"晚会 上 大家 唱歌 跳舞。"},{"zh":"请客","py":"qǐngkè","vi":"mời, đãi (trả tiền)","hv":"thỉnh khách","note":"Nói 今天我请客 nghĩa là \"hôm nay tôi mời, tôi trả tiền\".","ex":"今天我请客，大家别客气。","exPy":"Jīntiān wǒ qǐngkè, dàjiā bié kèqi.","exVi":"Hôm nay tôi mời, mọi người đừng khách sáo.","w":"今天 我 请客， 大家 别 客气。"},{"zh":"做客","py":"zuòkè","vi":"làm khách, đến chơi nhà","hv":"tố khách","note":"做 (làm) + 客 (khách).","ex":"周末来我家做客吧。","exPy":"Zhōumò lái wǒ jiā zuòkè ba.","exVi":"Cuối tuần đến nhà tôi chơi nhé.","w":"周末 来 我 家 做客 吧。"},{"zh":"开会","py":"kāihuì","vi":"họp","hv":"khai hội","note":"开 + 会 (cuộc họp).","ex":"经理在开会，请等一下。","exPy":"Jīnglǐ zài kāihuì, qǐng děng yíxià.","exVi":"Giám đốc đang họp, xin đợi chút.","w":"经理 在 开会， 请 等 一下。"},{"zh":"假期","py":"jiàqī","vi":"kỳ nghỉ","hv":"giả kỳ","note":"假 (nghỉ) + 期 (kỳ).","ex":"假期里游客特别多。","exPy":"Jiàqī lǐ yóukè tèbié duō.","exVi":"Trong kỳ nghỉ du khách đặc biệt đông.","w":"假期 里 游客 特别 多。"},{"zh":"休假","py":"xiūjià","vi":"nghỉ phép","hv":"hưu giả","note":"休 (nghỉ) + 假. Người đi làm nghỉ phép dùng 休假.","ex":"我下个月休假一个星期。","exPy":"Wǒ xià ge yuè xiūjià yí ge xīngqī.","exVi":"Tháng sau tôi nghỉ phép một tuần.","w":"我 下 个 月 休假 一 个 星期。"},{"zh":"运动会","py":"yùndònghuì","vi":"đại hội thể thao","hv":"vận động hội","note":"Chính là \"vận động hội\". Thế vận hội là 奥运会.","ex":"学校下周开运动会。","exPy":"Xuéxiào xià zhōu kāi yùndònghuì.","exVi":"Tuần sau trường tổ chức hội thao.","w":"学校 下 周 开 运动会。"},{"zh":"游客","py":"yóukè","vi":"du khách","hv":"du khách","note":"Chính là \"du khách\".","ex":"这里每年有很多游客。","exPy":"Zhèlǐ měi nián yǒu hěn duō yóukè.","exVi":"Ở đây mỗi năm có rất nhiều du khách.","w":"这里 每 年 有 很 多 游客。"},{"zh":"一块儿","py":"yíkuàir","vi":"cùng nhau","hv":"nhất khối nhi","note":"Khẩu ngữ phương Bắc, nghĩa như 一起.","ex":"我们一块儿去吃饭吧。","exPy":"Wǒmen yíkuàir qù chīfàn ba.","exVi":"Mình cùng đi ăn nhé.","w":"我们 一块儿 去 吃 饭 吧。"}],"newChars":[],"outro":"很好！Xong bài 89."};
G.ROOMS["zh-l090"] = {"id":"zh-l090","lang":"zh","level":3,"no":90,"teacher":"wang","title":"HSK3 · Bài 90 · 运动员 Thể thao và chụp ảnh","intro":["他是我们学校最好的运动员。","Bài 90: Nói về vận động viên, ghi điểm, sân bóng, nhà thi đấu, cầu lông, nhảy, leo, và chụp ảnh. Bấm 1 · Học để bắt đầu."],"introPy":"Tā shì wǒmen xuéxiào zuì hǎo de yùndòngyuán.","gram":{"t":"Lượng từ 场 cho trận đấu, buổi diễn","b":"一场比赛 · 一场电影 · 一场雨","d":"Sự kiện diễn ra một lần trọn vẹn dùng 场.","ex":[["这场比赛很精彩。","Trận đấu này rất hay.","Zhè chǎng bǐsài hěn jīngcǎi."],["昨天下了一场大雨。","Hôm qua có một trận mưa to.","Zuótiān xià le yì chǎng dà yǔ."]]},"grams":[{"t":"Lượng từ 场 cho trận đấu, buổi diễn","b":"一场比赛 · 一场电影 · 一场雨","d":"Sự kiện diễn ra một lần trọn vẹn dùng 场.","ex":[["这场比赛很精彩。","Trận đấu này rất hay.","Zhè chǎng bǐsài hěn jīngcǎi."],["昨天下了一场大雨。","Hôm qua có một trận mưa to.","Zuótiān xià le yì chǎng dà yǔ."]]},{"t":"Động từ ly hợp: 照相, 拍照, 跳舞","b":"照张相 · 拍张照 · 跳个舞","d":"Một số động từ hai chữ có thể tách ra, chèn lượng từ hay bổ ngữ vào giữa.","ex":[["请帮我们照张相。","Nhờ chụp giúp chúng tôi một tấm.","Qǐng bāng wǒmen zhào zhāng xiàng."],["我们去跳个舞吧。","Mình đi nhảy một bài nhé.","Wǒmen qù tiào ge wǔ ba."]]}],"items":[{"zh":"运动员","py":"yùndòngyuán","vi":"vận động viên","hv":"vận động viên","note":"Chính là \"vận động viên\".","ex":"他是我们学校最好的运动员。","exPy":"Tā shì wǒmen xuéxiào zuì hǎo de yùndòngyuán.","exVi":"Anh ấy là vận động viên giỏi nhất trường tôi.","w":"他 是 我们 学校 最好 的 运动员。"},{"zh":"得分","py":"défēn","vi":"ghi điểm; điểm số","hv":"đắc phân","note":"得 (được, \"đắc\") + 分 (điểm).","ex":"最后一分钟他得分了！","exPy":"Zuìhòu yì fēnzhōng tā défēn le!","exVi":"Phút cuối cùng anh ấy ghi điểm rồi!","w":"最后 一 分钟 他 得分 了！"},{"zh":"球场","py":"qiúchǎng","vi":"sân bóng","hv":"cầu trường","note":"球 + 场 (bãi, sân).","ex":"我们在学校球场踢球。","exPy":"Wǒmen zài xuéxiào qiúchǎng tī qiú.","exVi":"Chúng tôi đá bóng ở sân trường.","w":"我们 在 学校 球场 踢 球。"},{"zh":"体育馆","py":"tǐyùguǎn","vi":"nhà thi đấu","hv":"thể dục quán","note":"体育 (thể dục, thể thao) + 馆 (toà nhà).","ex":"体育馆里有很多人在打羽毛球。","exPy":"Tǐyùguǎn lǐ yǒu hěn duō rén zài dǎ yǔmáoqiú.","exVi":"Trong nhà thi đấu có nhiều người đang đánh cầu lông.","w":"体育馆 里 有 很 多 人 在 打 羽毛球。"},{"zh":"羽毛球","py":"yǔmáoqiú","vi":"cầu lông","hv":"vũ mao cầu","note":"羽毛 (lông vũ) + 球. Đánh cầu lông là 打羽毛球.","ex":"你会打羽毛球吗？","exPy":"Nǐ huì dǎ yǔmáoqiú ma?","exVi":"Bạn biết đánh cầu lông không?","w":"你 会 打 羽毛球 吗？"},{"zh":"跳","py":"tiào","vi":"nhảy","hv":"khiêu","note":"\"Khiêu\" trong \"khiêu vũ\". Nhảy múa là 跳舞, nhảy cao là 跳高.","ex":"他跳得很高。","exPy":"Tā tiào de hěn gāo.","exVi":"Anh ấy nhảy rất cao.","w":"他 跳 得 很 高。"},{"zh":"爬","py":"pá","vi":"bò; leo","hv":"bà","note":"Leo núi là 爬山, leo cầu thang là 爬楼梯.","ex":"我们一起去爬山吧。","exPy":"Wǒmen yìqǐ qù pá shān ba.","exVi":"Chúng ta cùng đi leo núi nhé.","w":"我们 一起 去 爬山 吧。"},{"zh":"照相","py":"zhàoxiàng","vi":"chụp ảnh","hv":"chiếu tướng","note":"照 (chiếu) + 相 (hình, \"tướng\").","ex":"这里不能照相。","exPy":"Zhèlǐ bù néng zhàoxiàng.","exVi":"Ở đây không được chụp ảnh.","w":"这里 不 能 照相。"},{"zh":"拍照","py":"pāizhào","vi":"chụp ảnh","hv":"phách chiếu","note":"Đồng nghĩa với 照相, hay dùng hơn trong khẩu ngữ hiện đại.","ex":"我们在这儿拍张照吧。","exPy":"Wǒmen zài zhèr pāi zhāng zhào ba.","exVi":"Mình chụp một tấm ở đây nhé.","w":"我们 在 这儿 拍 张 照 吧。"},{"zh":"相机","py":"xiàngjī","vi":"máy ảnh","hv":"tướng cơ","note":"照相机 nói gọn là 相机.","ex":"我的相机是新买的。","exPy":"Wǒ de xiàngjī shì xīn mǎi de.","exVi":"Máy ảnh của tôi mới mua.","w":"我 的 相机 是 新 买 的。"}],"newChars":["羽","毛","拍"],"outro":"很好！Xong bài 90."};
G.ROOMS["zh-l091"] = {"id":"zh-l091","lang":"zh","level":3,"no":91,"teacher":"wang","title":"HSK3 · Bài 91 · 住院 Sức khoẻ và việc nhà","intro":["病人要多休息。","Bài 91: Nói về bệnh nhân, nằm viện, ra viện, răng, bàn chải, chải, quét, vội, sợ, và chịu đựng. Bấm 1 · Học để bắt đầu."],"introPy":"Bìngrén yào duō xiūxi.","gram":{"t":"动词 + 一次 / 两次: số lần","b":"扫一次地 · 去过两次","d":"Số lần đứng sau động từ; với động từ ly hợp thì chen vào giữa: 刷两次牙.","ex":[["我一天刷两次牙。","Mỗi ngày tôi đánh răng hai lần.","Wǒ yì tiān shuā liǎng cì yá."],["我去过一次中国。","Tôi đã đến Trung Quốc một lần.","Wǒ qù guo yí cì Zhōngguó."]]},"grams":[{"t":"动词 + 一次 / 两次: số lần","b":"扫一次地 · 去过两次","d":"Số lần đứng sau động từ; với động từ ly hợp thì chen vào giữa: 刷两次牙.","ex":[["我一天刷两次牙。","Mỗi ngày tôi đánh răng hai lần.","Wǒ yì tiān shuā liǎng cì yá."],["我去过一次中国。","Tôi đã đến Trung Quốc một lần.","Wǒ qù guo yí cì Zhōngguó."]]},{"t":"怕 + danh từ / động từ","b":"怕冷 · 怕狗 · 怕说错","d":"Sau 怕 có thể là danh từ hoặc cả một việc.","ex":[["我怕说错，所以不敢说。","Tôi sợ nói sai nên không dám nói.","Wǒ pà shuō cuò, suǒyǐ bù gǎn shuō."],["她很怕冷。","Cô ấy rất sợ lạnh.","Tā hěn pà lěng."]]}],"items":[{"zh":"病人","py":"bìngrén","vi":"bệnh nhân","hv":"bệnh nhân","note":"Chính là \"bệnh nhân\".","ex":"病人要多休息。","exPy":"Bìngrén yào duō xiūxi.","exVi":"Bệnh nhân cần nghỉ ngơi nhiều.","w":"病人 要 多 休息。"},{"zh":"住院","py":"zhùyuàn","vi":"nằm viện","hv":"trú viện","note":"住 (ở) + 院 (viện).","ex":"他住院了三天。","exPy":"Tā zhùyuàn le sān tiān.","exVi":"Anh ấy nằm viện ba ngày.","w":"他 住院 了 三 天。"},{"zh":"出院","py":"chūyuàn","vi":"ra viện","hv":"xuất viện","note":"Chính là \"xuất viện\".","ex":"他出院以后身体好多了。","exPy":"Tā chūyuàn yǐhòu shēntǐ hǎo duō le.","exVi":"Ra viện rồi sức khoẻ anh ấy khá hơn nhiều.","w":"他 出院 以后 身体 好多 了。"},{"zh":"牙","py":"yá","vi":"răng","hv":"nha","note":"\"Nha\" trong \"nha sĩ\", \"nha khoa\". Đau răng là 牙疼.","ex":"我牙疼，要去看医生。","exPy":"Wǒ yá téng, yào qù kàn yīshēng.","exVi":"Tôi đau răng, phải đi khám.","w":"我 牙 疼， 要 去 看 医生。"},{"zh":"牙刷","py":"yáshuā","vi":"bàn chải đánh răng","hv":"nha loát","note":"牙 + 刷 (bàn chải).","ex":"我忘了带牙刷。","exPy":"Wǒ wàng le dài yáshuā.","exVi":"Tôi quên mang bàn chải đánh răng.","w":"我 忘 了 带 牙刷。"},{"zh":"刷","py":"shuā","vi":"chải, quét; quẹt","hv":"loát","note":"Đánh răng là 刷牙. Quẹt thẻ là 刷卡, lướt điện thoại là 刷手机.","ex":"早上起床先刷牙。","exPy":"Zǎoshang qǐchuáng xiān shuāyá.","exVi":"Sáng dậy đánh răng trước.","w":"早上 起床 先 刷牙。"},{"zh":"扫","py":"sǎo","vi":"quét","hv":"tảo","note":"\"Tảo\" trong \"tảo mộ\". Quét nhà là 扫地, quét mã là 扫码.","ex":"现在买东西可以扫码。","exPy":"Xiànzài mǎi dōngxi kěyǐ sǎo mǎ.","exVi":"Bây giờ mua đồ có thể quét mã.","w":"现在 买 东西 可以 扫码。"},{"zh":"急","py":"jí","vi":"vội, gấp; sốt ruột","hv":"cấp","note":"\"Cấp\" trong \"cấp cứu\", \"khẩn cấp\". 别急 là \"đừng vội\".","ex":"别急，慢慢说。","exPy":"Bié jí, mànmàn shuō.","exVi":"Đừng vội, nói từ từ.","w":"别 急， 慢 慢 说。"},{"zh":"怕","py":"pà","vi":"sợ","hv":"phạ","note":"Có bộ 忄 (tim). 怕冷 (sợ lạnh), 怕狗 (sợ chó).","ex":"别怕，我在你身边。","exPy":"Bié pà, wǒ zài nǐ shēnbiān.","exVi":"Đừng sợ, có tôi bên cạnh.","w":"别 怕， 我 在 你 身边。"},{"zh":"受","py":"shòu","vi":"chịu, bị","hv":"thụ","note":"\"Thụ\" trong \"thụ động\", \"cảm thụ\". 受伤 là bị thương.","ex":"他踢球的时候受伤了。","exPy":"Tā tī qiú de shíhou shòushāng le.","exVi":"Anh ấy bị thương lúc đá bóng.","w":"他 踢 球 的 时候 受伤 了。"}],"newChars":["受"],"outro":"很好！Xong bài 91."};
G.ROOMS["zh-l092"] = {"id":"zh-l092","lang":"zh","level":3,"no":92,"teacher":"wang","title":"HSK3 · Bài 92 · 火车晚点了 Ga tàu và chuyển nhà","intro":["火车晚点了，我们要等一会儿。","Bài 92: Nói về soát vé, tàu trễ, chuyển nhà, cầu thang, trước mặt, gặp tình cờ, và danh sách. Bấm 1 · Học để bắt đầu."],"introPy":"Huǒchē wǎndiǎn le, wǒmen yào děng yíhuìr.","gram":{"t":"从…起: bắt đầu từ","b":"从 + thời điểm + 起","d":"Đánh dấu điểm bắt đầu của một thói quen hay quy định mới.","ex":[["从下个月起，这里不能停车。","Từ tháng sau, ở đây không được đỗ xe.","Cóng xià ge yuè qǐ, zhèlǐ bù néng tíngchē."],["从今天起我不喝可乐了。","Từ hôm nay tôi không uống cola nữa.","Cóng jīntiān qǐ wǒ bù hē kělè le."]]},"grams":[{"t":"从…起: bắt đầu từ","b":"从 + thời điểm + 起","d":"Đánh dấu điểm bắt đầu của một thói quen hay quy định mới.","ex":[["从下个月起，这里不能停车。","Từ tháng sau, ở đây không được đỗ xe.","Cóng xià ge yuè qǐ, zhèlǐ bù néng tíngchē."],["从今天起我不喝可乐了。","Từ hôm nay tôi không uống cola nữa.","Cóng jīntiān qǐ wǒ bù hē kělè le."]]},{"t":"…不见了: biến mất","b":"Đồ vật + 不见了","d":"Phát hiện đồ bỗng nhiên không thấy đâu.","ex":[["我的钱包不见了。","Ví của tôi không thấy đâu rồi.","Wǒ de qiánbāo bú jiàn le."],["刚才还在这儿，怎么不见了？","Vừa nãy còn ở đây, sao lại mất rồi?","Gāngcái hái zài zhèr, zěnme bú jiàn le?"]]}],"items":[{"zh":"检票","py":"jiǎnpiào","vi":"soát vé","hv":"kiểm phiếu","note":"检 (kiểm) + 票 (vé).","ex":"火车站开始检票了。","exPy":"Huǒchēzhàn kāishǐ jiǎnpiào le.","exVi":"Ga tàu bắt đầu soát vé rồi.","w":"火车站 开始 检票 了。"},{"zh":"晚点","py":"wǎndiǎn","vi":"trễ giờ (tàu xe)","hv":"vãn điểm","note":"晚 (muộn) + 点 (giờ). Dùng cho tàu, máy bay đến muộn.","ex":"火车晚点了，我们要等一会儿。","exPy":"Huǒchē wǎndiǎn le, wǒmen yào děng yíhuìr.","exVi":"Tàu trễ rồi, chúng ta phải đợi một lúc.","w":"火车 晚点 了， 我们 要 等 一会儿。"},{"zh":"搬家","py":"bānjiā","vi":"chuyển nhà","hv":"ban gia","note":"搬 = chuyển, khiêng.","ex":"搬家很累，但是新房子很漂亮。","exPy":"Bānjiā hěn lèi, dànshì xīn fángzi hěn piàoliang.","exVi":"Chuyển nhà rất mệt, nhưng nhà mới rất đẹp.","w":"搬家 很 累， 但是 新 房子 很 漂亮。"},{"zh":"楼梯","py":"lóutī","vi":"cầu thang","hv":"lâu thê","note":"楼 (lầu) + 梯 (thang).","ex":"电梯坏了，我们走楼梯吧。","exPy":"Diàntī huài le, wǒmen zǒu lóutī ba.","exVi":"Thang máy hỏng, mình đi cầu thang nhé.","w":"电梯 坏 了， 我们 走 楼梯 吧。"},{"zh":"面前","py":"miànqián","vi":"trước mặt","hv":"diện tiền","note":"面 (mặt) + 前.","ex":"他站在我面前。","exPy":"Tā zhàn zài wǒ miànqián.","exVi":"Anh ấy đứng trước mặt tôi.","w":"他 站 在 我 面前。"},{"zh":"照","py":"zhào","vi":"chiếu; soi; chụp","hv":"chiếu","note":"\"Chiếu\" trong \"chiếu sáng\". 照镜子 là soi gương.","ex":"她在照镜子。","exPy":"Tā zài zhào jìngzi.","exVi":"Cô ấy đang soi gương.","w":"她 在 照 镜子。"},{"zh":"遇见","py":"yùjiàn","vi":"gặp (tình cờ)","hv":"ngộ kiến","note":"\"Ngộ\" trong \"hội ngộ\". Gặp không hẹn trước.","ex":"我昨天在商场遇见了老师。","exPy":"Wǒ zuótiān zài shāngchǎng yùjiàn le lǎoshī.","exVi":"Hôm qua tôi tình cờ gặp thầy ở trung tâm thương mại.","w":"我 昨天 在 商场 遇见 了 老师。"},{"zh":"不见","py":"bújiàn","vi":"không gặp; mất, không thấy","hv":"bất kiến","note":"Hai nghĩa: 好久不见 (lâu không gặp) và 我的钥匙不见了 (chìa khoá biến đâu mất).","ex":"我的手机不见了！","exPy":"Wǒ de shǒujī bú jiàn le!","exVi":"Điện thoại của tôi mất đâu rồi!","w":"我 的 手机 不见 了！"},{"zh":"起","py":"qǐ","vi":"dậy; bắt đầu từ","hv":"khởi","note":"起床 (dậy), 从明天起 (bắt đầu từ ngày mai).","ex":"从明天起，我每天跑步。","exPy":"Cóng míngtiān qǐ, wǒ měi tiān pǎobù.","exVi":"Từ mai, ngày nào tôi cũng chạy bộ.","w":"从 明天 起， 我 每 天 跑步。"},{"zh":"名单","py":"míngdān","vi":"danh sách","hv":"danh đơn","note":"名 (tên) + 单 (tờ, đơn).","ex":"请大家看一下名单。","exPy":"Qǐng dàjiā kàn yíxià míngdān.","exVi":"Mời mọi người xem qua danh sách.","w":"请 大家 看 一下 名单。"}],"newChars":[],"outro":"很好！Xong bài 92."};
G.ROOMS["zh-l093"] = {"id":"zh-l093","lang":"zh","level":3,"no":93,"teacher":"wang","title":"HSK3 · Bài 93 · 听说 Cảm nhận và thay đổi","intro":["听说那家饭店的菜很好吃。","Bài 93: Nói về thay đổi, có được, cảm thấy, trong lòng, có vẻ, tưởng rằng, nghe nói, yêu thích và nuôi. Bấm 1 · Học để bắt đầu."],"introPy":"Tīngshuō nà jiā fàndiàn de cài hěn hǎochī.","gram":{"t":"以为 và 认为","b":"以为 = tưởng (nhầm) · 认为 = cho rằng (ý kiến)","d":"Dùng 以为 khi sự thật hoá ra khác.","ex":[["我以为今天是星期五，原来是星期四。","Tôi tưởng hôm nay thứ Sáu, hoá ra là thứ Năm.","Wǒ yǐwéi jīntiān shì xīngqīwǔ, yuánlái shì xīngqīsì."],["我认为这个办法很好。","Tôi cho rằng cách này rất tốt.","Wǒ rènwéi zhège bànfǎ hěn hǎo."]]},"grams":[{"t":"以为 và 认为","b":"以为 = tưởng (nhầm) · 认为 = cho rằng (ý kiến)","d":"Dùng 以为 khi sự thật hoá ra khác.","ex":[["我以为今天是星期五，原来是星期四。","Tôi tưởng hôm nay thứ Sáu, hoá ra là thứ Năm.","Wǒ yǐwéi jīntiān shì xīngqīwǔ, yuánlái shì xīngqīsì."],["我认为这个办法很好。","Tôi cho rằng cách này rất tốt.","Wǒ rènwéi zhège bànfǎ hěn hǎo."]]},{"t":"变 / 变成 / 变得","b":"变成 + danh từ · 变得 + tính từ","d":"Thành một thứ khác dùng 变成; trở nên thế nào dùng 变得.","ex":[["他变得很瘦。","Anh ấy trở nên rất gầy.","Tā biàn de hěn shòu."],["小城变成了大城市。","Thị trấn nhỏ đã thành thành phố lớn.","Xiǎo chéng biànchéng le dà chéngshì."]]}],"items":[{"zh":"变","py":"biàn","vi":"thay đổi, biến","hv":"biến","note":"\"Biến\" trong \"biến đổi\".","ex":"这几年，我的家乡变了很多。","exPy":"Zhè jǐ nián, wǒ de jiāxiāng biàn le hěn duō.","exVi":"Mấy năm nay, quê tôi thay đổi nhiều lắm.","w":"这 几 年， 我 的 家乡 变 了 很 多。"},{"zh":"变成","py":"biànchéng","vi":"trở thành, biến thành","hv":"biến thành","note":"变 + 成 (thành).","ex":"水变成了冰。","exPy":"Shuǐ biànchéng le bīng.","exVi":"Nước biến thành băng.","w":"水 变成 了 冰。"},{"zh":"得到","py":"dédào","vi":"có được, nhận được","hv":"đắc đáo","note":"得 = \"đắc\" trong \"đắc ý\".","ex":"他得到了老师的帮助。","exPy":"Tā dédào le lǎoshī de bāngzhù.","exVi":"Anh ấy nhận được sự giúp đỡ của thầy.","w":"他 得到 了 老师 的 帮助。"},{"zh":"感到","py":"gǎndào","vi":"cảm thấy","hv":"cảm đáo","note":"感 = \"cảm\" trong \"cảm xúc\". Trang trọng hơn 觉得 một chút.","ex":"我感到很高兴。","exPy":"Wǒ gǎndào hěn gāoxìng.","exVi":"Tôi cảm thấy rất vui.","w":"我 感到 很 高兴。"},{"zh":"心里","py":"xīnlǐ","vi":"trong lòng","hv":"tâm lý","note":"Khác \"tâm lý\" tiếng Việt: 心里 là \"trong lòng, trong bụng\".","ex":"我心里一直想着这件事。","exPy":"Wǒ xīnlǐ yìzhí xiǎng zhe zhè jiàn shì.","exVi":"Trong lòng tôi cứ nghĩ mãi về chuyện này.","w":"我 心里 一直 想 着 这 件 事。"},{"zh":"看来","py":"kànlái","vi":"xem ra, có vẻ","hv":"khán lai","note":"Đầu câu để rút ra nhận định từ điều thấy được.","ex":"看来你很喜欢这个工作。","exPy":"Kànlái nǐ hěn xǐhuan zhège gōngzuò.","exVi":"Xem ra bạn rất thích công việc này.","w":"看来 你 很 喜欢 这个 工作。"},{"zh":"以为","py":"yǐwéi","vi":"tưởng (nhầm) rằng","hv":"dĩ vi","note":"Khác 认为: 以为 thường là tưởng sai.","ex":"我以为你是中国人。","exPy":"Wǒ yǐwéi nǐ shì Zhōngguó rén.","exVi":"Tôi cứ tưởng bạn là người Trung Quốc.","w":"我 以为 你 是 中国 人。"},{"zh":"听说","py":"tīngshuō","vi":"nghe nói","hv":"thính thuyết","note":"Đầu câu để kể lại điều nghe người khác nói.","ex":"听说那家饭店的菜很好吃。","exPy":"Tīngshuō nà jiā fàndiàn de cài hěn hǎochī.","exVi":"Nghe nói món ăn nhà hàng đó rất ngon.","w":"听说 那 家 饭店 的 菜 很 好吃。"},{"zh":"喜爱","py":"xǐ'ài","vi":"yêu thích","hv":"hỉ ái","note":"Trang trọng hơn 喜欢.","ex":"这本书很受年轻人喜爱。","exPy":"Zhè běn shū hěn shòu niánqīng rén xǐ'ài.","exVi":"Cuốn sách này rất được giới trẻ yêu thích.","w":"这 本 书 很 受 年轻 人 喜爱。"},{"zh":"养","py":"yǎng","vi":"nuôi","hv":"dưỡng","note":"\"Dưỡng\" trong \"nuôi dưỡng\". Nuôi chó là 养狗.","ex":"我家养了一只猫。","exPy":"Wǒ jiā yǎng le yì zhī māo.","exVi":"Nhà tôi nuôi một con mèo.","w":"我 家 养 了 一 只 猫。"}],"newChars":["养"],"outro":"很好！Xong bài 93."};
G.ROOMS["zh-l094"] = {"id":"zh-l094","lang":"zh","level":3,"no":94,"teacher":"wang","title":"HSK3 · Bài 94 · 不同的看法 Nhận xét và so sánh","intro":["南方和北方的生活很不同。","Bài 94: Khen chê xấu, khó nghe; nói nhiều, có ích, liên quan, khác nhau, cỡ to nhỏ, thường gặp, người nổi tiếng. Bấm 1 · Học để bắt đầu."],"introPy":"Nánfāng hé běifāng de shēnghuó hěn bù tóng.","gram":{"t":"跟 / 和 + A + 不同 / 一样","b":"A 跟 B 不同 · A 跟 B 一样","d":"So sánh giống hay khác: đặt B sau 跟.","ex":[["我的看法跟你不同。","Ý kiến của tôi khác bạn.","Wǒ de kànfǎ gēn nǐ bù tóng."],["他跟我一样高。","Anh ấy cao bằng tôi.","Tā gēn wǒ yíyàng gāo."]]},"grams":[{"t":"跟 / 和 + A + 不同 / 一样","b":"A 跟 B 不同 · A 跟 B 一样","d":"So sánh giống hay khác: đặt B sau 跟.","ex":[["我的看法跟你不同。","Ý kiến của tôi khác bạn.","Wǒ de kànfǎ gēn nǐ bù tóng."],["他跟我一样高。","Anh ấy cao bằng tôi.","Tā gēn wǒ yíyàng gāo."]]},{"t":"对 + người + 有用","b":"对我有用 · 对学习有用","d":"Có ích cho ai: dùng 对.","ex":[["多读书对你有用。","Đọc nhiều sách có ích cho bạn.","Duō dú shū duì nǐ yǒuyòng."],["这个软件对学汉语很有用。","Phần mềm này rất có ích cho việc học tiếng Trung.","Zhège ruǎnjiàn duì xué Hànyǔ hěn yǒuyòng."]]}],"items":[{"zh":"难看","py":"nánkàn","vi":"xấu, khó coi","hv":"nan khán","note":"难 (khó) + 看. Đối lập với 好看.","ex":"这件衣服太难看了。","exPy":"Zhè jiàn yīfu tài nánkàn le.","exVi":"Bộ quần áo này xấu quá.","w":"这 件 衣服 太 难看 了。"},{"zh":"难听","py":"nántīng","vi":"khó nghe","hv":"nan thính","note":"Đối lập với 好听. Cũng dùng cho lời nói khó nghe.","ex":"这首歌一点儿也不难听。","exPy":"Zhè shǒu gē yìdiǎnr yě bù nántīng.","exVi":"Bài hát này chẳng khó nghe chút nào.","w":"这 首 歌 一点儿 也 不 难听。"},{"zh":"好多","py":"hǎoduō","vi":"rất nhiều","hv":"hảo đa","note":"好 = rất. Khẩu ngữ, nghĩa như 很多.","ex":"我学了好多常用的句子。","exPy":"Wǒ xué le hǎoduō cháng yòng de jùzi.","exVi":"Tôi đã học rất nhiều câu thường dùng.","w":"我 学 了 好多 常用 的 句子。"},{"zh":"有用","py":"yǒuyòng","vi":"có ích","hv":"hữu dụng","note":"Chính là \"hữu dụng\". Vô ích là 没用.","ex":"这本书对我很有用。","exPy":"Zhè běn shū duì wǒ hěn yǒuyòng.","exVi":"Cuốn sách này rất có ích với tôi.","w":"这 本 书 对 我 很 有用。"},{"zh":"有关","py":"yǒuguān","vi":"có liên quan","hv":"hữu quan","note":"Chính là \"hữu quan\". 跟…有关 là \"liên quan đến…\".","ex":"这个问题跟钱有关。","exPy":"Zhège wèntí gēn qián yǒuguān.","exVi":"Vấn đề này liên quan đến tiền.","w":"这个 问题 跟 钱 有关。"},{"zh":"不同","py":"bù tóng","vi":"khác nhau","hv":"bất đồng","note":"Khác \"bất đồng\" (không đồng ý) tiếng Việt: 不同 chỉ là \"không giống\".","ex":"南方和北方的生活很不同。","exPy":"Nánfāng hé běifāng de shēnghuó hěn bù tóng.","exVi":"Cuộc sống miền Nam và miền Bắc rất khác nhau.","w":"南方 和 北方 的 生活 很 不同。"},{"zh":"大小","py":"dàxiǎo","vi":"kích cỡ","hv":"đại tiểu","note":"大 + 小 ghép thành danh từ chỉ cỡ, giống 长短, 高低.","ex":"这双鞋大小正好。","exPy":"Zhè shuāng xié dàxiǎo zhènghǎo.","exVi":"Đôi giày này vừa cỡ.","w":"这 双 鞋 大小 正好。"},{"zh":"常见","py":"cháng jiàn","vi":"thường gặp","hv":"thường kiến","note":"常 (thường) + 见 (gặp).","ex":"这是一个很常见的问题。","exPy":"Zhè shì yí ge hěn cháng jiàn de wèntí.","exVi":"Đây là một câu hỏi rất thường gặp.","w":"这 是 一 个 很 常见 的 问题。"},{"zh":"常用","py":"cháng yòng","vi":"thường dùng","hv":"thường dụng","note":"常 + 用.","ex":"这些是最常用的汉字。","exPy":"Zhèxiē shì zuì cháng yòng de Hànzì.","exVi":"Đây là những chữ Hán thường dùng nhất.","w":"这些 是 最 常用 的 汉字。"},{"zh":"名人","py":"míngrén","vi":"người nổi tiếng","hv":"danh nhân","note":"Chính là \"danh nhân\".","ex":"很多名人来过这家饭店。","exPy":"Hěn duō míngrén lái guo zhè jiā fàndiàn.","exVi":"Nhiều người nổi tiếng từng đến nhà hàng này.","w":"很 多 名人 来 过 这 家 饭店。"}],"newChars":[],"outro":"很好！Xong bài 94."};
G.ROOMS["zh-l095"] = {"id":"zh-l095","lang":"zh","level":3,"no":95,"teacher":"wang","title":"HSK3 · Bài 95 · 常常和总是 Phó từ thường dùng","intro":["你不用担心，我能做好。","Bài 95: Phân biệt thường, luôn, chỉ là, chỉ có thể, không cần, không được, nên, nhưng, hoặc. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ búyòng dānxīn, wǒ néng zuò hǎo.","gram":{"t":"或 (câu kể) và 还是 (câu hỏi)","b":"A 或 B (kể) · A 还是 B？ (hỏi)","d":"Cả hai đều nghĩa \"hoặc\", nhưng câu hỏi lựa chọn phải dùng 还是.","ex":[["你喝茶还是喝咖啡？","Bạn uống trà hay cà phê?","Nǐ hē chá háishi hē kāfēi?"],["喝茶或咖啡都可以。","Uống trà hay cà phê đều được.","Hē chá huò kāfēi dōu kěyǐ."]]},"grams":[{"t":"或 (câu kể) và 还是 (câu hỏi)","b":"A 或 B (kể) · A 还是 B？ (hỏi)","d":"Cả hai đều nghĩa \"hoặc\", nhưng câu hỏi lựa chọn phải dùng 还是.","ex":[["你喝茶还是喝咖啡？","Bạn uống trà hay cà phê?","Nǐ hē chá háishi hē kāfēi?"],["喝茶或咖啡都可以。","Uống trà hay cà phê đều được.","Hē chá huò kāfēi dōu kěyǐ."]]},{"t":"该…了: đến lúc phải","b":"该 + động từ + 了","d":"Báo đã đến giờ làm việc gì.","ex":[["该吃饭了。","Đến giờ ăn cơm rồi.","Gāi chīfàn le."],["十一点了，该睡觉了。","Mười một giờ rồi, phải đi ngủ thôi.","Shíyī diǎn le, gāi shuìjiào le."]]}],"items":[{"zh":"常","py":"cháng","vi":"thường","hv":"thường","note":"Gọn hơn 常常, nghĩa như nhau.","ex":"我常去那家咖啡馆。","exPy":"Wǒ cháng qù nà jiā kāfēiguǎn.","exVi":"Tôi hay đến quán cà phê đó.","w":"我 常 去 那 家 咖啡 馆。"},{"zh":"常常","py":"chángcháng","vi":"thường thường, hay","hv":"thường thường","note":"Chính là \"thường thường\".","ex":"他常常迟到。","exPy":"Tā chángcháng chídào.","exVi":"Anh ấy hay đến muộn.","w":"他 常常 迟到。"},{"zh":"总","py":"zǒng","vi":"luôn, lúc nào cũng","hv":"tổng","note":"Gọn hơn 总是, hay mang ý than phiền.","ex":"他总说没时间。","exPy":"Tā zǒng shuō méi shíjiān.","exVi":"Anh ấy lúc nào cũng nói không có thời gian.","w":"他 总 说 没 时间。"},{"zh":"只是","py":"zhǐshì","vi":"chỉ là; có điều","hv":"chỉ thị","note":"Khác \"chỉ thị\" tiếng Việt: 只是 là \"chỉ là\", hoặc \"có điều\" ở đầu vế sau.","ex":"这个菜很好吃，只是有点儿辣。","exPy":"Zhège cài hěn hǎochī, zhǐshì yǒudiǎnr là.","exVi":"Món này rất ngon, có điều hơi cay.","w":"这个 菜 很 好吃， 只是 有点儿 辣。"},{"zh":"只能","py":"zhǐ néng","vi":"chỉ có thể, đành","hv":"chỉ năng","note":"只 (chỉ) + 能 (có thể).","ex":"没有车了，我们只能走路回去。","exPy":"Méiyǒu chē le, wǒmen zhǐ néng zǒulù huíqu.","exVi":"Hết xe rồi, chúng ta đành đi bộ về.","w":"没有 车 了， 我们 只能 走路 回去。"},{"zh":"不用","py":"búyòng","vi":"không cần","hv":"bất dụng","note":"Đáp lại lời cảm ơn: 不用谢 (không cần cảm ơn).","ex":"你不用担心，我能做好。","exPy":"Nǐ búyòng dānxīn, wǒ néng zuò hǎo.","exVi":"Bạn không cần lo, tôi làm tốt được.","w":"你 不用 担心， 我 能 做 好。"},{"zh":"不行","py":"bùxíng","vi":"không được; kém","hv":"bất hành","note":"\"Không được phép\" hoặc \"kém, tồi\": 我的汉语还不行.","ex":"我的汉语还不行，要多练习。","exPy":"Wǒ de Hànyǔ hái bùxíng, yào duō liànxí.","exVi":"Tiếng Trung của tôi còn kém, phải luyện nhiều.","w":"我 的 汉语 还 不行， 要 多 练习。"},{"zh":"该","py":"gāi","vi":"nên, phải; đến lượt","hv":"cai","note":"Gọn hơn 应该. 该你了 là \"đến lượt bạn\".","ex":"时间不早了，我该走了。","exPy":"Shíjiān bù zǎo le, wǒ gāi zǒu le.","exVi":"Không còn sớm nữa, tôi phải đi rồi.","w":"时间 不 早 了， 我 该 走 了。"},{"zh":"可","py":"kě","vi":"nhưng; thật là","hv":"khả","note":"Như 可是 (nhưng). Trước tính từ còn để nhấn mạnh: 可好了.","ex":"我想去，可没有时间。","exPy":"Wǒ xiǎng qù, kě méiyǒu shíjiān.","exVi":"Tôi muốn đi, nhưng không có thời gian.","w":"我 想 去， 可 没有 时间。"},{"zh":"或","py":"huò","vi":"hoặc","hv":"hoặc","note":"Chính là \"hoặc\". Gọn hơn 或者, dùng trong câu kể, không dùng trong câu hỏi.","ex":"你可以坐公交车或地铁。","exPy":"Nǐ kěyǐ zuò gōngjiāochē huò dìtiě.","exVi":"Bạn có thể đi xe buýt hoặc tàu điện ngầm.","w":"你 可以 坐 公交车 或 地铁。"}],"newChars":[],"outro":"很好！Xong bài 95."};
G.ROOMS["zh-l096"] = {"id":"zh-l096","lang":"zh","level":3,"no":96,"teacher":"wang","title":"HSK3 · Bài 96 · 怎么办？ Hỏi cách làm và nối câu","intro":["车坏了，怎么办？","Bài 96: Hỏi phải làm sao, như thế nào; nói \"nếu… thì\", \"cho đến khi\", sau này, dưới, ngoài ra, cái khác, làm và lo việc. Bấm 1 · Học để bắt đầu."],"introPy":"Chē huài le, zěnme bàn?","gram":{"t":"…的话: nếu","b":"(如果) + điều kiện + 的话，+ kết quả","d":"Có thể dùng 的话 một mình hoặc đi cùng 如果. Vế sau hay có 就.","ex":[["明天下雨的话，我们就不去了。","Nếu mai mưa thì chúng ta không đi nữa.","Míngtiān xià yǔ dehuà, wǒmen jiù bú qù le."],["如果你忙的话，我自己去。","Nếu bạn bận thì tôi tự đi.","Rúguǒ nǐ máng dehuà, wǒ zìjǐ qù."]]},"grams":[{"t":"…的话: nếu","b":"(如果) + điều kiện + 的话，+ kết quả","d":"Có thể dùng 的话 một mình hoặc đi cùng 如果. Vế sau hay có 就.","ex":[["明天下雨的话，我们就不去了。","Nếu mai mưa thì chúng ta không đi nữa.","Míngtiān xià yǔ dehuà, wǒmen jiù bú qù le."],["如果你忙的话，我自己去。","Nếu bạn bận thì tôi tự đi.","Rúguǒ nǐ máng dehuà, wǒ zìjǐ qù."]]},{"t":"除了…以外，还 / 都","b":"除了 A 以外，还 B (cộng thêm) · 除了 A 以外，都 B (trừ ra)","d":"还 là \"ngoài A còn B\"; 都 là \"trừ A, tất cả đều B\".","ex":[["除了他以外，大家都来了。","Trừ anh ấy ra, mọi người đều đến rồi.","Chúle tā yǐwài, dàjiā dōu lái le."],["除了足球以外，我还喜欢篮球。","Ngoài bóng đá ra, tôi còn thích bóng rổ.","Chúle zúqiú yǐwài, wǒ hái xǐhuan lánqiú."]]}],"items":[{"zh":"怎么办","py":"zěnme bàn","vi":"làm sao bây giờ","hv":"chẩm ma biện","note":"怎么 (thế nào) + 办 (làm). Câu cửa miệng khi gặp rắc rối.","ex":"车坏了，怎么办？","exPy":"Chē huài le, zěnme bàn?","exVi":"Xe hỏng rồi, làm sao đây?","w":"车 坏 了， 怎么办？"},{"zh":"怎样","py":"zěnyàng","vi":"thế nào, ra sao","hv":"chẩm dạng","note":"Trang trọng hơn 怎么样.","ex":"你觉得这个计划怎样？","exPy":"Nǐ juéde zhège jìhuà zěnyàng?","exVi":"Bạn thấy kế hoạch này thế nào?","w":"你 觉得 这个 计划 怎样？"},{"zh":"的话","py":"dehuà","vi":"nếu… thì","hv":"đích thoại","note":"Đặt cuối vế điều kiện: 有时间的话 (nếu có thời gian).","ex":"你不喜欢这个的话，可以选别的。","exPy":"Nǐ bù xǐhuan zhège dehuà, kěyǐ xuǎn biéde.","exVi":"Nếu bạn không thích cái này thì có thể chọn cái khác.","w":"你 不 喜欢 这个 的话， 可以 选 别的。"},{"zh":"直到","py":"zhídào","vi":"mãi cho đến","hv":"trực đáo","note":"直 (thẳng) + 到 (đến).","ex":"他直到晚上十点才回家。","exPy":"Tā zhídào wǎnshang shí diǎn cái huí jiā.","exVi":"Mãi đến mười giờ tối anh ấy mới về nhà.","w":"他 直到 晚上 十 点 才 回 家。"},{"zh":"以后","py":"yǐhòu","vi":"sau này; sau khi","hv":"dĩ hậu","note":"Đứng một mình là \"sau này\"; sau một việc là \"sau khi\": 下课以后.","ex":"以后我想当医生。","exPy":"Yǐhòu wǒ xiǎng dāng yīshēng.","exVi":"Sau này tôi muốn làm bác sĩ.","w":"以后 我 想 当 医生。"},{"zh":"以下","py":"yǐxià","vi":"dưới, trở xuống; sau đây","hv":"dĩ hạ","note":"十岁以下 (từ mười tuổi trở xuống). Đầu câu: 以下 là \"sau đây\".","ex":"以下是这次考试的名单。","exPy":"Yǐxià shì zhè cì kǎoshì de míngdān.","exVi":"Sau đây là danh sách kỳ thi lần này.","w":"以下 是 这 次 考试 的 名单。"},{"zh":"以外","py":"yǐwài","vi":"ngoài ra, ngoài","hv":"dĩ ngoại","note":"除了…以外 là \"ngoài… ra\".","ex":"除了汉语以外，我还会说英语。","exPy":"Chúle Hànyǔ yǐwài, wǒ hái huì shuō Yīngyǔ.","exVi":"Ngoài tiếng Trung ra, tôi còn nói được tiếng Anh.","w":"除了 汉语 以外， 我 还 会 说 英 语。"},{"zh":"别的","py":"biéde","vi":"cái khác, khác","hv":"biệt đích","note":"别 = \"biệt\" trong \"khác biệt\".","ex":"你还要别的吗？","exPy":"Nǐ hái yào biéde ma?","exVi":"Bạn còn cần gì khác không?","w":"你 还 要 别的 吗？"},{"zh":"办","py":"bàn","vi":"làm, lo (việc)","hv":"biện","note":"\"Biện\" trong \"biện pháp\". 办事 (lo việc), 办手续 (làm thủ tục).","ex":"我去银行办点儿事。","exPy":"Wǒ qù yínháng bàn diǎnr shì.","exVi":"Tôi ra ngân hàng làm chút việc.","w":"我 去 银行 办 点 儿 事。"},{"zh":"干","py":"gàn","vi":"làm","hv":"cán","note":"Khẩu ngữ, nghĩa như 做: 你在干什么？","ex":"他每天从早干到晚。","exPy":"Tā měi tiān cóng zǎo gàn dào wǎn.","exVi":"Ngày nào anh ấy cũng làm từ sáng đến tối.","w":"他 每 天 从 早 干 到 晚。"}],"newChars":[],"outro":"很好！Xong bài 96."};
G.ROOMS["zh-l097"] = {"id":"zh-l097","lang":"zh","level":3,"no":97,"teacher":"wang","title":"HSK3 · Bài 97 · 写信 Thư từ và nghề nghiệp","intro":["现在很少有人写信了。","Bài 97: Nói về thư, phong thư, âm thanh, hoạ sĩ, phục vụ, tách ra, vườn, nhân viên, hậu tố 子, màu vàng, tán gẫu và chiều cao. Bấm 1 · Học để bắt đầu."],"introPy":"Xiànzài hěn shǎo yǒu rén xiě xìn le.","gram":{"t":"Hậu tố 员 và 家 chỉ người","b":"员 = nhân viên, người làm · 家 = chuyên gia, người có tài","d":"服务员, 运动员 là làm công việc đó; 画家, 作家 là người giỏi trong lĩnh vực.","ex":[["我哥哥是运动员，我姐姐是画家。","Anh tôi là vận động viên, chị tôi là hoạ sĩ.","Wǒ gēge shì yùndòngyuán, wǒ jiějie shì huàjiā."],["服务员，请给我一杯水。","Phục vụ ơi, cho tôi một cốc nước.","Fúwùyuán, qǐng gěi wǒ yì bēi shuǐ."]]},"grams":[{"t":"Hậu tố 员 và 家 chỉ người","b":"员 = nhân viên, người làm · 家 = chuyên gia, người có tài","d":"服务员, 运动员 là làm công việc đó; 画家, 作家 là người giỏi trong lĩnh vực.","ex":[["我哥哥是运动员，我姐姐是画家。","Anh tôi là vận động viên, chị tôi là hoạ sĩ.","Wǒ gēge shì yùndòngyuán, wǒ jiějie shì huàjiā."],["服务员，请给我一杯水。","Phục vụ ơi, cho tôi một cốc nước.","Fúwùyuán, qǐng gěi wǒ yì bēi shuǐ."]]},{"t":"边…边…: vừa… vừa…","b":"边 + động từ 1 + 边 + động từ 2","d":"Làm hai việc cùng lúc. Cũng nói 一边…一边….","ex":[["他边走边唱。","Anh ấy vừa đi vừa hát.","Tā biān zǒu biān chàng."],["我们一边吃饭一边聊天。","Chúng tôi vừa ăn cơm vừa trò chuyện.","Wǒmen yìbiān chīfàn yìbiān liáotiān."]]}],"items":[{"zh":"信","py":"xìn","vi":"thư; tin","hv":"tín","note":"\"Tín\" trong \"tín nhiệm\". Vừa là lá thư, vừa là tin tưởng: 相信.","ex":"现在很少有人写信了。","exPy":"Xiànzài hěn shǎo yǒu rén xiě xìn le.","exVi":"Bây giờ ít người viết thư lắm rồi.","w":"现在 很 少 有 人 写 信 了。"},{"zh":"封","py":"fēng","vi":"phong, lá (lượng từ cho thư)","hv":"phong","note":"\"Phong\" trong \"phong bì\". Một lá thư: 一封信.","ex":"我收到了两封邮件。","exPy":"Wǒ shōudào le liǎng fēng yóujiàn.","exVi":"Tôi nhận được hai email.","w":"我 收到 了 两 封 邮件。"},{"zh":"声","py":"shēng","vi":"tiếng, âm thanh","hv":"thanh","note":"\"Thanh\" trong \"âm thanh\", \"thanh điệu\". 大声 là to tiếng.","ex":"我听见外面有人说话的声音。","exPy":"Wǒ tīngjiàn wàimian yǒu rén shuōhuà de shēngyīn.","exVi":"Tôi nghe thấy tiếng người nói chuyện bên ngoài.","w":"我 听见 外面 有 人 说话 的 声音。"},{"zh":"画家","py":"huàjiā","vi":"hoạ sĩ","hv":"hoạ gia","note":"画 (vẽ) + 家 (nhà chuyên môn).","ex":"他是一位有名的画家。","exPy":"Tā shì yí wèi yǒumíng de huàjiā.","exVi":"Ông ấy là một hoạ sĩ nổi tiếng.","w":"他 是 一 位 有名 的 画家。"},{"zh":"服务","py":"fúwù","vi":"phục vụ","hv":"phục vụ","note":"Chính là \"phục vụ\". Nhân viên phục vụ là 服务员.","ex":"这家饭店的服务很好。","exPy":"Zhè jiā fàndiàn de fúwù hěn hǎo.","exVi":"Nhà hàng này phục vụ rất tốt.","w":"这 家 饭店 的 服务 很 好。"},{"zh":"分开","py":"fēnkāi","vi":"tách ra, chia ra","hv":"phân khai","note":"分 (chia) + 开.","ex":"我们分开走吧。","exPy":"Wǒmen fēnkāi zǒu ba.","exVi":"Chúng ta tách ra mà đi nhé.","w":"我们 分开 走 吧。"},{"zh":"园","py":"yuán","vi":"vườn","hv":"viên","note":"\"Viên\" trong \"hoa viên\", \"công viên\". Ghép: 公园, 花园, 动物园.","ex":"这个公园里有很多花。","exPy":"Zhège gōngyuán lǐ yǒu hěn duō huā.","exVi":"Công viên này có rất nhiều hoa.","w":"这个 公园 里 有 很 多 花。"},{"zh":"员","py":"yuán","vi":"nhân viên (hậu tố chỉ người)","hv":"viên","note":"\"Viên\" trong \"nhân viên\", \"đảng viên\". Ghép: 服务员, 运动员, 售货员.","ex":"我姐姐是银行职员。","exPy":"Wǒ jiějie shì yínháng zhíyuán.","exVi":"Chị tôi là nhân viên ngân hàng.","w":"我 姐姐 是 银行 职员。"},{"zh":"子","py":"zi","vi":"(hậu tố danh từ)","hv":"tử","note":"Đọc nhẹ. Gắn sau một chữ để thành danh từ: 桌子, 椅子, 本子, 箱子.","ex":"桌子上有一个杯子。","exPy":"Zhuōzi shang yǒu yí ge bēizi.","exVi":"Trên bàn có một cái cốc.","w":"桌子 上 有 一 个 杯子。"},{"zh":"黄色","py":"huángsè","vi":"màu vàng","hv":"hoàng sắc","note":"黄 = \"hoàng\" (vàng) trong \"Hoàng Hà\".","ex":"秋天树叶变成了黄色。","exPy":"Qiūtiān shùyè biànchéng le huángsè.","exVi":"Mùa thu lá cây chuyển sang màu vàng.","w":"秋天 树 叶 变成 了 黄色。"},{"zh":"聊","py":"liáo","vi":"tán gẫu, nói chuyện","hv":"liêu","note":"Hay gặp trong 聊天 (tán gẫu).","ex":"我们两个人聊了一个晚上。","exPy":"Wǒmen liǎng ge rén liáo le yí ge wǎnshang.","exVi":"Hai chúng tôi nói chuyện cả buổi tối.","w":"我们 两 个人 聊 了 一 个 晚上。"},{"zh":"身高","py":"shēngāo","vi":"chiều cao (người)","hv":"thân cao","note":"身 (thân) + 高 (cao).","ex":"他身高一米九，很适合打篮球。","exPy":"Tā shēngāo yì mǐ jiǔ, hěn shìhé dǎ lánqiú.","exVi":"Anh ấy cao một mét chín, rất hợp chơi bóng rổ.","w":"他 身高 一 米 九， 很 适合 打篮球。"}],"newChars":["封"],"outro":"很好！Xong bài 97."};
G.ZH_LOADED = G.ZH_LOADED || {}; G.ZH_LOADED["data/zh_c3.js"] = 1;
